      ac(0.095, 0.025, 0.26, 0, 0.062, -0.05);
      st(0.025, 0.03, 0.08, 0.045, 0.07, 0.02);
      muzzle.set(0, 0.02, -0.95);
      break;
    }
  }
  g.userData.muzzle = muzzle;
  g.userData.weaponId = id;
  g.traverse(o => { if (o.isMesh) { o.castShadow = true; o.userData.weapon = id; } });
  return g;
}

