import * as THREE from 'three';
import { mulberry32, clamp, lerp, noiseTexture, panelTexture, smokeTexture, canvasTexture, mergeGeometries, transformGeom, deg, rayAABB } from './utils.js';

const SIZE = 600;
const HALF = SIZE / 2;
const SEA = 0.25;

/* =========================================================================
   Static batchers — every box/cylinder in a material group is one draw call
   ========================================================================= */
class BoxBatch {
  constructor(material, opts = {}) {
    this.material = material; this.items = []; this.opts = opts;
  }
  add(w, h, d, x, y, z, color, ry = 0, rx = 0, rz = 0) {
    this.items.push({ w, h, d, x, y, z, color, rx, ry, rz });
  }
  build(parent, shadows = true) {
    if (!this.items.length) return null;
    const geo = new THREE.BoxGeometry(1, 1, 1);
    const mesh = new THREE.InstancedMesh(geo, this.material, this.items.length);
    const m = new THREE.Matrix4(), q = new THREE.Quaternion(), e = new THREE.Euler(), v = new THREE.Vector3(), s = new THREE.Vector3();
    const col = new THREE.Color();
    this.items.forEach((it, i) => {
      e.set(it.rx, it.ry, it.rz); q.setFromEuler(e);
      v.set(it.x, it.y, it.z); s.set(it.w, it.h, it.d);
      m.compose(v, q, s); mesh.setMatrixAt(i, m);
      mesh.setColorAt(i, col.set(it.color || '#ffffff'));
    });
    mesh.instanceMatrix.needsUpdate = true;
    if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
    mesh.castShadow = shadows && this.opts.shadow !== false;
    mesh.receiveShadow = true;
    mesh.frustumCulled = false;
    parent.add(mesh);
    return mesh;
  }
}
class CylBatch {
  constructor(material, opts = {}) { this.material = material; this.items = []; this.opts = opts; }
  add(r, h, x, y, z, color, rx = 0, rz = 0, ry = 0) { this.items.push({ r, h, x, y, z, color, rx, ry, rz }); }
  build(parent, shadows = true, seg = 10) {
    if (!this.items.length) return null;
    const geo = new THREE.CylinderGeometry(0.5, 0.5, 1, seg);
    const mesh = new THREE.InstancedMesh(geo, this.material, this.items.length);
    const m = new THREE.Matrix4(), q = new THREE.Quaternion(), e = new THREE.Euler(), v = new THREE.Vector3(), s = new THREE.Vector3();
    const col = new THREE.Color();
    this.items.forEach((it, i) => {
      e.set(it.rx, it.ry, it.rz); q.setFromEuler(e);
      v.set(it.x, it.y, it.z); s.set(it.r * 2, it.h, it.r * 2);
      m.compose(v, q, s); mesh.setMatrixAt(i, m);
      mesh.setColorAt(i, col.set(it.color || '#ffffff'));
    });
    mesh.instanceMatrix.needsUpdate = true;
    if (mesh.instanceColor) mesh.instanceColor.needsUpdate = true;
    mesh.castShadow = shadows && this.opts.shadow !== false;
    mesh.receiveShadow = true;
    mesh.frustumCulled = false;
    parent.add(mesh);
    return mesh;
  }
}

function skyMaterial(map) {
  return new THREE.ShaderMaterial({
    side: THREE.BackSide, depthWrite: false, fog: false,
    uniforms: {
      top: { value: new THREE.Color(map.skyTop) },
      horizon: { value: new THREE.Color(map.skyHorizon) },
      sunColor: { value: new THREE.Color(map.sunColor) },
      sunDir: { value: new THREE.Vector3(...map.sunDir).normalize() },
      uTime: { value: 0 }
    },
    vertexShader: `
      varying vec3 vDir;
      void main(){ vDir = normalize(position); gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }
    `,
    fragmentShader: `
      uniform vec3 top; uniform vec3 horizon; uniform vec3 sunColor; uniform vec3 sunDir; uniform float uTime;
      varying vec3 vDir;
      void main(){
        vec3 d = normalize(vDir);
        float h = clamp(d.y*0.5+0.5, 0., 1.);
        vec3 col = mix(horizon, top, pow(smoothstep(0.46, 0.95, h), 0.8));
        float sun = max(dot(d, normalize(sunDir)), 0.0);
        col += sunColor * pow(sun, 90.0) * 0.9;
        col += sunColor * pow(sun, 8.0) * 0.16;
        float band = sin(d.y*28.0 + d.x*5.0 + uTime*0.015)*0.5+0.5;
        col += horizon * 0.035 * band * smoothstep(0.5,0.0,d.y);
        gl_FragColor = vec4(col, 1.0);
      }
    `
  });
}

export function buildWorld(scene, map, quality = 'medium') {
  const rng = mulberry32(map.id.split('').reduce((a, c) => a + c.charCodeAt(0), 77) * 97);
  const group = new THREE.Group(); group.name = 'world'; scene.add(group);
  const colliders = [];
  const lootSpots = [];
  const vehicleSpots = [];
  const spawnPoints = [];
  const poiCenters = [];
  const lowQ = quality === 'low';
  const propScale = quality === 'low' ? 0.55 : quality === 'medium' ? 0.8 : 1;

  /* ---------------- terrain height field ---------------- */
  const seed = map.id.length * 1.7 + map.id.charCodeAt(1);
  const baseHeight = (x, z) => {
    let h = 2.6 * Math.sin(x * 0.011 + seed) + 2.0 * Math.cos(z * 0.014 + seed * 2.2)
      + 1.5 * Math.sin((x + z) * 0.026 + seed) + 3.2 * Math.sin(x * 0.004 + seed) * Math.cos(z * 0.005 - seed);
    h += 0.55 * Math.sin(x * 0.09) * Math.cos(z * 0.08);
    return h * 0.72;
  };
  const shore = d => 1 - THREE.MathUtils.smoothstep(d, 236, 292);
  const poiHeights = map.pois.map(p => baseHeight(p.x, p.z) * shore(Math.hypot(p.x, p.z)) + 0.9);
  const heightAt = (x, z) => {
    let h = baseHeight(x, z);
    for (let i = 0; i < map.pois.length; i++) {
      const p = map.pois[i];
      const d = Math.hypot(x - p.x, z - p.z);
      const rr = p.r + 30;
      if (d < rr) {
        const t = THREE.MathUtils.smoothstep(d, p.r * 0.65, rr);
        h = lerp(poiHeights[i], h, t);
      }
    }
    const sh = shore(Math.hypot(x, z));
    h = h * sh - (1 - sh) * 8;
    return h;
  };
  const groundAt = (x, z) => Math.max(0.12, heightAt(x, z));

  const addCollider = (x, z, w, d, y0, h, ry = 0) => {
    const c = Math.abs(Math.cos(ry)), s = Math.abs(Math.sin(ry));
    const hw = (w * c + d * s) / 2, hd = (w * s + d * c) / 2;
    colliders.push({ minX: x - hw, maxX: x + hw, minZ: z - hd, maxZ: z + hd, minY: y0, maxY: y0 + h });
  };

  /* ---------------- materials ---------------- */
  const mkTex = (fn) => { const t = fn(); t.anisotropy = quality === 'high' ? 4 : 1; return t; };
  const concreteTex = mkTex(() => noiseTexture('#a9a9a4', ['#8f8f89', '#c0c0ba', '#7b7b76', '#b5b5ae'], 256, { dots: 1500, dotMax: 2.6, streaks: 20 }));
  const metalTex = mkTex(() => panelTexture('#a7adb2', 'rgba(60,66,70,.35)', 256, 6));
  const woodTex = mkTex(() => canvasTexture(256, (ctx, s) => {
    ctx.fillStyle = '#b59a74'; ctx.fillRect(0, 0, s, s);
    for (let i = 0; i < 10; i++) {
      ctx.fillStyle = i % 2 ? '#a88a63' : '#c0a57f';
      ctx.fillRect(0, i * s / 10, s, s / 10 - 2);
      ctx.strokeStyle = 'rgba(80,55,30,.25)'; ctx.lineWidth = 2;
      ctx.beginPath(); ctx.moveTo(0, i * s / 10); ctx.lineTo(s, i * s / 10); ctx.stroke();
    }
    for (let i = 0; i < 40; i++) { ctx.strokeStyle = 'rgba(90,62,35,.14)'; ctx.beginPath(); ctx.moveTo(0, Math.random() * s); ctx.lineTo(s, Math.random() * s); ctx.stroke(); }
  }));
  const stoneTex = mkTex(() => noiseTexture('#8f8b80', ['#6d6a61', '#aaa69a', '#7d7a70'], 256, { dots: 1800, dotMax: 4 }));
  const matte = (tex, rough = 0.85, metal = 0.06) => new THREE.MeshStandardMaterial({ map: tex, color: 0xffffff, roughness: rough, metalness: metal });
  const matConcrete = matte(concreteTex, 0.9, 0.03);
  const matMetal = matte(metalTex, 0.55, 0.5);
  const matWood = matte(woodTex, 0.85, 0.02);
  const matStone = matte(stoneTex, 0.95, 0.02);
  const matDark = new THREE.MeshStandardMaterial({ color: 0x2a3036, roughness: 0.65, metalness: 0.4 });
  const matGlass = new THREE.MeshStandardMaterial({ color: 0x16303f, roughness: 0.15, metalness: 0.6, emissive: 0x0d2430, emissiveIntensity: 0.8 });
  const matCloth = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.95, metalness: 0 });

  for (const m of [matConcrete, matMetal, matWood, matStone, matDark, matCloth]) m.vertexColors = false;

  const bat = {
    concrete: new BoxBatch(matConcrete),
    metal: new BoxBatch(matMetal),
    wood: new BoxBatch(matWood),
    stone: new BoxBatch(matStone),
    dark: new BoxBatch(matDark),
    glass: new BoxBatch(matGlass, { shadow: false }),
    cloth: new BoxBatch(matCloth),
    paint: new BoxBatch(new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.5, metalness: 0.15 }), { shadow: false }),
    cyl: new CylBatch(matMetal),
    cylDark: new CylBatch(matDark),
    cylWood: new CylBatch(matWood),
    cylStone: new CylBatch(matStone)
  };

  const G = (x, z) => heightAt(x, z);
  const box = (cat, w, h, d, x, y, z, color, opts = {}) => {
    bat[cat].add(w, h, d, x, y, z, color, opts.ry || 0, opts.rx || 0, opts.rz || 0);
    if (opts.solid) addCollider(x, z, w, d, y - h / 2, h, opts.ry || 0);
  };
  const wall = (x, z, w, d, h, cat, color, opts = {}) => {
    const gy = opts.baseY != null ? opts.baseY : G(x, z);
    box(cat, w, h, d, x, gy + h / 2, z, color, { ...opts, solid: opts.solid !== false });
    return gy;
  };

  /* ---------------- ground ---------------- */
  const terraSeg = lowQ ? 80 : 128;
  const tGeo = new THREE.PlaneGeometry(SIZE + 40, SIZE + 40, terraSeg, terraSeg);
  tGeo.rotateX(-Math.PI / 2);
  const pos = tGeo.attributes.position;
  const colors = new Float32Array(pos.count * 3);
  const cA = new THREE.Color(map.groundA), cB = new THREE.Color(map.groundB), cC = new THREE.Color(map.groundC);
  const cSand = new THREE.Color(map.sand), cRock = new THREE.Color(map.rock);
  const tmpC = new THREE.Color();
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i), z = pos.getZ(i);
    const h = heightAt(x, z);
    pos.setY(i, h);
    const d = Math.hypot(x, z);
    const n = 0.5 + 0.5 * Math.sin(x * 0.09 + Math.cos(z * 0.07) * 3) * Math.cos(z * 0.05);
    tmpC.copy(cA).lerp(cB, clamp(n + (h < 1.2 ? 0.2 : 0), 0, 1));
    if (h < 1.7) tmpC.lerp(cSand, clamp((1.7 - h) / 2.4, 0, 0.85));
    if (h > 4.2) tmpC.lerp(cC, clamp((h - 4.2) / 4, 0, 0.65));
    const sl = Math.abs(heightAt(x + 3, z) - heightAt(x - 3, z)) + Math.abs(heightAt(x, z + 3) - heightAt(x, z - 3));
    if (sl > 2.4) tmpC.lerp(cRock, clamp((sl - 2.4) / 3, 0, 0.5));
    if (map.id === 'frost') tmpC.lerp(new THREE.Color('#f2f7fa'), clamp((h - 1.4) / 5, 0, 0.35));
    const v = 0.94 + n * 0.1;
    colors[i * 3] = tmpC.r * v; colors[i * 3 + 1] = tmpC.g * v; colors[i * 3 + 2] = tmpC.b * v;
  }
  tGeo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
  tGeo.computeVertexNormals();
  const groundTex = mkTex(() => noiseTexture('#d8d8d4', ['#ffffff', '#b8b8b2', '#94948e', '#e2e2dd'], 256, { dots: 1800, dotMax: 1.9, streaks: 30 }));
  groundTex.repeat.set(32, 32);
  const groundMat = new THREE.MeshStandardMaterial({ map: groundTex, vertexColors: true, roughness: 0.96, metalness: 0.02 });
  const terrain = new THREE.Mesh(tGeo, groundMat);
  terrain.receiveShadow = true; terrain.castShadow = false;
  terrain.userData.terrain = true;
  group.add(terrain);

  /* ---------------- water ---------------- */
  const wTex = mkTex(() => canvasTexture(256, (ctx, s) => {
    ctx.fillStyle = '#7f9fa6'; ctx.fillRect(0, 0, s, s);
    for (let i = 0; i < 90; i++) {
      const y = Math.random() * s, x = Math.random() * s, w = 20 + Math.random() * 80;
      ctx.strokeStyle = `rgba(255,255,255,${0.04 + Math.random() * 0.12})`;
      ctx.lineWidth = 1 + Math.random() * 1.5;
      ctx.beginPath(); ctx.moveTo(x, y); ctx.quadraticCurveTo(x + w / 2, y + 4, x + w, y); ctx.stroke();
    }
  }));
  wTex.repeat.set(26, 26);
  const water = new THREE.Mesh(new THREE.PlaneGeometry(1900, 1900), new THREE.MeshStandardMaterial({
    map: wTex, color: new THREE.Color(map.water), roughness: 0.17, metalness: 0.55, transparent: true, opacity: 0.93
  }));
  water.rotation.x = -Math.PI / 2; water.position.y = SEA;
  water.receiveShadow = false;
  group.add(water);

  /* ---------------- sky & lighting ---------------- */
  const sky = new THREE.Mesh(new THREE.SphereGeometry(900, 24, 16), skyMaterial(map));
  sky.frustumCulled = false;
  group.add(sky);
  scene.fog = new THREE.Fog(map.fogColor, map.fogNear, map.fogFar);
  scene.background = new THREE.Color(map.fogColor);

  const sun = new THREE.DirectionalLight(map.sunColor, map.sunIntensity);
  const sunDir = new THREE.Vector3(...map.sunDir).normalize();
  sun.position.copy(sunDir).multiplyScalar(180);
  sun.castShadow = quality !== 'low';
  sun.shadow.mapSize.set(quality === 'high' ? 2048 : 1024, quality === 'high' ? 2048 : 1024);
  sun.shadow.camera.near = 1; sun.shadow.camera.far = 420;
  const sc = quality === 'low' ? 80 : 110;
  sun.shadow.camera.left = -sc; sun.shadow.camera.right = sc;
  sun.shadow.camera.top = sc; sun.shadow.camera.bottom = -sc;
  sun.shadow.bias = -0.0009;
  sun.target.position.set(0, 0, 0);
  group.add(sun, sun.target);
  const hemi = new THREE.HemisphereLight(map.skyHorizon, map.groundB, 0.65);
  group.add(hemi);
  const fill = new THREE.DirectionalLight(0x8fb7c8, 0.35);
  fill.position.set(-sunDir.x * 90, 60, -sunDir.z * 90);
  group.add(fill);

  /* ---------------- POI ground pads ---------------- */
  const padVerts = [], padIndices = [];
  for (const p of map.pois) {
    const rad = p.r * 0.78;
    const segs = 28;
    const start = padVerts.length / 3;
    for (let i = 0; i <= segs; i++) {
      const a = i / segs * Math.PI * 2;
      const x = p.x + Math.cos(a) * rad, z = p.z + Math.sin(a) * rad;
      padVerts.push(x, heightAt(x, z) + 0.05, z);
    }
    padVerts.push(p.x, heightAt(p.x, p.z) + 0.06, p.z);
    const center = start + segs + 1;
    for (let i = 0; i < segs; i++) padIndices.push(center, start + i, start + i + 1);
  }
  const padGeo = new THREE.BufferGeometry();
  padGeo.setAttribute('position', new THREE.Float32BufferAttribute(padVerts, 3));
  padGeo.setIndex(padIndices);
  padGeo.computeVertexNormals();
  const padMat = new THREE.MeshStandardMaterial({ color: new THREE.Color(map.road), roughness: 1, metalness: 0, transparent: true, opacity: 0.4, depthWrite: false, polygonOffset: true, polygonOffsetFactor: -2 });
  const pads = new THREE.Mesh(padGeo, padMat); pads.receiveShadow = true; group.add(pads);

  /* ---------------- roads between POIs ---------------- */
  const roadVerts = [], roadIdx = [], roadUvs = [];
  const roadPairs = [];
  for (let i = 1; i < map.pois.length; i++) roadPairs.push([map.pois[i - 1], map.pois[i]]);
  roadPairs.push([map.pois[0], map.pois[3] || map.pois[1]]);
  let vi = 0;
  for (const [a, b] of roadPairs) {
    const dist = Math.hypot(b.x - a.x, b.z - a.z);
    const steps = Math.max(3, Math.floor(dist / 12));
    for (let i = 0; i < steps; i++) {
      const t0 = i / steps, t1 = (i + 1) / steps;
      const p0 = { x: lerp(a.x, b.x, t0), z: lerp(a.z, b.z, t0) };
      const p1 = { x: lerp(a.x, b.x, t1), z: lerp(a.z, b.z, t1) };
      const ang = Math.atan2(p1.z - p0.z, p1.x - p0.x);
      const nx = Math.cos(ang + Math.PI / 2) * 3.6, nz = Math.sin(ang + Math.PI / 2) * 3.6;
      const pts = [[p0.x - nx, p0.z - nz], [p0.x + nx, p0.z + nz], [p1.x - nx, p1.z - nz], [p1.x + nx, p1.z + nz]];
      for (const [x, z] of pts) roadVerts.push(x, heightAt(x, z) + 0.04, z);
      roadUvs.push(0, 0, 1, 0, 0, 1, 1, 1);
      roadIdx.push(vi, vi + 2, vi + 1, vi + 1, vi + 2, vi + 3);
      vi += 4;
    }
  }
  const roadGeo = new THREE.BufferGeometry();
  roadGeo.setAttribute('position', new THREE.Float32BufferAttribute(roadVerts, 3));
  roadGeo.setAttribute('uv', new THREE.Float32BufferAttribute(roadUvs, 2));
  roadGeo.setIndex(roadIdx); roadGeo.computeVertexNormals();
  const road = new THREE.Mesh(roadGeo, new THREE.MeshStandardMaterial({ color: new THREE.Color(map.road), roughness: 0.98, metalness: 0, transparent: true, opacity: 0.55, depthWrite: false, polygonOffset: true, polygonOffsetFactor: -3 }));
  road.receiveShadow = true;
  group.add(road);

  /* ---------------- prop & building helpers ---------------- */
  const addLoot = (x, z, kind = 'random', yOffset = 0) => {
    lootSpots.push({ x, z, y: heightAt(x, z) + 0.05 + yOffset, kind });
  };
  const addVehicleSpot = (x, z, yaw = 0) => {
    if (Math.hypot(x, z) > 250) return;
    vehicleSpots.push({ x, z, y: heightAt(x, z), yaw });
  };
  const addSpawn = (x, z) => { if (Math.hypot(x, z) < 270) spawnPoints.push({ x, z, y: heightAt(x, z) }); };

  const crate = (x, z, size = 1.2, color = '#8a6b43', baseY = null) => {
    const gy = baseY != null ? baseY : G(x, z);
    box('wood', size, size, size, x, gy + size / 2, z, color, { solid: true });
    box('dark', size * 1.02, 0.06, size * 0.2, x, gy + size - 0.03, z, '#4a3b2a');
    addLoot(x + size * 0.8, z, 'random', 0);
  };
  const barrel = (x, z, color = '#b55335', baseY = null) => {
    const gy = baseY != null ? baseY : G(x, z);
    bat.cylDark.add(0.35, 0.95, x, gy + 0.475, z, color, 0, 0, 0);
    addCollider(x, z, 0.7, 0.7, gy, 0.95);
  };
  const sandbag = (x, z, y, ry = 0, color = '#b6a578') => {
    box('cloth', 0.9, 0.32, 0.55, x, y + 0.16, z, color, { ry, solid: true });
  };
  const container = (x, z, color = '#4f6b78', ry = 0, stack = 0) => {
    const gy = baseYAt(x, z);
    const w = 6.2, h = 2.55, d = 2.5;
    for (let s = 0; s <= stack; s++) {
      const y = gy + 0.08 + s * (h + 0.02) + h / 2;
      box('metal', w, h, d, x, y, z, color, { ry, solid: true });
      for (let i = -1; i <= 1; i++) {
        box('dark', w * 0.9, 0.05, 0.03, x + Math.sin(ry) * (d / 2 + 0.01) + Math.cos(ry) * i * 2, y + 0.6, z + Math.cos(ry) * (d / 2 + 0.01) - Math.sin(ry) * i * 2, '#20262b', { ry });
      }
      box('paint', w * 0.35, 0.16, 0.02, x + Math.sin(ry) * (d / 2 + 0.02), y + 0.3, z + Math.cos(ry) * (d / 2 + 0.02), '#e0e6ea', { ry });
    }
  };
  const baseYAt = (x, z) => Math.max(0.15, heightAt(x, z));

  const addWindow = (x, y, z, w, h, ry = 0) => {
    box('glass', w, h, 0.08, x, y, z, '#8fd7ff', { ry });
    box('dark', w + 0.18, 0.07, 0.12, x, y + h / 2 + 0.04, z, '#252a2e', { ry });
    box('dark', w + 0.18, 0.07, 0.12, x, y - h / 2 - 0.04, z, '#252a2e', { ry });
  };

  function house(cx, cz, w = 9, d = 7, h = 3.2, ry = 0, color = '#c8c3b4', roofColor = '#7b4a36', door = 1.8) {
    const gy = G(cx, cz);
    const hw = w / 2, hd = d / 2;
    const cos = Math.cos(ry), sin = Math.sin(ry);
    const L = (lx, lz) => [cx + lx * cos - lz * sin, cz + lx * sin + lz * cos];
    const wallA = '#cfc9b8';
    box('concrete', w + 0.6, 0.35, d + 0.6, cx, gy + 0.17, cz, '#8d897d', { ry, solid: true });
    // front & back walls (door gap in front at -z)
    const side = (w - door) / 2;
    for (const s of [-1, 1]) {
      const [x1, z1] = L(s * (door / 2 + side / 2), -hd);
      wall(x1, z1, side, 0.28, h, 'concrete', wallA, { baseY: gy + 0.3, ry });
      const [x2, z2] = L(0, -hd);
      box('concrete', door, 0.55, 0.28, x2, gy + 0.3 + h - 0.27, z2, wallA, { ry, solid: true });
    }
    const [bx, bz] = L(0, hd);
    wall(bx, bz, w, 0.28, h, 'concrete', wallA, { baseY: gy + 0.3, ry });
    for (const s of [-1, 1]) {
      const [sx, sz] = L(s * hw, 0);
      wall(sx, sz, 0.28, d, h, 'concrete', wallA, { baseY: gy + 0.3, ry });
      const [wx, wz] = L(s * (hw + 0.05), 0.8);
      addWindow(wx, gy + 2.0, wz, 1.5, 0.9, ry);
    }
    // roof
    for (const s of [-1, 1]) {
      const [rx, rz] = L(0, s * d * 0.255);
      box('wood', w + 1.3, 0.18, d * 0.58, rx, gy + h + 0.75, rz, roofColor, { ry, rx: s * 0.38 });
    }
    box('dark', w + 1.4, 0.12, 0.22, cx, gy + h + 1.47, cz, '#3a2b22', { ry });
    // interior floor + loot
    box('wood', w - 0.9, 0.08, d - 0.9, cx, gy + 0.34, cz, '#977c58', { ry });
    addLoot(cx - w * 0.2, cz + d * 0.12, 'weapon');
    addLoot(cx + w * 0.22, cz - d * 0.15, 'random');
    addWindow(cx, gy + 2.0, cz + hd + 0.02, 1.4, 0.9, ry);
    // exterior crates
    if (rng() > 0.4) crate(cx + (rng() - 0.5) * w * 1.6, cz + (rng() > 0.5 ? hd + 2 : -hd - 2), 1.05);
  }

  function warehouse(cx, cz, w = 22, d = 14, h = 5.6, color = '#7b8388', ry = 0) {
    const gy = G(cx, cz);
    const cos = Math.cos(ry), sin = Math.sin(ry);
    const L = (lx, lz) => [cx + lx * cos - lz * sin, cz + lx * sin + lz * cos];
    box('concrete', w + 1, 0.4, d + 1, cx, gy + 0.2, cz, '#8b877b', { ry, solid: true });
    const door = 4.6;
    const side = (w - door) / 2;
    for (const s of [-1, 1]) {
      const [x, z] = L(s * (door / 2 + side / 2), -d / 2);
      wall(x, z, side, 0.32, h, 'metal', color, { baseY: gy + 0.4, ry });
      const [lx, lz] = L(0, -d / 2);
      box('metal', door, 1.1, 0.32, lx, gy + 0.4 + h - 0.55, lz, color, { ry, solid: true });
    }
    const [bx, bz] = L(0, d / 2);
    wall(bx, bz, w, 0.32, h, 'metal', color, { baseY: gy + 0.4, ry });
    for (const s of [-1, 1]) {
      const [sx, sz] = L(s * w / 2, 0);
      wall(sx, sz, 0.32, d, h, 'metal', color, { baseY: gy + 0.4, ry });
      const [wx, wz] = L(s * (w / 2 + 0.02), 0);
      for (let i = -1; i <= 1; i++) {
        const [x, z] = L(s * (w / 2 + 0.02), i * 3.4);
        addWindow(x, gy + 3.8, z, 1.6, 1.0, ry);
      }
    }
    // roof
    for (let i = 0; i < Math.ceil(w / 5); i++) {
      const lx = -w / 2 + 2.6 + i * 5;
      const [x, z] = L(lx, 0);
      box('metal', 5.2, 0.22, d + 1.4, x, gy + h + 0.6, z, '#596166', { ry });
      box('dark', 0.25, 0.6, 0.25, x, gy + h + 0.3, z, '#2f353a', { ry });
    }
    box('dark', w, 0.35, 0.28, cx, gy + h + 0.15, cz - d / 2, '#3a4045', { ry });
    // interior
    box('concrete', w - 1.5, 0.1, d - 1.5, cx, gy + 0.45, cz, '#96938a', { ry });
    const [ix, iz] = L(-w * 0.2, 0.6);
    crate(ix, iz, 1.5, '#806444', gy + 0.5);
    const [ix2, iz2] = L(w * 0.24, -d * 0.2);
    barrel(ix2, iz2, '#a35438', gy + 0.5);
    addLoot(...L(-w * 0.05, -d * 0.18), 'weapon');
    addLoot(...L(w * 0.15, d * 0.2), 'random');
    addLoot(...L(-w * 0.3, d * 0.3), 'random');
    // containers behind
    if (rng() > 0.3) container(cx + (rng() - 0.5) * (w + 10), cz + d / 2 + 3.6, rng() > 0.5 ? '#7a4a3a' : '#3f5c6b', 0, rng() > 0.7 ? 1 : 0);
    addVehicleSpot(...L(-w / 2 - 5, -d / 2 - 3), ry + 0.4);
  }

  function bunker(cx, cz, w = 13, d = 10, h = 2.9, color = '#8b8c80') {
    const gy = G(cx, cz);
    box('concrete', w + 1.2, 0.5, d + 1.2, cx, gy + 0.25, cz, '#77776d', { solid: true });
    wall(cx, cz - d / 2, w, 0.45, h, 'concrete', color, { baseY: gy + 0.5 });
    wall(cx, cz + d / 2, w, 0.45, h, 'concrete', color, { baseY: gy + 0.5 });
    wall(cx - w / 2, cz, 0.45, d, h, 'concrete', color, { baseY: gy + 0.5 });
    wall(cx + w / 2, cz, 0.45, d, h, 'concrete', color, { baseY: gy + 0.5 });
    box('concrete', w + 1.6, 0.4, d + 1.6, cx, gy + h + 0.6, cz, '#6d6d63');
    box('concrete', w + 1.7, 0.25, 0.7, cx, gy + h + 0.95, cz - d / 2, '#5e5e55');
    for (let i = -1; i <= 1; i++) addWindow(cx + i * 3.2, gy + 1.9, cz - d / 2 - 0.24, 1.2, 0.45);
    addLoot(cx, cz + 1.4, 'weapon');
    addLoot(cx - 2.6, cz - 1.2, 'random');
    // sandbags
    for (let i = 0; i < 5; i++) sandbag(cx - w / 2 - 2.6, cz - 2 + i * 1.2, gy, 0);
    for (let i = 0; i < 4; i++) sandbag(cx + 2 + i * 1.1, cz - d / 2 - 2, gy, Math.PI / 2);
  }

  function watchtower(cx, cz, h = 7, color = '#6c6a5c') {
    const gy = G(cx, cz);
    for (const [sx, sz] of [[-1.6, -1.6], [1.6, -1.6], [-1.6, 1.6], [1.6, 1.6]]) {
      bat.cylDark.add(0.14, h, cx + sx, gy + h / 2, cz + sz, color, 0, 0, 0);
      addCollider(cx + sx, cz + sz, 0.4, 0.4, gy, h);
    }
    box('wood', 5, 0.3, 5, cx, gy + h, cz, '#8b7656', { solid: true });
    box('wood', 0.2, 1.0, 5, cx - 2.4, gy + h + 0.65, cz, '#7a6749');
    box('wood', 0.2, 1.0, 5, cx + 2.4, gy + h + 0.65, cz, '#7a6749');
    box('wood', 5, 1.0, 0.2, cx, gy + h + 0.65, cz - 2.4, '#7a6749');
    box('metal', 5.8, 0.16, 5.8, cx, gy + h + 1.5, cz, '#4b5052');
    box('metal', 0.18, 1.4, 0.18, cx - 2.4, gy + h + 0.8, cz - 2.4, '#3e4345');
    box('metal', 0.18, 1.4, 0.18, cx + 2.4, gy + h + 0.8, cz + 2.4, '#3e4345');
    addLoot(cx, cz, 'weapon', h);
    addLoot(cx + 0.8, cz + 0.6, 'ammo', h);
  }

  function tents(cx, cz, count = 3) {
    for (let i = 0; i < count; i++) {
      const a = rng() * Math.PI * 2, ra = 4 + rng() * 8;
      const x = cx + Math.cos(a) * ra, z = cz + Math.sin(a) * ra;
      const gy = G(x, z);
      bat.cylStone.add(1.9, 1.5, x, gy + 0.75, z, i % 2 ? '#b99a63' : '#7d8a55', 0, 0, 0);
      addCollider(x, z, 2.6, 2.6, gy, 1.5);
      addLoot(x + 1.2, z, 'random');
    }
  }

  function fences(cx, cz, rad, color = '#9c825d') {
    const segs = Math.floor(rad * 1.2);
    for (let i = 0; i < segs; i++) {
      const a = i / segs * Math.PI * 2;
      if (i % 5 === 0) continue;
      const x = cx + Math.cos(a) * rad, z = cz + Math.sin(a) * rad;
      const gy = G(x, z);
      box('wood', 2.8, 0.13, 0.11, x, gy + 0.9, z, color, { ry: -a, solid: true });
      box('wood', 2.8, 0.13, 0.11, x, gy + 0.5, z, color, { ry: -a });
    }
  }

  /* ---------------- POI builders ---------------- */
  for (const p of map.pois) {
    poiCenters.push({ ...p, y: heightAt(p.x, p.z) });
    switch (p.type) {
      case 'town': {
        const n = 5;
        for (let i = 0; i < n; i++) {
          const a = (i / n) * Math.PI * 2 + 0.5;
          const rad = p.r * (0.42 + (i % 2) * 0.08);
          const hx = p.x + Math.cos(a) * rad, hz = p.z + Math.sin(a) * rad;
          const rot = i % 2 ? Math.PI / 2 : 0;
          const palette = rng() > 0.6 ? ['#b7ada0', '#6d4a3c'] : rng() > 0.4 ? ['#c7beac', '#7a5745'] : ['#a6a89e', '#4f5c5c'];
          house(hx, hz, 8.5 + (i % 2) * 1.4, 7 + (i % 3), 3.1, rot, palette[0], palette[1]);
        }
        crate(p.x + 4, p.z + 5, 1.2, '#8b6b45');
        crate(p.x - 3, p.z + 6, 1.0, '#755b3d');
        addLoot(p.x + 1.5, p.z - 2, 'weapon');
        addLoot(p.x - 1.5, p.z + 2, 'random');
        addVehicleSpot(p.x - p.r * 0.7, p.z + 2, 1.4);
        addSpawn(p.x + 6, p.z + 8);
        for (let i = 0; i < 8; i++) addSpawn(p.x + (rng() - 0.5) * p.r * 1.7, p.z + (rng() - 0.5) * p.r * 1.7);
        break;
      }
      case 'industrial': {
        warehouse(p.x, p.z, 21, 13, 5.4, rng() > 0.5 ? '#788087' : '#6c756f');
        for (let i = 0; i < 3; i++) {
          const a = rng() * Math.PI * 2;
          container(p.x + Math.cos(a) * (p.r * 0.7), p.z + Math.sin(a) * (p.r * 0.7), ['#7a4a3a', '#3f5c6b', '#5c6b4b'][i], a > 2 ? Math.PI / 2 : 0, i % 3 === 0 ? 1 : 0);
        }
        for (let i = 0; i < 5; i++) barrel(p.x + (rng() - 0.5) * p.r, p.z + (rng() - 0.5) * p.r, rng() > 0.5 ? '#a35438' : '#3f5a68');
        bat.cylDark.add(0.5, 9, p.x - p.r * 0.55, G(p.x - p.r * 0.55, p.z) + 4.5, p.z - p.r * 0.4, '#6d7377');
        addVehicleSpot(p.x + p.r * 0.55, p.z + p.r * 0.3, 0.4);
        addSpawn(p.x, p.z + p.r * 0.8);
        for (let i = 0; i < 7; i++) addSpawn(p.x + (rng() - 0.5) * p.r * 1.8, p.z + (rng() - 0.5) * p.r * 1.8);
        break;
      }
      case 'military': {
        bunker(p.x, p.z, 12, 9, 2.9, '#7e8175');
        watchtower(p.x + p.r * 0.55, p.z - p.r * 0.42, 6.4);
        for (let i = 0; i < 7; i++) {
          const a = rng() * Math.PI * 2, ra = 8 + rng() * p.r * 0.6;
          sandbag(p.x + Math.cos(a) * ra, p.z + Math.sin(a) * ra, G(p.x + Math.cos(a) * ra, p.z + Math.sin(a) * ra), a);
        }
        for (let i = 0; i < 3; i++) crate(p.x - 7 + i * 2.4, p.z + 5.5, 1.15, '#5f6b4a');
        addVehicleSpot(p.x + 8, p.z + 6, 0.9);
        for (let i = 0; i < 7; i++) addSpawn(p.x + (rng() - 0.5) * p.r * 1.7, p.z + (rng() - 0.5) * p.r * 1.7);
        break;
      }
      case 'ruins': {
        const gy = G(p.x, p.z);
        box('stone', 14, 0.4, 12, p.x, gy + 0.2, p.z, '#9d9687', { solid: true });
        for (let i = 0; i < 6; i++) {
          const a = i / 6 * Math.PI * 2;
          const x = p.x + Math.cos(a) * 5.4, z = p.z + Math.sin(a) * 5.4;
          const hh = 2.4 + rng() * 3.5;
          wall(x, z, 4.2, 0.55, hh, 'stone', i % 2 ? '#a39a87' : '#8f8776', { baseY: gy, ry: a });
        }
        for (let i = 0; i < 6; i++) {
          const a = rng() * Math.PI * 2, ra = 8 + rng() * p.r * 0.6;
          const x = p.x + Math.cos(a) * ra, z = p.z + Math.sin(a) * ra;
          const hh = 2.5 + rng() * 3;
          bat.cylStone.add(0.5, hh, x, G(x, z) + hh / 2, z, '#aaa08c');
          addCollider(x, z, 1, 1, G(x, z), hh);
        }
        crate(p.x + 2, p.z + 2, 1.2, '#7d6646');
        addLoot(p.x - 2, p.z, 'weapon');
        addLoot(p.x + 2.5, p.z - 1, 'random');
        addSpawn(p.x + 7, p.z - 5);
        for (let i = 0; i < 8; i++) addSpawn(p.x + (rng() - 0.5) * p.r * 2, p.z + (rng() - 0.5) * p.r * 2);
        break;
      }
      case 'docks': {
        warehouse(p.x, p.z, 18, 12, 4.8, '#6f777a');
        container(p.x + p.r * 0.7, p.z - 4, '#3f5c6b', 0, 1);
        container(p.x + p.r * 0.7, p.z + 4, '#7a4a3a', 0, 0);
        for (let i = 0; i < 4; i++) crate(p.x - p.r * 0.7, p.z - 6 + i * 3.2, 1.3, '#886a47');
        addVehicleSpot(p.x + 4, p.z + p.r * 0.6, 0.2);
        addSpawn(p.x + 8, p.z + 4);
        for (let i = 0; i < 6; i++) addSpawn(p.x + (rng() - 0.5) * p.r * 1.9, p.z + (rng() - 0.5) * p.r * 1.9);
        break;
      }
      case 'farm': {
        const gy = G(p.x, p.z);
        house(p.x, p.z, 14, 18, 5, 0, '#9e4b38', '#4a2b24', 3.2);
        const sx = p.x + 10, sz = p.z - 7;
        bat.cylDark.add(2.1, 8, sx, G(sx, sz) + 4, sz, '#a5a59a');
        bat.cylDark.add(2.3, 0.6, sx, G(sx, sz) + 8.3, sz, '#7b7b71');
        addCollider(sx, sz, 4.2, 4.2, G(sx, sz), 8.3);
        for (let i = 0; i < 6; i++) {
          const a = rng() * Math.PI;
          const x = p.x - 8 + Math.cos(a) * 6, z = p.z + 10 + Math.sin(a) * 6;
          bat.cylWood.add(0.7, 1.2, x, G(x, z) + 0.7, z, '#c9ab63', Math.PI / 2, 0, 0);
        }
        fences(p.x, p.z, p.r * 0.9, '#9c825d');
        addLoot(p.x - 2, p.z + 3, 'weapon');
        addVehicleSpot(p.x + 8, p.z + 7, 1.1);
        for (let i = 0; i < 7; i++) addSpawn(p.x + (rng() - 0.5) * p.r * 1.8, p.z + (rng() - 0.5) * p.r * 1.8);
        break;
      }
      case 'oasis': {
        const gy = G(p.x, p.z);
        const pool = new THREE.Mesh(new THREE.CircleGeometry(p.r * 0.45, 24), new THREE.MeshStandardMaterial({ color: 0x2c8b9e, roughness: 0.15, metalness: 0.55, transparent: true, opacity: 0.9 }));
        pool.rotation.x = -Math.PI / 2; pool.position.set(p.x, gy + 0.08, p.z); group.add(pool);
        tents(p.x - p.r * 0.55, p.z + p.r * 0.3, 3);
        for (let i = 0; i < 5; i++) {
          const a = rng() * Math.PI * 2, ra = p.r * 0.7;
          addPalmAt(p.x + Math.cos(a) * ra, p.z + Math.sin(a) * ra, 1.1);
        }
        addLoot(p.x + 2, p.z + 2, 'weapon');
        addVehicleSpot(p.x + p.r * 0.7, p.z - p.r * 0.3, 2);
        for (let i = 0; i < 7; i++) addSpawn(p.x + (rng() - 0.5) * p.r * 1.7, p.z + (rng() - 0.5) * p.r * 1.7);
        break;
      }
      case 'lake': {
        const gy = G(p.x, p.z);
        const ice = new THREE.Mesh(new THREE.CircleGeometry(p.r * 0.78, 30), new THREE.MeshStandardMaterial({ color: 0xa8d6e2, roughness: 0.08, metalness: 0.25, transparent: true, opacity: 0.85 }));
        ice.rotation.x = -Math.PI / 2; ice.position.set(p.x, gy + 0.07, p.z); group.add(ice);
        for (let i = 0; i < 4; i++) {
          const a = (i / 4) * Math.PI * 2;
          house(p.x + Math.cos(a) * p.r * 0.8, p.z + Math.sin(a) * p.r * 0.8, 7.5, 6.5, 2.9, a, '#7a5d47', '#6e3d2f');
        }
        addLoot(p.x, p.z, 'weapon');
        addVehicleSpot(p.x + 10, p.z + 4, 0.6);
        for (let i = 0; i < 7; i++) addSpawn(p.x + (rng() - 0.5) * p.r * 1.8, p.z + (rng() - 0.5) * p.r * 1.8);
        break;
      }
    }
    // central loot table for every POI
    for (let i = 0; i < 3; i++) {
      const a = rng() * Math.PI * 2, ra = p.r * (0.15 + rng() * 0.45);
      addLoot(p.x + Math.cos(a) * ra, p.z + Math.sin(a) * ra, rng() > 0.72 ? 'weapon' : rng() > 0.5 ? 'ammo' : rng() > 0.45 ? 'med' : 'shield');
    }
  }

  /* ---------------- road-side vehicle spots & spawns ---------------- */
  for (let i = 0; i < map.pois.length; i++) {
    const p = map.pois[i], q = map.pois[(i + 1) % map.pois.length];
    const mx = (p.x + q.x) / 2, mz = (p.z + q.z) / 2;
    addVehicleSpot(mx + (rng() - 0.5) * 10, mz + (rng() - 0.5) * 10, rng() * 3);
    for (let k = 0; k < 3; k++) addSpawn(p.x + (rng() - 0.5) * 60, p.z + (rng() - 0.5) * 60);
  }
  for (let i = 0; i < 40; i++) {
    const a = rng() * Math.PI * 2, r = rng() * 230;
    addSpawn(Math.cos(a) * r, Math.sin(a) * r);
  }

  /* ---------------- foliage ---------------- */
  function makePalmGeometry() {
    const parts = [];
    parts.push(transformGeom(new THREE.CylinderGeometry(0.16, 0.28, 5.5, 7), [0, 2.7, 0]));
    parts.push(transformGeom(new THREE.CylinderGeometry(0.12, 0.17, 3, 6), [0.18, 5.4, 0], [0, 0, -0.12]));
    return mergeGeometries(parts);
  }
  function makeFrondsGeometry() {
    const parts = [];
    for (let i = 0; i < 9; i++) {
      const a = i / 9 * Math.PI * 2;
      const len = 2.8 + (i % 3) * 0.3;
      const frond = new THREE.BoxGeometry(0.3, 0.06, len);
      const g = transformGeom(frond, [Math.sin(a) * len * 0.42, 6.4 - (i % 2) * 0.2, Math.cos(a) * len * 0.42], [0.28 * (i % 2 ? 1 : -1) + 0.15, a, 0]);
      parts.push(g);
    }
    return mergeGeometries(parts);
  }
  function makePineGeometry() {
    const parts = [transformGeom(new THREE.CylinderGeometry(0.14, 0.26, 4, 7), [0, 2, 0])];
    parts.push(transformGeom(new THREE.ConeGeometry(2.2, 4, 8), [0, 4.3, 0]));
    parts.push(transformGeom(new THREE.ConeGeometry(1.7, 3.4, 8), [0, 6, 0]));
    parts.push(transformGeom(new THREE.ConeGeometry(1.15, 2.6, 8), [0, 7.6, 0]));
    return mergeGeometries(parts);
  }

  const palmTrunkGeo = makePalmGeometry();
  const palmCrownGeo = makeFrondsGeometry();
  const pineGeo = makePineGeometry();
  const treePositions = [];
  function addPalmAt(x, z, scale = 1) { treePositions.push({ x, z, scale, pine: false }); }
  function addPineAt(x, z, scale = 1) { treePositions.push({ x, z, scale, pine: true }); }

  // extra palms for oasis are added during POI build; place the rest
  const treeCount = Math.floor((map.tree === 'pine' ? 170 : 145) * propScale);
  for (let i = 0; i < treeCount; i++) {
    const a = rng() * Math.PI * 2, r = 30 + Math.sqrt(rng()) * 230;
    const x = Math.cos(a) * r, z = Math.sin(a) * r;
    if (heightAt(x, z) < 0.9) continue;
    if (map.pois.some(p => Math.hypot(x - p.x, z - p.z) < p.r * 0.7)) continue;
    const pine = map.tree === 'pine';
    (pine ? addPineAt : addPalmAt)(x, z, 0.75 + rng() * 0.7);
  }
  // cluster trees near POIs edges
  for (const p of map.pois) {
    for (let i = 0; i < 5; i++) {
      const a = rng() * Math.PI * 2, r = p.r * (0.9 + rng() * 0.5);
      const x = p.x + Math.cos(a) * r, z = p.z + Math.sin(a) * r;
      if (heightAt(x, z) < 0.8) continue;
      (map.tree === 'pine' ? addPineAt : addPalmAt)(x, z, 0.85 + rng() * 0.5);
    }
  }
  const palmTrunks = treePositions.filter(t => !t.pine);
  const pines = treePositions.filter(t => t.pine);
  const treeMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.92 });
  if (palmTrunks.length) {
    const trunkMesh = new THREE.InstancedMesh(palmTrunkGeo, treeMat, palmTrunks.length);
    const crownMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.9, side: THREE.DoubleSide });
    const crownMesh = new THREE.InstancedMesh(palmCrownGeo, crownMat, palmTrunks.length);
    const m = new THREE.Matrix4(), q = new THREE.Quaternion(), col = new THREE.Color();
    palmTrunks.forEach((t, i) => {
      q.setFromEuler(new THREE.Euler(0, rng() * Math.PI * 2, (rng() - 0.5) * 0.1));
      const gy = heightAt(t.x, t.z);
      m.compose(new THREE.Vector3(t.x, gy, t.z), q, new THREE.Vector3(t.scale, t.scale, t.scale));
      trunkMesh.setMatrixAt(i, m); crownMesh.setMatrixAt(i, m);
      trunkMesh.setColorAt(i, col.set('#8a7355'));
      crownMesh.setColorAt(i, col.set(rng() > 0.5 ? map.treeColor : map.treeColor2));
    });
    trunkMesh.castShadow = true; crownMesh.castShadow = true;
    trunkMesh.receiveShadow = crownMesh.receiveShadow = true;
    group.add(trunkMesh, crownMesh);
  }
  if (pines.length) {
    const pineMesh = new THREE.InstancedMesh(pineGeo, treeMat, pines.length);
    const m = new THREE.Matrix4(), q = new THREE.Quaternion(), col = new THREE.Color();
    pines.forEach((t, i) => {
      q.setFromEuler(new THREE.Euler(0, rng() * Math.PI * 2, (rng() - 0.5) * 0.06));
      const gy = heightAt(t.x, t.z);
      m.compose(new THREE.Vector3(t.x, gy, t.z), q, new THREE.Vector3(t.scale, t.scale, t.scale));
      pineMesh.setMatrixAt(i, m);
      pineMesh.setColorAt(i, col.set(rng() > 0.5 ? map.treeColor : map.treeColor2));
    });
    pineMesh.castShadow = true; pineMesh.receiveShadow = true;
    group.add(pineMesh);
  }

  // bushes
  const bushGeo = new THREE.IcosahedronGeometry(0.7, 0);
  const bushMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.95, flatShading: true });
  const bushes = [];
  for (let i = 0; i < 90 * propScale; i++) {
    const a = rng() * Math.PI * 2, r = 20 + Math.sqrt(rng()) * 245;
    const x = Math.cos(a) * r, z = Math.sin(a) * r;
    if (heightAt(x, z) < 0.7) continue;
    bushes.push({ x, z, s: 0.5 + rng() * 1.1 });
  }
  if (bushes.length) {
    const bm = new THREE.InstancedMesh(bushGeo, bushMat, bushes.length);
    const m = new THREE.Matrix4(), q = new THREE.Quaternion(), col = new THREE.Color();
    bushes.forEach((b, i) => {
      q.setFromEuler(new THREE.Euler(0, rng() * 6, 0));
      m.compose(new THREE.Vector3(b.x, heightAt(b.x, b.z) + 0.3 * b.s, b.z), q, new THREE.Vector3(b.s, b.s * 0.8, b.s));
      bm.setMatrixAt(i, m);
      bm.setColorAt(i, col.set(map.id === 'frost' ? '#6d8579' : map.id === 'dune' ? '#8d8a4e' : '#4e6f3d'));
    });
    bm.castShadow = true; bm.receiveShadow = true; group.add(bm);
  }

  // rocks
  const rockGeo = new THREE.DodecahedronGeometry(1, 0);
  const rockMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.95, flatShading: true });
  const rocks = [];
  for (let i = 0; i < 46 * propScale; i++) {
    const a = rng() * Math.PI * 2, r = 40 + Math.sqrt(rng()) * 220;
    const x = Math.cos(a) * r, z = Math.sin(a) * r;
    if (heightAt(x, z) < 0.4) continue;
    const s = 0.8 + rng() * 2.4;
    rocks.push({ x, z, s, y: heightAt(x, z) });
    if (s > 2.1) addCollider(x, z, s * 1.4, s * 1.4, heightAt(x, z), s * 1.2);
  }
  if (rocks.length) {
    const rm = new THREE.InstancedMesh(rockGeo, rockMat, rocks.length);
    const m = new THREE.Matrix4(), q = new THREE.Quaternion(), col = new THREE.Color();
    rocks.forEach((r, i) => {
      q.setFromEuler(new THREE.Euler(rng() * 3, rng() * 3, rng() * 3));
      m.compose(new THREE.Vector3(r.x, r.y + r.s * 0.25, r.z), q, new THREE.Vector3(r.s, r.s * 0.7, r.s));
      rm.setMatrixAt(i, m);
      rm.setColorAt(i, col.set(map.id === 'frost' ? '#b6c1c7' : map.id === 'dune' ? '#a9895f' : map.rock));
    });
    rm.castShadow = true; rm.receiveShadow = true; group.add(rm);
  }

  // grass
  if (map.id !== 'dune' && quality !== 'low') {
    const grassTex = canvasTexture(64, (ctx, s) => {
      ctx.clearRect(0, 0, s, s);
      for (let i = 0; i < 18; i++) {
        const x = 6 + Math.random() * (s - 12);
        ctx.strokeStyle = `rgba(${map.id === 'frost' ? '220,235,240' : '138,175,100'},${0.5 + Math.random() * 0.5})`;
        ctx.lineWidth = 1 + Math.random();
        ctx.beginPath(); ctx.moveTo(x, s); ctx.quadraticCurveTo(x + (Math.random() - 0.5) * 12, s * 0.5, x + (Math.random() - 0.5) * 18, Math.random() * s * 0.4); ctx.stroke();
      }
    });
    grassTex.colorSpace = THREE.SRGBColorSpace;
    const grassMat = new THREE.MeshBasicMaterial({ map: grassTex, transparent: true, alphaTest: 0.3, side: THREE.DoubleSide, depthWrite: false, opacity: 0.8 });
    const gGeo = new THREE.PlaneGeometry(1.3, 0.9);
    const count = quality === 'high' ? 1100 : 500;
    const gm = new THREE.InstancedMesh(gGeo, grassMat, count);
    const m = new THREE.Matrix4(), q = new THREE.Quaternion();
    let placed = 0;
    for (let i = 0; i < count * 3 && placed < count; i++) {
      const a = rng() * Math.PI * 2, r = 15 + Math.sqrt(rng()) * 250;
      const x = Math.cos(a) * r, z = Math.sin(a) * r;
      if (heightAt(x, z) < 0.8) continue;
      q.setFromEuler(new THREE.Euler(0, rng() * 6, 0));
      m.compose(new THREE.Vector3(x, heightAt(x, z) + 0.4, z), q, new THREE.Vector3(1, 1, 1));
      gm.setMatrixAt(placed++, m);
    }
    gm.count = placed; gm.frustumCulled = false;
    group.add(gm);
  }

  /* ---------------- clouds & atmosphere ---------------- */
  const cloudTex = smokeTexture(128);
  const cloudMat = new THREE.SpriteMaterial({ map: cloudTex, transparent: true, opacity: 0.14, depthWrite: false, color: new THREE.Color(map.skyHorizon) });
  const clouds = [];
  for (let i = 0; i < 10; i++) {
    const s = new THREE.Sprite(cloudMat.clone());
    s.position.set((rng() - 0.5) * 800, 75 + rng() * 50, (rng() - 0.5) * 800);
    s.scale.set(90 + rng() * 120, 26 + rng() * 20, 1);
    s.material.opacity = 0.07 + rng() * 0.1;
    group.add(s); clouds.push(s);
  }

  // weather particles
  let particles = null, particleData = null;
  const pCount = quality === 'high' ? 900 : quality === 'medium' ? 500 : 0;
  if (pCount) {
    const pg = new THREE.BufferGeometry();
    const p = new Float32Array(pCount * 3);
    particleData = [];
    for (let i = 0; i < pCount; i++) {
      const x = (rng() - 0.5) * 80, y = rng() * 30, z = (rng() - 0.5) * 80;
      p[i * 3] = x; p[i * 3 + 1] = y; p[i * 3 + 2] = z;
      particleData.push({ x, y, z, v: 0.4 + rng() * 1.2 });
    }
    pg.setAttribute('position', new THREE.BufferAttribute(p, 3));
    const pMat = new THREE.PointsMaterial({
      color: map.id === 'dune' ? 0xe8d4a8 : map.id === 'frost' ? 0xffffff : 0xd8e8a8,
      size: map.id === 'frost' ? 0.22 : 0.16, transparent: true, opacity: map.id === 'dune' ? 0.35 : 0.6,
      depthWrite: false, sizeAttenuation: true
    });
    particles = new THREE.Points(pg, pMat);
    particles.frustumCulled = false;
    group.add(particles);
  }

  /* ---------------- build batches ---------------- */
  bat.concrete.build(group);
  bat.metal.build(group);
  bat.wood.build(group);
  bat.stone.build(group);
  bat.dark.build(group);
  bat.glass.build(group, false);
  bat.cloth.build(group);
  bat.paint.build(group, false);
  bat.cyl.build(group);
  bat.cylDark.build(group);
  bat.cylWood.build(group);
  bat.cylStone.build(group);

  /* ---------------- minimap base ---------------- */
  const mini = document.createElement('canvas'); mini.width = mini.height = 512;
  const mctx = mini.getContext('2d');
  const mapScale = 512 / SIZE;
  const img = mctx.createImageData(512, 512);
  for (let py = 0; py < 512; py++) {
    for (let px = 0; px < 512; px++) {
      const wx = (px / 512) * SIZE - HALF, wz = (py / 512) * SIZE - HALF;
      const h = heightAt(wx, wz);
      let r, g, b;
      if (h < SEA + 0.3) {
        const deep = clamp(-h / 8, 0, 1);
        const wc = new THREE.Color(map.waterDeep).lerp(new THREE.Color(map.water), 1 - deep);
        r = wc.r * 255; g = wc.g * 255; b = wc.b * 255;
      } else if (h < 1.6) {
        const c = new THREE.Color(map.sand); r = c.r * 255; g = c.g * 255; b = c.b * 255;
      } else {
        const n = 0.5 + 0.5 * Math.sin(wx * 0.09 + Math.cos(wz * 0.07) * 3) * Math.cos(wz * 0.05);
        const c = new THREE.Color(map.minimap).lerp(new THREE.Color(map.groundB), n * 0.5);
        const shade = 0.85 + (h / 20);
        r = c.r * 255 * shade; g = c.g * 255 * shade; b = c.b * 255 * shade;
      }
      const i = (py * 512 + px) * 4;
      img.data[i] = r; img.data[i + 1] = g; img.data[i + 2] = b; img.data[i + 3] = 255;
    }
  }
  mctx.putImageData(img, 0, 0);
  // roads on minimap
  mctx.strokeStyle = 'rgba(225,214,184,.55)'; mctx.lineWidth = 2.2;
  for (const [a, b] of roadPairs) {
    mctx.beginPath(); mctx.moveTo((a.x + HALF) * mapScale, (a.z + HALF) * mapScale);
    mctx.lineTo((b.x + HALF) * mapScale, (b.z + HALF) * mapScale); mctx.stroke();
  }
  // grid
  mctx.strokeStyle = 'rgba(255,255,255,.1)'; mctx.lineWidth = 1;
  for (let i = 1; i < 8; i++) {
    mctx.beginPath(); mctx.moveTo(i * 64, 0); mctx.lineTo(i * 64, 512); mctx.stroke();
    mctx.beginPath(); mctx.moveTo(0, i * 64); mctx.lineTo(512, i * 64); mctx.stroke();
  }
  for (const p of map.pois) {
    const x = (p.x + HALF) * mapScale, y = (p.z + HALF) * mapScale;
    mctx.fillStyle = 'rgba(0,0,0,.55)'; mctx.beginPath(); mctx.arc(x, y, 4, 0, 7); mctx.fill();
    mctx.fillStyle = '#f4efe2'; mctx.beginPath(); mctx.arc(x, y, 2.2, 0, 7); mctx.fill();
    mctx.font = '600 11px "Chakra Petch", sans-serif';
    mctx.fillStyle = 'rgba(245,250,252,.88)';
    mctx.textAlign = 'center';
    mctx.fillText(p.name, x, y - 9);
  }
  const miniTex = new THREE.CanvasTexture(mini);
  miniTex.colorSpace = THREE.SRGBColorSpace;

  /* ---------------- ray queries ---------------- */
  const occluders = colliders;
  function rayBlock(origin, dir, maxDist) {
    let best = maxDist;
    for (let i = 0; i < occluders.length; i++) {
      const t = rayAABB(origin, dir, occluders[i], best);
      if (t >= 0 && t < best) best = t;
    }
    return best;
  }
  function collide(pos, radius, feetY) {
    // returns corrected x/z through pos mutation
    for (let i = 0; i < colliders.length; i++) {
      const c = colliders[i];
      if (feetY > c.maxY - 0.25 || feetY + 1.7 < c.minY) continue;
      const cx = clamp(pos.x, c.minX, c.maxX), cz = clamp(pos.z, c.minZ, c.maxZ);
      let dx = pos.x - cx, dz = pos.z - cz;
      let d2 = dx * dx + dz * dz;
      if (d2 < radius * radius) {
        if (d2 < 0.000001) {
          // inside: push toward nearest edge
          const dl = pos.x - c.minX, dr = c.maxX - pos.x, dt = pos.z - c.minZ, db = c.maxZ - pos.z;
          const m = Math.min(dl, dr, dt, db);
          if (m === dl) pos.x = c.minX - radius;
          else if (m === dr) pos.x = c.maxX + radius;
          else if (m === dt) pos.z = c.minZ - radius;
          else pos.z = c.maxZ + radius;
        } else {
          const d = Math.sqrt(d2);
          pos.x = cx + dx / d * radius;
          pos.z = cz + dz / d * radius;
        }
      }
    }
    const r = Math.hypot(pos.x, pos.z);
    if (r > 276) { pos.x *= 276 / r; pos.z *= 276 / r; }
    return pos;
  }
  function isSolidAt(x, z, y) {
    for (const c of colliders) {
      if (x > c.minX && x < c.maxX && z > c.minZ && z < c.maxZ && y > c.minY - 0.2 && y < c.maxY) return true;
    }
    return false;
  }

  /* ---------------- update ---------------- */
  let time = 0;
  function update(dt, playerPos) {
    time += dt;
    wTex.offset.x += dt * 0.004;
    wTex.offset.y += dt * 0.0022;
    sky.material.uniforms.uTime.value = time;
    if (playerPos) {
      sky.position.set(playerPos.x, 0, playerPos.z);
      sun.position.set(playerPos.x + sunDir.x * 170, 90 + sunDir.y * 90, playerPos.z + sunDir.z * 170);
      sun.target.position.set(playerPos.x, 0, playerPos.z);
      if (particles) {
        particles.position.set(playerPos.x, 0, playerPos.z);
        const arr = particles.geometry.attributes.position.array;
        for (let i = 0; i < particleData.length; i++) {
          const d = particleData[i];
          if (map.id === 'dune') {
            d.x += dt * (1.2 + d.v * 0.5); d.z += dt * 0.4;
            if (d.x > 40) d.x -= 80;
          } else {
            d.y -= dt * (1.4 + d.v);
            if (d.y < 0) { d.y = 30; d.x = (Math.random() - 0.5) * 80; d.z = (Math.random() - 0.5) * 80; }
            if (d.x > 40) d.x = -40;
          }
          arr[i * 3] = d.x; arr[i * 3 + 1] = d.y; arr[i * 3 + 2] = d.z;
        }
        particles.geometry.attributes.position.needsUpdate = true;
      }
    }
    for (const c of clouds) {
      c.position.x += dt * 1.4;
      if (c.position.x > 420) c.position.x = -420;
    }
  }

  function dispose() {
    scene.remove(group);
    scene.fog = null;
    group.traverse(o => {
      o.geometry?.dispose?.();
      if (o.material) (Array.isArray(o.material) ? o.material : [o.material]).forEach(m => { m.map?.dispose?.(); m.dispose?.(); });
      if (o.isInstancedMesh) o.dispose?.();
    });
    miniTex.dispose();
  }

  return {
    group, map, scene, heightAt, groundAt, colliders, lootSpots, vehicleSpots, spawnPoints,
    poiCenters, terrain, sun, sky, miniCanvas: mini, update, dispose, rayBlock, collide,
    isSolidAt, size: SIZE, half: HALF, sea: SEA,
    toMap: (x, z) => ({ x: (x + HALF) * mapScale, y: (z + HALF) * mapScale }),
    sunDir
  };
}

import * as THREE from 'three';
import { radialTexture, smokeTexture, rand } from './utils.js';

const flashTex = radialTexture('rgba(255,232,180,1)', 'rgba(255,110,20,0)', 128);
const sparkTex = radialTexture('rgba(255,255,255,1)', 'rgba(255,160,60,0)', 64);
const bloodTex = radialTexture('rgba(255,72,52,1)', 'rgba(120,0,0,0)', 64);
const dustTex = smokeTexture(128);

export class Effects {
  constructor(scene, camera) {
    this.scene = scene;
    this.camera = camera;
    this.tracers = [];
    this.flashes = [];
    this.sparks = [];
    this.smokes = [];
    this.dmgNums = [];
    this.container = document.getElementById('dmg-layer');
    this.tracerMat = new THREE.LineBasicMaterial({ color: 0xffc06a, transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false });

    // tracers
    for (let i = 0; i < 40; i++) {
      const geo = new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(), new THREE.Vector3()]);
      const line = new THREE.Line(geo, this.tracerMat.clone());
      line.visible = false; line.frustumCulled = false; scene.add(line);
      this.tracers.push({ line, life: 0, max: 0.09 });
    }
    // flashes / sparks
    const addSpritePool = (n, tex, blending) => {
      const arr = [];
      for (let i = 0; i < n; i++) {
        const mat = new THREE.SpriteMaterial({ map: tex, transparent: true, blending, depthWrite: false, depthTest: true });
        const s = new THREE.Sprite(mat); s.visible = false; scene.add(s);
        arr.push({ sprite: s, life: 0, max: 0.2, vel: new THREE.Vector3(), grow: 1 });
      }
      return arr;
    };
    this.flashes = addSpritePool(24, flashTex, THREE.AdditiveBlending);
    this.sparks = addSpritePool(60, sparkTex, THREE.AdditiveBlending);
    this.smokes = addSpritePool(40, dustTex, THREE.NormalBlending);
    this.smokes.forEach(p => { p.sprite.material.color.set(0xb9b2a6); p.grow = 1.8; });
  }

  _get(pool, tex) {
    let p = pool.find(x => x.life <= 0);
    if (!p) p = pool[0];
    p.sprite.visible = true; p.life = p.max = 0.16; p.vel.set(0, 0, 0); p.sprite.material.map = tex;
    return p;
  }

  muzzle(pos, color = '#ffbb66', scale = 1) {
    const p = this._get(this.flashes, flashTex);
    p.sprite.position.copy(pos);
    p.sprite.material.color.set(color);
    p.sprite.material.opacity = 1;
    p.sprite.scale.setScalar(0.55 * scale * rand(0.85, 1.2));
    p.life = p.max = 0.07;
    p.grow = 0.4;
  }

  tracer(from, to, color = 0xffc06a, width = 1) {
    const t = this.tracers.find(x => x.life <= 0) || this.tracers[0];
    const arr = t.line.geometry.attributes.position.array;
    arr[0] = from.x; arr[1] = from.y; arr[2] = from.z;
    arr[3] = to.x; arr[4] = to.y; arr[5] = to.z;
    t.line.geometry.attributes.position.needsUpdate = true;
    t.line.material.color.setHex(color);
    t.line.material.opacity = 0.9;
    t.line.visible = true;
    t.life = t.max = 0.09;
    t.line.computeLineDistances?.();
  }

  impact(pos, normal = null, color = '#ffca7a', blood = false) {
    const p = this._get(this.sparks, blood ? bloodTex : sparkTex);
    p.sprite.position.copy(pos);
    p.sprite.material.color.set(blood ? '#ff4a3a' : color);
    p.sprite.material.opacity = 0.95;
    p.sprite.material.blending = blood ? THREE.NormalBlending : THREE.AdditiveBlending;
    p.sprite.scale.setScalar(blood ? 0.5 : 0.32);
    p.life = p.max = 0.22; p.grow = 0.1;
    // sparks
    for (let i = 0; i < 3; i++) {
      const s = this._get(this.sparks, blood ? bloodTex : sparkTex);
      s.sprite.position.copy(pos);
      s.sprite.material.color.set(blood ? '#d42618' : color);
      s.sprite.material.opacity = 1;
      s.sprite.scale.setScalar(rand(0.06, 0.14));
      s.vel.set(rand(-1.4, 1.4), rand(0.3, 2), rand(-1.4, 1.4));
      if (normal) s.vel.addScaledVector(normal, rand(0.5, 1.5));
      s.life = s.max = rand(0.18, 0.35); s.grow = -0.3;
    }
    if (!blood && Math.random() > 0.5) {
      const s = this._get(this.smokes, dustTex);
      s.sprite.position.copy(pos);
      s.sprite.material.color.set('#b7ac9a');
      s.sprite.material.opacity = 0.22;
      s.sprite.scale.setScalar(0.5);
      s.vel.set(rand(-0.2, 0.2), rand(0.3, 0.8), rand(-0.2, 0.2));
      s.life = s.max = 0.7; s.grow = 1.2;
    }
  }

  explosion(pos, scale = 1) {
    for (let i = 0; i < 6; i++) {
      const p = this._get(this.flashes, flashTex);
      p.sprite.position.set(pos.x + rand(-1, 1), pos.y + rand(0, 1), pos.z + rand(-1, 1));
      p.sprite.material.color.set(i < 2 ? '#fff2c0' : '#ff7a1a');
      p.sprite.material.opacity = 0.9;
      p.sprite.scale.setScalar((1 + i * 0.5) * scale);
      p.life = p.max = 0.4 + i * 0.08; p.grow = 3;
    }
    for (let i = 0; i < 10; i++) {
      const s = this._get(this.smokes, dustTex);
      s.sprite.position.set(pos.x + rand(-1.5, 1.5), pos.y + rand(0, 1.5), pos.z + rand(-1.5, 1.5));
      s.sprite.material.color.set(i < 3 ? '#ff9a3a' : '#2e2a27');
      s.sprite.material.opacity = 0.5;
      s.sprite.scale.setScalar(rand(0.8, 1.8) * scale);
      s.vel.set(rand(-1, 1), rand(0.4, 1.6), rand(-1, 1));
      s.life = s.max = rand(0.9, 1.8); s.grow = 2.2;
    }
  }

  smoke(pos, color = '#c7bda9', opacity = 0.25, scale = 1.4, life = 1.4) {
    const s = this._get(this.smokes, dustTex);
    s.sprite.position.copy(pos);
    s.sprite.material.color.set(color);
    s.sprite.material.opacity = opacity;
    s.sprite.scale.setScalar(scale);
    s.vel.set(rand(-0.1, 0.1), rand(0.5, 1.1), rand(-0.1, 0.1));
    s.life = s.max = life; s.grow = 1.5;
  }

  damageNumber(worldPos, amount, crit = false, kill = false) {
    if (!this.container) return;
    if (this.dmgNums.length > 14) {
      const old = this.dmgNums.shift();
      old.el.remove();
    }
    const div = document.createElement('div');
    div.className = 'dmg-num' + (crit ? ' crit' : '') + (kill ? ' kill' : '');
    div.textContent = kill ? 'ELIMINATED' : (crit ? amount + '!' : amount);
    if (kill) div.style.fontSize = '15px';
    this.container.appendChild(div);
    this.dmgNums.push({ el: div, world: worldPos.clone(), life: 0.75, max: 0.75, randX: rand(-14, 14) });
  }

  update(dt) {
    const v = new THREE.Vector3();
    for (const t of this.tracers) {
      if (t.life > 0) {
        t.life -= dt;
        t.line.material.opacity = Math.max(0, t.life / t.max) * 0.85;
        if (t.life <= 0) t.line.visible = false;
      }
    }
    for (const pool of [this.flashes, this.sparks, this.smokes]) {
      for (const p of pool) {
        if (p.life <= 0) continue;
        p.life -= dt;
        if (p.life <= 0) { p.sprite.visible = false; continue; }
        const k = p.life / p.max;
        p.sprite.material.opacity = k * (pool === this.smokes ? 0.5 : 1);
        p.sprite.position.addScaledVector(p.vel, dt);
        p.sprite.scale.x += (p.grow > 0 ? p.grow : p.grow) * dt * 0.6;
        p.sprite.scale.y = p.sprite.scale.x;
      }
    }
    for (let i = this.dmgNums.length - 1; i >= 0; i--) {
      const d = this.dmgNums[i];
      d.life -= dt;
      if (d.life <= 0) { d.el.remove(); this.dmgNums.splice(i, 1); continue; }
      v.copy(d.world).project(this.camera);
      if (v.z > 1 || v.z < -1) { d.el.style.display = 'none'; continue; }
      d.el.style.display = '';
      d.el.style.left = ((v.x * 0.5 + 0.5) * 100) + '%';
      d.el.style.top = ((-v.y * 0.5 + 0.5) * 100 + d.randX * 0.01) + '%';
    }
  }

  clear() {
    for (const t of this.tracers) { t.life = 0; t.line.visible = false; }
    for (const pool of [this.flashes, this.sparks, this.smokes]) for (const p of pool) { p.life = 0; p.sprite.visible = false; }
    for (const d of this.dmgNums) d.el.remove();
    this.dmgNums.length = 0;
  }
}

import { clamp } from './utils.js';

export class Input {
  constructor() {
    this.keys = new Set();
    this.enabled = false;
    this.isTouch = matchMedia('(pointer: coarse)').matches || 'ontouchstart' in window;
    this.mouse = { dx: 0, dy: 0, locked: false, left: false, right: false };
    this.firing = false;
    this.aiming = false;
    this.adsToggle = false;
    this.sprintToggle = false;
    this.crouchToggle = false;
    this.joy = { x: 0, y: 0, active: false, pointerId: null, ox: 0, oy: 0 };
    this.touchLook = { active: false, pointerId: null, lastX: 0, lastY: 0 };
    this.listeners = {};
    this.canvas = document.getElementById('stage');
    this.hud = document.getElementById('hud');
    this.stickZone = document.getElementById('stick-zone');
    this.stickBase = document.getElementById('stick-base');
    this.stickKnob = document.getElementById('stick-knob');
    this.fireBtn = document.getElementById('t-fire');
    this.adsBtn = document.getElementById('t-ads');
    this.bindKeyboard();
    this.bindMouse();
    this.bindTouch();
    this.createLookZone();
    document.addEventListener('pointerlockchange', () => {
      this.mouse.locked = document.pointerLockElement === this.canvas;
      if (!this.mouse.locked && this.enabled) this.emit('unlock');
    });
  }

  on(name, fn) { (this.listeners[name] ||= []).push(fn); }
  emit(name, arg) { (this.listeners[name] || []).forEach(f => f(arg)); }

  setEnabled(on) {
    this.enabled = on;
    if (!on) {
      this.keys.clear(); this.firing = false; this.aiming = false;
      this.mouse.left = this.mouse.right = false;
      if (document.pointerLockElement) document.exitPointerLock();
      this.resetJoystick();
      document.getElementById('touch-ui')?.classList.add('hidden');
      document.body.classList.remove('playing');
    } else {
      if (this.isTouch) document.getElementById('touch-ui')?.classList.remove('hidden');
      document.body.classList.add('playing');
    }
  }

  createLookZone() {
    const z = document.createElement('div');
    z.className = 'look-zone';
    z.id = 'look-zone';
    this.hud.appendChild(z);
    this.lookZone = z;
    z.addEventListener('pointerdown', e => {
      if (!this.enabled || !this.isTouch) return;
      e.preventDefault();
      this.touchLook.active = true; this.touchLook.pointerId = e.pointerId;
      this.touchLook.lastX = e.clientX; this.touchLook.lastY = e.clientY;
      z.setPointerCapture(e.pointerId);
    });
    z.addEventListener('pointermove', e => {
      if (!this.touchLook.active || e.pointerId !== this.touchLook.pointerId) return;
      this.mouse.dx += e.clientX - this.touchLook.lastX;
      this.mouse.dy += e.clientY - this.touchLook.lastY;
      this.touchLook.lastX = e.clientX; this.touchLook.lastY = e.clientY;
    });
    const end = e => { if (e.pointerId === this.touchLook.pointerId) this.touchLook.active = false; };
    z.addEventListener('pointerup', end);
    z.addEventListener('pointercancel', end);
  }

  bindKeyboard() {
    window.addEventListener('keydown', e => {
      if (!this.enabled) return;
      const k = e.code;
      if (['Space', 'Tab', 'ControlLeft', 'ShiftLeft', 'KeyR', 'KeyF', 'KeyH', 'KeyJ', 'Digit1', 'Digit2', 'Digit3'].includes(k)) e.preventDefault();
      if (e.repeat) { this.keys.add(k); return; }
      this.keys.add(k);
      switch (k) {
        case 'Space': this.emit('jump'); break;
        case 'ControlLeft': case 'KeyC': this.emit('crouch'); break;
        case 'KeyR': this.emit('reload'); break;
        case 'KeyF': this.emit('interact'); break;
        case 'KeyH': this.emit('med'); break;
        case 'KeyJ': this.emit('shield'); break;
        case 'Digit1': this.emit('slot', 0); break;
        case 'Digit2': this.emit('slot', 1); break;
        case 'Digit3': this.emit('slot', 2); break;
        case 'Tab': this.emit('scoreboard', true); break;
        case 'Escape': this.emit('pause'); break;
        case 'KeyQ': this.emit('swap'); break;
      }
      if (k === 'ShiftLeft') this.emit('sprint', true);
    });
    window.addEventListener('keyup', e => {
      this.keys.delete(e.code);
      if (e.code === 'ShiftLeft') this.emit('sprint', false);
      if (e.code === 'Tab') this.emit('scoreboard', false);
      if (e.code === 'ControlLeft' || e.code === 'KeyC') this.emit('crouchRelease');
    });
  }

  bindMouse() {
    this.canvas.addEventListener('mousedown', e => {
      if (!this.enabled) return;
      if (!this.mouse.locked) {
        if (this.isTouch) return;
        this.canvas.requestPointerLock?.();
        return;
      }
      if (e.button === 0) { this.mouse.left = true; this.firing = true; }
      if (e.button === 2) { this.mouse.right = true; this.aiming = true; }
    });
    window.addEventListener('mouseup', e => {
      if (e.button === 0) { this.mouse.left = false; this.firing = false; }
      if (e.button === 2) { this.mouse.right = false; this.aiming = this.adsToggle; }
    });
    window.addEventListener('mousemove', e => {
      if (!this.enabled || !this.mouse.locked) return;
      this.mouse.dx += e.movementX || 0;
      this.mouse.dy += e.movementY || 0;
    });
    window.addEventListener('contextmenu', e => { if (this.enabled) e.preventDefault(); });
    window.addEventListener('wheel', e => {
      if (!this.enabled) return;
      e.preventDefault();
      this.emit('swap', e.deltaY > 0 ? 1 : -1);
    }, { passive: false });
  }

  bindTouch() {
    const zone = this.stickZone;
    const base = this.stickBase, knob = this.stickKnob;
    const maxR = 44;
    const setKnob = (dx, dy) => {
      const d = Math.hypot(dx, dy);
      const cl = d > maxR ? maxR / d : 1;
      knob.style.transform = `translate(${dx * cl}px,${dy * cl}px)`;
      this.joy.x = clamp(dx / maxR, -1, 1);
      this.joy.y = clamp(dy / maxR, -1, 1);
      const mag = Math.min(1, Math.hypot(this.joy.x, this.joy.y));
      if (mag > 0.25 && !this.joy.active) this.joy.active = true;
      base.classList.add('active');
    };
    zone.addEventListener('pointerdown', e => {
      if (!this.enabled) return;
      e.preventDefault();
      this.joy.pointerId = e.pointerId;
      const rect = base.getBoundingClientRect();
      this.joy.ox = rect.left + rect.width / 2;
      this.joy.oy = rect.top + rect.height / 2;
      // move stick under thumb
      const bx = rect.width / 2;
      base.style.left = (e.clientX - bx) + 'px';
      base.style.top = (e.clientY - bx) + 'px';
      base.style.bottom = 'auto';
      this.joy.ox = e.clientX; this.joy.oy = e.clientY;
      setKnob(0, 0);
      zone.setPointerCapture(e.pointerId);
    });
    zone.addEventListener('pointermove', e => {
      if (e.pointerId !== this.joy.pointerId) return;
      setKnob(e.clientX - this.joy.ox, e.clientY - this.joy.oy);
    });
    const end = e => {
      if (e.pointerId !== this.joy.pointerId) return;
      this.resetJoystick();
    };
    zone.addEventListener('pointerup', end);
    zone.addEventListener('pointercancel', end);

    const hold = (el, on, off) => {
      el.addEventListener('pointerdown', e => {
        if (!this.enabled) return;
        e.preventDefault(); e.stopPropagation();
        el.classList.add('on');
        el.setPointerCapture?.(e.pointerId);
        on?.();
      });
      const up = e => { el.classList.remove('on'); off?.(); };
      el.addEventListener('pointerup', up);
      el.addEventListener('pointercancel', up);
      el.addEventListener('pointerleave', e => { if (e.buttons === 0) up(e); });
    };
    hold(this.fireBtn, () => { this.firing = true; this.emit('fireStart'); }, () => { this.firing = false; });
    hold(this.adsBtn, () => {
      this.adsToggle = !this.adsToggle;
      this.aiming = this.adsToggle;
      this.adsBtn.classList.toggle('on', this.adsToggle);
      this.emit('ads', this.adsToggle);
    });
    const tap = (id, fn) => {
      const el = document.getElementById(id);
      if (!el) return;
      el.addEventListener('pointerdown', e => {
        if (!this.enabled) return;
        e.preventDefault(); e.stopPropagation();
        el.classList.add('on');
        fn(el);
      });
      const up = () => el.classList.remove('on');
      el.addEventListener('pointerup', up);
      el.addEventListener('pointercancel', up);
    };
    tap('t-jump', () => this.emit('jump'));
    tap('t-crouch', () => { this.crouchToggle = !this.crouchToggle; this.emit('crouch', this.crouchToggle); });
    tap('t-reload', () => this.emit('reload'));
    tap('t-swap', () => this.emit('swap'));
    tap('t-sprint', el => { this.sprintToggle = !this.sprintToggle; el.classList.toggle('on', this.sprintToggle); });
    tap('t-interact', () => this.emit('interact'));
    // prevent iOS scroll / zoom gestures on HUD
    document.addEventListener('gesturestart', e => e.preventDefault());
    this.hud.addEventListener('touchmove', e => { if (this.enabled && e.target.closest('.look-zone,#stick-zone')) e.preventDefault(); }, { passive: false });
  }

  resetJoystick() {
    this.joy.x = 0; this.joy.y = 0; this.joy.active = false; this.joy.pointerId = null;
    this.stickKnob.style.transform = 'translate(0,0)';
    this.stickBase.classList.remove('active');
    this.stickBase.style.left = ''; this.stickBase.style.top = ''; this.stickBase.style.bottom = '';
  }

  get moving() {
    const k = this.keys;
    return k.has('KeyW') || k.has('KeyA') || k.has('KeyS') || k.has('KeyD') ||
      Math.abs(this.joy.x) > 0.18 || Math.abs(this.joy.y) > 0.18;
  }
  get forward() {
    let f = 0;
    if (this.keys.has('KeyW')) f += 1;
    if (this.keys.has('KeyS')) f -= 1;
    f -= this.joy.y;
    return clamp(f, -1, 1);
  }
  get strafe() {
    let s = 0;
    if (this.keys.has('KeyD')) s += 1;
    if (this.keys.has('KeyA')) s -= 1;
    s += this.joy.x;
    return clamp(s, -1, 1);
  }
  get sprinting() { return this.keys.has('ShiftLeft') || this.keys.has('ShiftRight') || this.sprintToggle; }
  get crouching() { return this.keys.has('ControlLeft') || this.keys.has('KeyC') || this.crouchToggle; }

  consumeLook() {
    const dx = this.mouse.dx, dy = this.mouse.dy;
    this.mouse.dx = 0; this.mouse.dy = 0;
    return { dx, dy };
  }
}

import * as THREE from 'three';
import { clamp, damp, lerp, rand, deg } from './utils.js';
import { WEAPONS } from './config.js';
import { createWeaponModel } from './models.js';
import { audio } from './audio.js';

const EYE_STAND = 1.62;
const EYE_CROUCH = 1.08;

export class Player {
  constructor(game, profile) {
    this.game = game;
    this.profile = profile;
    this.camera = game.camera;
    this.scene = game.scene;
    this.world = game.world;
    this.pos = new THREE.Vector3(0, 40, 0);
    this.vel = new THREE.Vector3();
    this.yaw = 0; this.pitch = 0;
    this.eyeHeight = EYE_STAND;
    this.grounded = false;
    this.health = 100; this.shield = 0; this.maxShield = 100;
    this.alive = true;
    this.kills = 0; this.damageDealt = 0; this.headshots = 0; this.shots = 0; this.hits = 0;
    this.mode = 'fps';
    this.speed = 0;
    this.bobPhase = 0;
    this.recoilPitch = 0; this.recoilYaw = 0; this.recoilRoll = 0;
    this.landKick = 0;
    this.inWater = false;
    this.medkits = 2; this.shields = 1;
    this.useCooldown = 0;
    this.stepTimer = 0;
    this.lastDamageTime = 0;
    this.regenTimer = 0;
    this.sprinting = false;
    this.crouching = false;
    this.aiming = false;
    this.adsAmount = 0;
    this.scoped = false;
    this.spreadHeat = 0;
    this.weaponIndex = 0;
    this.reloadTimer = 0;
    this.fireTimer = 0;
    this.switchTimer = 0;
    this.muzzleTimer = 0;
    this.weaponKick = 0;
    this.weaponRoll = 0;
    this.cameraShake = 0;
    this.weapons = [];
    this.baseFov = profile.settings.fov || 74;
    this.viewGroup = new THREE.Group();
    this.camera.add(this.viewGroup);
    this.gunRoot = null;
    this.weaponModel = null;
    this.hands = null;
    this.setupWeapons();
  }

  setupWeapons() {
    const g = this.game;
    const m = g.mode;
    const ids = [this.profile.primary, this.profile.secondary];
    for (const id of ids) {
      const def = WEAPONS[id] || WEAPONS.vanguard;
      const reserve = m.infiniteAmmo ? 999 : def.reserve * (m.startAmmo || 1);
      this.weapons.push({ def, mag: def.mag, reserve });
    }
    this.equip(0, true);
    this.health = 100;
    this.shield = m.armor || 0;
    this.maxShield = 100;
  }

  spawn(x, z, y = null) {
    const gy = y != null ? y : this.world.heightAt(x, z);
    this.pos.set(x, gy + 0.05, z);
    this.vel.set(0, 0, 0);
    this.yaw = rand(0, Math.PI * 2); this.pitch = 0;
    this.alive = true;
    this.mode = 'fps';
    this.eyeHeight = EYE_STAND;
    this.syncCamera(0);
  }

  get weapon() { return this.weapons[this.weaponIndex]; }
  get def() { return this.weapon.def; }

  equip(i, instant = false) {
    if (i < 0 || i >= this.weapons.length) return;
    if (this.weaponIndex === i && !instant) return;
    this.weaponIndex = i;
    this.reloadTimer = 0;
    this.switchTimer = instant ? 0 : 0.28;
    this.fireTimer = Math.max(this.fireTimer, 0.2);
    this.buildViewModel();
    if (!instant) audio.equip();
    this.game.onWeaponChanged?.();
  }

  equipId(id) {
    // replace current slot with picked-up weapon, or fill an empty slot
    const def = WEAPONS[id];
    if (!def) return false;
    const existing = this.weapons.findIndex(w => w.def.id === id);
    if (existing >= 0) { this.equip(existing); return true; }
    let slot = this.weapons.findIndex(w => !w.def || w.def.id === 'fists');
    if (def.slot === 'secondary') slot = 1;
    if (def.slot === 'primary' && this.weapons.length < 2) slot = this.weapons.length;
    if (slot < 0) slot = this.weaponIndex;
    this.weapons[slot] = { def, mag: def.mag, reserve: def.reserve, picked: true };
    this.equip(slot);
    // refill ammo of other weapon too for pickup convenience
    return true;
  }

  buildViewModel() {
    if (this.gunRoot) {
      this.viewGroup.remove(this.gunRoot);
      this.gunRoot.traverse(o => { if (o.isMesh) { o.geometry?.dispose?.(); } });
      this.gunRoot = null;
    }
    const def = this.def;
    const g = new THREE.Group();
    const weapon = createWeaponModel(def.id, this.profile.outfitAccent);
    weapon.traverse(o => { if (o.isMesh) { o.castShadow = false; o.receiveShadow = false; } });
    g.add(weapon);
    // gloved hands
    const skinMat = new THREE.MeshStandardMaterial({ color: 0x1b2025, roughness: 0.8 });
    const glove1 = new THREE.Mesh(new THREE.BoxGeometry(0.11, 0.14, 0.16), skinMat); glove1.position.set(0.01, -0.12, 0.1); g.add(glove1);
    const glove2 = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.12, 0.17), skinMat); glove2.position.set(-0.03, -0.05, -0.22); glove2.rotation.x = -0.15; g.add(glove2);
    const armMat = new THREE.MeshStandardMaterial({ color: new THREE.Color(this.profile.outfitTop || '#252b33'), roughness: 0.9 });
    const arm1 = new THREE.Mesh(new THREE.BoxGeometry(0.13, 0.13, 0.36), armMat); arm1.position.set(0.08, -0.26, 0.2); arm1.rotation.x = 0.2; g.add(arm1);
    const arm2 = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.12, 0.3), armMat); arm2.position.set(-0.08, -0.19, -0.1); arm2.rotation.x = -0.1; g.add(arm2);
    this.viewGroup.add(g);
    this.gunRoot = g;
    this.weaponModel = weapon;
    this.gunBasePos = new THREE.Vector3(0.24, -0.235, -0.48);
    this.gunAdsPos = new THREE.Vector3(0, -0.16, -0.36);
    g.position.copy(this.gunBasePos);
    g.rotation.set(0.01, 0.02, 0);
    this.game.onWeaponChanged?.();
  }

  /* ---------------- movement ---------------- */
  update(dt, input) {
    if (!this.alive) { this.updateCameraShake(dt); return; }
    const look = input.consumeLook();
    const sens = (this.profile.settings.sens || 1) * (this.aiming ? 0.62 : 1) * 0.0022;
    this.yaw -= look.dx * sens * (this.profile.settings.inverted ? -1 : 1);
    this.pitch -= look.dy * sens;
    this.pitch = clamp(this.pitch, -1.42, 1.42);

    this.aiming = this.mode === 'fps' && (input.aiming);
    this.adsAmount = damp(this.adsAmount, this.aiming ? 1 : 0, 12, dt);
    this.scoped = this.aiming && this.def.zoom > 3 && this.adsAmount > 0.6;

    const crouchWanted = input.crouching && this.mode === 'fps';
    this.crouching = crouchWanted;
    const targetEye = crouchWanted ? EYE_CROUCH : EYE_STAND;
    this.eyeHeight = damp(this.eyeHeight, targetEye, 12, dt);

    let wx = 0, wz = 0;
    if (this.mode === 'fps') {
      const f = input.forward, s = input.strafe;
      const len = Math.hypot(f, s);
      const sprinting = input.sprinting && !this.aiming && !crouchWanted && f > 0.2;
      this.sprinting = sprinting;
      let speed = crouchWanted ? 2.6 : (sprinting ? 7.2 : 4.85);
      if (this.aiming) speed = 2.9;
      if (this.inWater) speed *= 0.6;
      if (len > 0.01) {
        const nf = f / Math.max(len, 1), ns = s / Math.max(len, 1);
        const sin = Math.sin(this.yaw), cos = Math.cos(this.yaw);
        wx = (-sin * nf + cos * ns) * speed;
        wz = (-cos * nf - sin * ns) * speed;
      }
    }
    const accel = this.grounded ? 14 : 3.2;
    this.vel.x = damp(this.vel.x, wx, accel, dt);
    this.vel.z = damp(this.vel.z, wz, accel, dt);
    this.vel.y -= 21 * dt;

    const oldY = this.pos.y;
    this.pos.x += this.vel.x * dt;
    this.pos.z += this.vel.z * dt;
    this.world.collide(this.pos, 0.4, this.pos.y);
    this.pos.y += this.vel.y * dt;

    const ground = Math.max(this.world.heightAt(this.pos.x, this.pos.z), this.world.sea - 0.82);
    this.inWater = this.world.heightAt(this.pos.x, this.pos.z) < this.world.sea - 0.1;
    if (this.pos.y <= ground) {
      if (this.vel.y < -7) { this.landKick = clamp(-this.vel.y * 0.008, 0.02, 0.09); audio.land(); }
      this.pos.y = ground;
      this.vel.y = 0;
      this.grounded = true;
    } else {
      this.grounded = false;
    }
    this.speed = Math.hypot(this.vel.x, this.vel.z);

    // footsteps + bob
    if (this.grounded && this.speed > 1.2) {
      this.bobPhase += dt * (this.sprinting ? 11 : 8) * (this.crouching ? 0.6 : 1);
      this.stepTimer -= dt;
      if (this.stepTimer <= 0) {
        this.stepTimer = this.sprinting ? 0.27 : 0.38;
        audio.step();
      }
    }
    this.landKick = damp(this.landKick, 0, 8, dt);
    this.recoilPitch = damp(this.recoilPitch, 0, 9, dt);
    this.recoilYaw = damp(this.recoilYaw, 0, 9, dt);
    this.recoilRoll = damp(this.recoilRoll, 0, 8, dt);
    this.cameraShake = damp(this.cameraShake, 0, 11, dt);

    // health regen after 9s
    if (this.alive && this.health < 100 && this.game.time - this.lastDamageTime > 9) {
      this.health = Math.min(100, this.health + dt * 3.2);
    }
    this.useCooldown = Math.max(0, this.useCooldown - dt);
    this.syncCamera(dt);
    this.updateWeapon(dt, input);
    this.updateViewModel(dt);
  }

  syncCamera(dt) {
    const bobAmt = clamp(this.speed / 7, 0, 1) * (this.grounded ? 1 : 0) * (1 - this.adsAmount * 0.8);
    const bx = Math.cos(this.bobPhase) * 0.035 * bobAmt;
    const by = Math.abs(Math.sin(this.bobPhase)) * 0.045 * bobAmt;
    const shake = this.cameraShake;
    const sx = (Math.random() - 0.5) * shake, sy = (Math.random() - 0.5) * shake;
    this.camera.position.set(
      this.pos.x + bx * Math.cos(this.yaw) + sx,
      this.pos.y + this.eyeHeight + by - this.landKick + sy,
      this.pos.z - bx * Math.sin(this.yaw)
    );
    this.camera.rotation.order = 'YXZ';
    this.camera.rotation.set(this.pitch + this.recoilPitch, this.yaw + this.recoilYaw, this.recoilRoll);
    const baseFov = this.baseFov;
    const targetFov = this.aiming ? baseFov / this.def.zoom : baseFov;
    if (Math.abs(this.camera.fov - targetFov) > 0.05) {
      this.camera.fov = damp(this.camera.fov, targetFov, 18, dt || 0.016);
      this.camera.updateProjectionMatrix();
    }
  }

  updateCameraShake(dt) {
    this.cameraShake = damp(this.cameraShake, 0, 10, dt);
    this.camera.rotation.set(this.pitch, this.yaw, this.recoilRoll);
    this.camera.position.y = damp(this.camera.position.y, this.pos.y + 0.4, 8, dt);
  }

  updateViewModel(dt) {
    if (!this.gunRoot) return;
    const target = new THREE.Vector3().copy(this.gunBasePos).lerp(this.gunAdsPos, this.adsAmount);
    const sway = clamp(this.speed / 7, 0, 1) * (1 - this.adsAmount * 0.85);
    target.x += Math.cos(this.bobPhase) * 0.012 * sway;
    target.y += Math.sin(this.bobPhase * 2) * 0.012 * sway;
    this.weaponKick = damp(this.weaponKick, 0, 12, dt);
    this.weaponRoll = damp(this.weaponRoll, 0, 10, dt);
    target.z += this.weaponKick * 0.12;
    this.gunRoot.position.lerp(target, 1 - Math.exp(-18 * dt));
    this.gunRoot.rotation.x = 0.01 - this.weaponKick * 0.22 + (1 - this.adsAmount) * 0.04;
    this.gunRoot.rotation.y = 0.03 * (1 - this.adsAmount);
    this.gunRoot.rotation.z = this.weaponRoll;
    if (this.reloadTimer > 0) {
      const total = this.def.reload;
      const k = 1 - this.reloadTimer / total;
      const dip = Math.sin(k * Math.PI);
      this.gunRoot.position.y -= dip * 0.25;
      this.gunRoot.rotation.x -= dip * 0.5;
      this.gunRoot.rotation.z += dip * 0.4;
    }
    if (this.switchTimer > 0) {
      const k = this.switchTimer / 0.28;
      this.gunRoot.position.y -= k * 0.35;
    }
  }

  updateWeapon(dt, input) {
    const w = this.weapon;
    this.fireTimer = Math.max(0, this.fireTimer - dt);
    this.switchTimer = Math.max(0, this.switchTimer - dt);
    this.spreadHeat = Math.max(0, this.spreadHeat - dt * 2.6);
    if (this.reloadTimer > 0) {
      this.reloadTimer -= dt;
      if (this.reloadTimer <= 0) this.finishReload();
      return;
    }
    if (this.switchTimer > 0) return;
    if (this.mode !== 'fps') return;
    if (input.firing && this.fireTimer <= 0) {
      if (w.def.auto || !this.triggerHeld) {
        this.tryFire();
      }
    }
    this.triggerHeld = input.firing;
  }

  tryFire() {
    const w = this.weapon, def = w.def;
    if (!this.alive) return;
    if (w.mag <= 0) {
      audio.empty();
      this.fireTimer = 0.25;
      this.game.hud?.flashAmmo();
      return;
    }
    w.mag--;
    this.fireTimer = 60 / def.rpm;
    this.shots++;
    this.weaponKick = 1;
    this.weaponRoll = rand(-0.04, 0.04);
    this.spreadHeat = clamp(this.spreadHeat + 0.22, 0, 2.6);
    const spread = this.currentSpread();
    for (let p = 0; p < def.pellets; p++) {
      const dir = this.camera.getWorldDirection(new THREE.Vector3());
      const right = new THREE.Vector3().crossVectors(dir, new THREE.Vector3(0, 1, 0)).normalize();
      const up = new THREE.Vector3().crossVectors(right, dir).normalize();
      const a = rand(0, Math.PI * 2), r = Math.tan(deg(spread)) * Math.sqrt(Math.random());
      dir.addScaledVector(right, Math.cos(a) * r).addScaledVector(up, Math.sin(a) * r).normalize();
      const origin = this.camera.position.clone();
      const hit = this.game.castShot(origin, dir, def.range, this);
      const end = hit.point;
      const muzzleWorld = this.getMuzzleWorld();
      this.game.effects.tracer(muzzleWorld, end, def.id === 'longshot' ? 0xbfe4ff : 0xffc06a);
      if (hit.bot) {
        const dist = hit.distance;
        let dmg = def.dmg;
        if (def.pellets > 1) dmg *= clamp(1 - dist / (def.range * 1.2), 0.25, 1);
        if (def.falloff && dist > def.falloff[0]) {
          const t = clamp((dist - def.falloff[0]) / (def.falloff[1] - def.falloff[0]), 0, 1);
          dmg *= lerp(1, def.falloff[2], t);
        }
        if (hit.zone === 'head') dmg *= 2.1;
        else if (hit.zone === 'leg') dmg *= 0.8;
        this.hits++;
        if (hit.zone === 'head') this.headshots++;
        this.game.damageBot(hit.bot, Math.round(dmg), this, hit.point, hit.zone === 'head', def);
        this.game.effects.impact(hit.point, hit.normal, '#ffca7a', true);
        audio.hit(hit.zone === 'head');
      } else {
        this.game.effects.impact(hit.point, hit.normal, '#ffd08a', false);
      }
    }
    this.recoilPitch += deg(def.recoil * 0.32) * (1 - this.adsAmount * 0.38);
    this.recoilYaw += rand(-1, 1) * deg(def.recoil * 0.1) * (1 - this.adsAmount * 0.5);
    this.recoilRoll += rand(-1, 1) * deg(0.35);
    this.cameraShake = Math.max(this.cameraShake, def.recoil * 0.006);
    const muzzleWorld = this.getMuzzleWorld();
    this.game.effects.muzzle(muzzleWorld, '#ffd08a', def.pellets > 5 ? 1.6 : 1);
    audio.shot(def.model, 0);
    this.game.onShot?.();
    if (w.mag === 0) this.startReload();
    this.game.hud?.updateAmmo();
  }

  currentSpread() {
    const def = this.def;
    let s = def.spread;
    const move = clamp(this.speed / 7, 0, 1);
    s += move * (def.moveSpread || 1) * 2.2;
    s += this.spreadHeat * 0.55;
    if (this.aiming) s = lerp(s, def.adsSpread, this.adsAmount) * 0.5;
    if (this.crouching) s *= 0.72;
    return s;
  }

  getMuzzleWorld() {
    const forward = this.camera.getWorldDirection(new THREE.Vector3());
    const right = new THREE.Vector3().crossVectors(forward, new THREE.Vector3(0, 1, 0)).normalize();
    return this.camera.position.clone().addScaledVector(forward, 0.75 + this.adsAmount * 0.2).addScaledVector(right, 0.18 * (1 - this.adsAmount)).add(new THREE.Vector3(0, -0.1, 0));
  }

  startReload() {
    const w = this.weapon, def = w.def;
    if (this.reloadTimer > 0 || w.mag >= def.mag || w.reserve <= 0) return;
    this.reloadTimer = def.reload;
    audio.reload();
    this.game.hud?.startReload(def.reload);
  }
  finishReload() {
    const w = this.weapon, def = w.def;
    const need = def.mag - w.mag;
    const take = this.game.mode.infiniteAmmo ? need : Math.min(need, w.reserve);
    w.mag += take;
    if (!this.game.mode.infiniteAmmo) w.reserve -= take;
    this.game.hud?.updateAmmo();
  }

  jump() {
    if (!this.alive || this.mode !== 'fps') return;
    if (this.grounded) {
      this.vel.y = 6.7;
      this.grounded = false;
      this.landKick = 0.015;
    }
  }

  heal(amount = 50) {
    if (!this.alive) return false;
    if (this.medkits <= 0) return false;
    if (this.health >= 100) return false;
    this.medkits--;
    this.health = Math.min(100, this.health + amount);
    audio.heal();
    this.game.hud?.updateVitals();
    this.game.hud?.toast('MEDKIT USED', '+50 HEALTH');
    return true;
  }
  useShield(amount = 50) {
    if (!this.alive) return false;
    if (this.shields <= 0) return false;
    if (this.shield >= this.maxShield) return false;
    this.shields--;
    this.shield = Math.min(this.maxShield, this.shield + amount);
    audio.shield();
    this.game.hud?.updateVitals();
    this.game.hud?.toast('SHIELD CELL', '+50 ARMOR');
    return true;
  }

  takeDamage(amount, source, point = null) {
    if (!this.alive || this.game.godMode) return;
    this.lastDamageTime = this.game.time;
    this.regenTimer = 0;
    if (this.shield > 0) {
      const absorbed = Math.min(this.shield, amount * 0.66);
      this.shield -= absorbed;
      amount -= absorbed;
      this.game.hud?.hitFlash(0.3);
    }
    this.health -= amount;
    this.cameraShake = 0.03;
    audio.hit(false);
    this.game.hud?.damageIndicator(source ? source.pos : null);
    this.game.hud?.updateVitals();
    this.game.hud?.hitFlash(0.75);
    if (this.health <= 0) {
      this.health = 0;
      this.die(source);
    }
  }

  die(source) {
    if (!this.alive) return;
    this.alive = false;
    this.mode = 'dead';
    this.adsAmount = 0; this.aiming = false;
    this.game.onPlayerDeath?.(source);
  }

  resetForRespawn(x, z) {
    this.alive = true;
    this.health = 100;
    this.shield = this.game.mode.armor || 0;
    this.pos.set(x, this.world.heightAt(x, z) + 0.05, z);
    this.vel.set(0, 0, 0);
    this.mode = 'fps';
    this.weapons.forEach(w => { w.mag = w.def.mag; w.reserve = w.def.reserve * (this.game.mode.startAmmo || 1); });
    this.equip(0, true);
    this.medkits = 2; this.shields = 1;
  }
}

import * as THREE from 'three';
import { clamp, damp, rand, randInt, pick, deg, angleDelta } from './utils.js';
import { createHumanoid, createNameTag, createWeaponModel, createPickupModel } from './models.js';
import { WEAPONS, OUTFITS, SKINS, HELMETS, BOT_NAMES } from './config.js';
import { audio } from './audio.js';

const BOT_OUTFITS = ['#252b33', '#2f3b33', '#3d3134', '#32322d', '#293546', '#463a2a', '#3a2c38', '#2c3c45'];
const BOT_PANTS = ['#343c46', '#2a312e', '#3a2e30', '#2c2c28', '#2c3540', '#3b3227', '#2f2632', '#2a343c'];
const ACCENTS = ['#ff7a1a', '#ff4545', '#25ddc3', '#ffc74a', '#9c7dff', '#4fa8ff'];

class Bot {
  constructor(mgr, opts) {
    this.mgr = mgr;
    this.game = mgr.game;
    this.world = mgr.world;
    this.name = opts.name;
    this.team = opts.team;
    this.teamColor = this.team === 0 && mgr.game.mode.id !== 'br' ? '#25ddc3' : '#ff5a45';
    this.outfit = opts.outfit;
    this.skin = opts.skin;
    this.helmet = opts.helmet;
    this.weaponDef = opts.weapon;
    this.health = 100;
    this.maxHealth = 100;
    this.alive = true;
    this.pos = new THREE.Vector3(opts.x, opts.y, opts.z);
    this.vel = new THREE.Vector3();
    this.yaw = rand(0, Math.PI * 2);
    this.state = 'patrol';
    this.target = null;
    this.targetTimer = 0;
    this.fireTimer = rand(0.4, 1.6);
    this.strafeDir = Math.random() > 0.5 ? 1 : -1;
    this.dest = new THREE.Vector3(opts.x + rand(-12, 12), 0, opts.z + rand(-12, 12));
    this.speed = rand(2.6, 4.4);
    this.skill = rand(0.35, 0.78);
    this.lastDamage = -99;
    this.deadTime = 0;
    this.stuckTimer = 0;
    this.respawnTimer = 0;
    this.walkPhase = 0;
    this.kills = 0;
    this.tagTimer = 0;
    this.prevPos = new THREE.Vector3().copy(this.pos);
    this.buildModel();
  }

  buildModel() {
    const outfitColors = { top: this.outfit, pants: this.pants || pick(BOT_PANTS), accent: pick(ACCENTS), vest: '#161a1f' };
    this.model = createHumanoid({
      outfit: outfitColors, skin: this.skin, helmet: this.helmet,
      backpack: Math.random() > 0.4 ? 'recon' : 'none',
      weapon: this.weaponDef.id,
      teamColor: this.game.mode.id !== 'br' ? this.teamColor : null
    });
    this.model.position.copy(this.pos);
    this.model.rotation.y = this.yaw;
    this.model.userData.bot = this;
    this.game.scene.add(this.model);
    this.parts = this.model.userData.parts;
    this.hitMeshes = [];
    const mark = (obj, zone) => {
      obj.traverse(o => {
        if (o.isMesh && !o.userData.weapon) { o.userData.hitZone = zone; o.userData.bot = this; this.hitMeshes.push(o); }
      });
    };
    mark(this.parts.head, 'head');
    const headSet = new Set(this.hitMeshes);
    this.hitMeshes = [];
    mark(this.parts.head, 'head');
    // torso includes vest/body meshes attached to group; traverse specific known meshes by geometry proximity
    this.model.traverse(o => {
      if (!o.isMesh || o.userData.weapon) return;
      if (headSet.has(o)) return;
      let p = o; let wy = 0;
      while (p && p !== this.model) { wy += p.position.y; p = p.parent; }
      if (wy > 1.48) o.userData.hitZone = 'head';
      else if (wy < 0.95) o.userData.hitZone = 'leg';
      else o.userData.hitZone = 'body';
      o.userData.bot = this;
      if (!this.hitMeshes.includes(o)) this.hitMeshes.push(o);
    });
    // remove gun meshes
    this.hitMeshes = this.hitMeshes.filter(m => !m.userData.weapon && m.parent);
    // team ring
    const ring = new THREE.Mesh(new THREE.RingGeometry(0.5, 0.62, 18), new THREE.MeshBasicMaterial({ color: new THREE.Color(this.teamColor), transparent: true, opacity: 0.45, side: THREE.DoubleSide, depthWrite: false }));
    ring.rotation.x = -Math.PI / 2; ring.position.y = 0.03;
    this.model.add(ring); this.ring = ring;
    // tag
    this.tag = createNameTag(this.name, this.team === 0 && this.game.mode.id !== 'br' ? '#6ff5e0' : '#ffb3a8');
    this.model.add(this.tag);
    this.updateTag();
    this.model.updateMatrixWorld(true);
  }

  updateTag() {
    if (!this.tag) return;
    const c = document.createElement('canvas'); c.width = 256; c.height = 84;
    const ctx = c.getContext('2d');
    const col = this.team === 0 && this.game.mode.id !== 'br' ? '#6ff5e0' : '#ff8d80';
    ctx.fillStyle = 'rgba(4,7,10,.55)';
    ctx.fillRect(8, 2, 240, 80);
    ctx.font = '600 24px "Chakra Petch", sans-serif';
    ctx.textAlign = 'center'; ctx.fillStyle = col;
    ctx.fillText(this.name.toUpperCase(), 128, 28);
    const k = clamp(this.health / this.maxHealth, 0, 1);
    ctx.fillStyle = 'rgba(255,255,255,.16)'; ctx.fillRect(28, 42, 200, 7);
    ctx.fillStyle = k > 0.5 ? '#42e6a4' : k > 0.25 ? '#ffc74a' : '#ff4b4b';
    ctx.fillRect(28, 42, 200 * k, 7);
    ctx.font = '600 13px "Rajdhani", sans-serif'; ctx.fillStyle = '#9fb0bd';
    ctx.fillText(`${this.weaponDef.short}  ·  ${Math.ceil(this.health)}`, 128, 68);
    const tex = new THREE.CanvasTexture(c);
    tex.colorSpace = THREE.SRGBColorSpace;
    if (this.tag.material.map) this.tag.material.map.dispose();
    this.tag.material.map = tex;
    this.tag.material.needsUpdate = true;
    this.tag.scale.set(2.05, 0.67, 1);
    this.tag.position.y = 2.25;
    this.tag.userData.lastHealth = this.health;
  }

  eye() { return new THREE.Vector3(this.pos.x, this.pos.y + 1.55, this.pos.z); }
  center() { return new THREE.Vector3(this.pos.x, this.pos.y + 1.15, this.pos.z); }

  takeDamage(amount, killer, point, head = false, def = null) {
    if (!this.alive) return;
    this.health -= amount;
    this.lastDamage = this.game.time;
    this.state = 'attack';
    if (killer && killer !== this) {
      this.target = killer;
      this.targetTimer = 4;
    }
    if (this.health <= 0) {
      this.health = 0;
      this.die(killer, head, def);
    } else {
      this.updateTag();
      this.tag.material.opacity = 1;
    }
  }

  die(killer, head = false, def = null) {
    if (!this.alive) return;
    this.alive = false;
    this.deadTime = this.game.time;
    this.state = 'dead';
    this.target = null;
    this.vel.set(0, 0, 0);
    if (this.tag) this.tag.visible = false;
    if (this.ring) this.ring.visible = false;
    // ragdoll-ish fall
    const dir = killer && killer.pos ? Math.sign(this.pos.x - killer.pos.x) || 1 : 1;
    this.fallDir = dir;
    this.game.onBotKilled?.(this, killer, head, def);
    // loot
    this.game.dropBotLoot?.(this);
  }

  respawn(x, z) {
    this.alive = true;
    this.health = 100;
    this.pos.set(x, this.world.heightAt(x, z) + 0.05, z);
    this.vel.set(0, 0, 0);
    this.state = 'patrol';
    this.target = null;
    this.model.visible = true;
    this.model.position.copy(this.pos);
    this.model.rotation.set(0, this.yaw, 0);
    if (this.tag) this.tag.visible = true;
    if (this.ring) this.ring.visible = true;
    this.updateTag();
    this.model.updateMatrixWorld(true);
  }

  fireAt(target) {
    const def = this.weaponDef;
    const dist = this.center().distanceTo(target.center ? target.center() : target.pos);
    const muzzle = this.center().add(new THREE.Vector3(-Math.sin(this.yaw) * 0.5, 0.1, -Math.cos(this.yaw) * 0.5));
    const targetPos = target.center ? target.center() : target.pos.clone().add(new THREE.Vector3(0, 1.2, 0));
    const targetVel = target.vel ? Math.hypot(target.vel.x, target.vel.z) : 0;
    let chance = clamp(0.8 - dist * 0.009 - targetVel * 0.026, 0.1, 0.75) * this.skill;
    if (target.crouching) chance *= 0.8;
    if (target.aiming) chance *= 0.92;
    const hit = Math.random() < chance;
    const end = hit ? targetPos.clone() : targetPos.clone().add(new THREE.Vector3(rand(-1.6, 1.6), rand(-0.8, 1.2), rand(-1.6, 1.6)));
    this.game.effects.tracer(muzzle, end, 0xffb066);
    this.game.effects.muzzle(muzzle, '#ffcc88', 0.8);
    audio.shot(def.model, this.pos.distanceTo(this.game.player.pos));
    if (hit) {
      let dmg = def.dmg * rand(0.55, 0.85);
      if (def.pellets > 1) dmg *= rand(0.4, 0.9);
      if (target === this.game.player) target.takeDamage(Math.round(dmg), this);
      else target.takeDamage(Math.round(dmg), this);
      this.game.effects.impact(end, null, '#ffb060', true);
    } else {
      this.game.effects.impact(end, null, '#ffd08a', false);
    }
    if (target === this.game.player) this.game.hud?.nearMiss(end);
  }

  update(dt) {
    if (!this.alive) {
      // death animation & cleanup
      if (this.model) {
        const k = clamp((this.game.time - this.deadTime) / 0.6, 0, 1);
        this.model.rotation.z = this.fallDir * k * Math.PI * 0.48;
        this.model.position.y = this.pos.y + Math.sin(k * Math.PI) * 0.15 - Math.max(0, (this.game.time - this.deadTime - 5)) * 0.4;
        if (this.game.time - this.deadTime > 7.5) { this.remove(); }
      }
      return;
    }
    this.prevPos.copy(this.pos);
    const now = this.game.time;
    this.targetTimer -= dt;
    this.fireTimer -= dt;

    // target acquisition
    if (this.targetTimer <= 0) {
      this.targetTimer = 0.32 + Math.random() * 0.28;
      this.target = this.mgr.findTarget(this);
      this.state = this.target ? 'attack' : 'patrol';
      if (!this.target) this.pickDestination();
    }
    if (this.target && (!this.target.alive)) this.target = null;

    let moveX = 0, moveZ = 0;
    let faceYaw = this.yaw;
    if (this.target) {
      const tp = this.target.center ? this.target.center() : this.target.pos.clone().add(new THREE.Vector3(0, 1.1, 0));
      const dx = tp.x - this.pos.x, dz = tp.z - this.pos.z;
      const dist = Math.hypot(dx, dz);
      faceYaw = Math.atan2(-dx, -dz);
      const ideal = this.weaponDef.model === 'shotgun' ? 9 : this.weaponDef.model === 'sniper' ? 45 : this.weaponDef.model === 'smg' ? 15 : 24;
      let forward = 0;
      if (dist > ideal + 4) forward = 1;
      else if (dist < ideal - 5) forward = -0.7;
      const strafe = this.strafeDir;
      if (Math.random() < 0.006) this.strafeDir *= -1;
      const nx = dx / (dist || 1), nz = dz / (dist || 1);
      moveX = (nx * forward + -nz * strafe * 0.72) * this.speed;
      moveZ = (nz * forward + nx * strafe * 0.72) * this.speed;
      // shooting
      if (this.fireTimer <= 0 && dist < 75) {
        const eye = this.eye(), targetEye = this.target.eye ? this.target.eye() : this.target.pos.clone().add(new THREE.Vector3(0, 1.2, 0));
        const dir = targetEye.clone().sub(eye); const d = dir.length(); dir.normalize();
        const blocked = this.world.rayBlock(eye, dir, d);
        if (blocked >= d - 1.2) {
          this.fireTimer = 60 / this.weaponDef.rpm * rand(1.6, 3.2) + 0.15;
          this.fireAt(this.target);
          // burst
          if (this.weaponDef.auto && Math.random() > 0.35) {
            const self = this;
            setTimeout(() => { if (self.alive && self.target && self.target.alive) self.fireAt(self.target); }, 110);
          }
        } else {
          this.fireTimer = 0.5;
        }
      }
    } else {
      // patrol
      const dx = this.dest.x - this.pos.x, dz = this.dest.z - this.pos.z;
      const dist = Math.hypot(dx, dz);
      if (dist < 2.5) this.pickDestination();
      else {
        moveX = dx / dist * this.speed * 0.55;
        moveZ = dz / dist * this.speed * 0.55;
        faceYaw = Math.atan2(-dx, -dz);
      }
    }
    // avoid water
    if (this.world.heightAt(this.pos.x, this.pos.z) < 0.3) {
      moveX += (0 - this.pos.x) * 0.03; moveZ += (0 - this.pos.z) * 0.03;
    }
    this.vel.x = damp(this.vel.x, moveX, 8, dt);
    this.vel.z = damp(this.vel.z, moveZ, 8, dt);
    this.vel.y -= 20 * dt;
    this.pos.x += this.vel.x * dt;
    this.pos.z += this.vel.z * dt;
    this.world.collide(this.pos, 0.42, this.pos.y);
    this.pos.y += this.vel.y * dt;
    const gy = Math.max(this.world.heightAt(this.pos.x, this.pos.z), this.world.sea - 0.8);
    if (this.pos.y <= gy) { this.pos.y = gy; this.vel.y = 0; }
    // stuck check
    const moved = Math.hypot(this.pos.x - this.prevPos.x, this.pos.z - this.prevPos.z);
    if (moved < 0.002 && (this.vel.x || this.vel.z)) {
      this.stuckTimer += dt;
      if (this.stuckTimer > 1.2) { this.stuckTimer = 0; this.pickDestination(); this.strafeDir *= -1; this.pos.x += rand(-1, 1); this.pos.z += rand(-1, 1); }
    } else this.stuckTimer = 0;

    // face target smoothly
    this.yaw += angleDelta(this.yaw, faceYaw) * Math.min(1, dt * 7);
    this.model.position.copy(this.pos);
    this.model.rotation.y = this.yaw;
    this.model.rotation.z = damp(this.model.rotation.z, 0, 8, dt);
    // walk animation
    const spd = Math.hypot(this.vel.x, this.vel.z);
    this.walkPhase += dt * spd * 2.1;
    const swing = Math.min(1, spd / 3) * 0.55;
    this.parts.leftLeg.rotation.x = Math.sin(this.walkPhase) * swing;
    this.parts.rightLeg.rotation.x = -Math.sin(this.walkPhase) * swing;
    this.parts.leftArm.rotation.x = -1.32 + Math.sin(this.walkPhase) * swing * 0.18;
    this.parts.rightArm.rotation.x = -1.18 - Math.sin(this.walkPhase) * swing * 0.1;
    this.parts.torso.position.y = 1.2 + Math.abs(Math.sin(this.walkPhase)) * 0.018 * Math.min(1, spd);
    this.model.updateMatrixWorld();
    // tag visibility
    const distToPlayer = this.pos.distanceTo(this.game.player.pos);
    if (this.tag) {
      this.tag.visible = distToPlayer < 55 || (this.game.time - this.lastDamage < 6);
      this.tag.material.opacity = clamp(1.8 - distToPlayer / 45, 0.25, 1);
    }
    if (this.ring) this.ring.visible = distToPlayer < 70;
    // health tag refresh
    if (this.tagTimer < this.game.time && this.tag && this.tag.userData.lastHealth !== this.health) {
      this.tagTimer = this.game.time + 0.25;
      this.updateTag();
    }
  }

  pickDestination() {
    const nearPoi = this.mgr.poiCenters[randInt(0, this.mgr.poiCenters.length - 1)];
    if (Math.random() > 0.35 && nearPoi) {
      const a = rand(0, Math.PI * 2), r = rand(4, nearPoi.r * 0.9);
      this.dest.set(nearPoi.x + Math.cos(a) * r, 0, nearPoi.z + Math.sin(a) * r);
    } else {
      this.dest.set(this.pos.x + rand(-24, 24), 0, this.pos.z + rand(-24, 24));
    }
  }

  remove() {
    if (this.model) {
      this.game.scene.remove(this.model);
      this.model.traverse(o => { if (o.isMesh) o.geometry?.dispose?.(); });
      this.model = null;
    }
    this.mgr.remove(this);
  }
}

export class BotManager {
  constructor(game) {
    this.game = game;
    this.scene = game.scene;
    this.world = game.world;
    this.map = game.map;
    this.mode = game.mode;
    this.bots = [];
    this.virtualAlive = 0;
    this.virtualNames = [];
    this.virtualTimer = 0;
    this.poiCenters = game.world.poiCenters;
    this.usedNames = new Set();
    this.teamScores = [0, 0];
    this.spawnAll();
  }

  get aliveReal() { return this.bots.filter(b => b.alive).length; }
  get aliveCount() {
    const playerAlive = this.game.player.alive ? 1 : 0;
    return playerAlive + this.aliveReal + this.virtualAlive;
  }
  get enemies() { return this.bots.filter(b => b.alive && b.team !== 0); }

  nextName() {
    const available = BOT_NAMES.filter(n => !this.usedNames.has(n));
    const name = available.length ? pick(available) : 'BOT' + randInt(10, 99);
    this.usedNames.add(name);
    return name;
  }

  spawnAll() {
    const mode = this.mode;
    const isTDM = mode.id === 'tdm';
    const isTraining = mode.id === 'training';
    this.virtualAlive = mode.id === 'br' ? Math.max(0, mode.players - 1 - mode.realBots) : 0;
    for (let i = 0; i < (mode.players - 1 - this.virtualAlive); i++) {
      const team = isTDM ? (i < 4 ? 0 : 1) : isTraining ? 1 : (i + 1);
      const sp = this.pickSpawn(isTDM || isTraining ? team : -1, i);
      const def = pick(Object.values(WEAPONS).filter(w => !isTDM || w.slot === 'primary'));
      const bot = new Bot(this, {
        x: sp.x, z: sp.z, y: sp.y != null ? sp.y : this.world.heightAt(sp.x, sp.z),
        name: this.nextName(), team,
        outfit: pick(BOT_OUTFITS), pants: pick(BOT_PANTS), skin: pick(SKINS).color,
        helmet: pick(HELMETS.slice(1)).id, weapon: def
      });
      this.bots.push(bot);
    }
    for (let i = 0; i < this.virtualAlive; i++) this.virtualNames.push(this.nextName());
    this.virtualTimer = rand(14, 26);
  }

  pickSpawn(team, index) {
    const g = this.game;
    if (team === 0 && index < 4) {
      // teammate near player
      return { x: g.player.pos.x + rand(-9, 9), z: g.player.pos.z + rand(-9, 9) };
    }
    if (team === 1) {
      let best = null, bestScore = -1;
      for (let i = 0; i < 12; i++) {
        const sp = pick(this.world.spawnPoints);
        if (!sp) break;
        const d = Math.hypot(sp.x - g.player.pos.x, sp.z - g.player.pos.z);
        const score = Math.min(120, Math.abs(d - 45)) + rand(0, 15);
        if (bestScore < 0 || score < bestScore) { bestScore = score; best = sp; }
      }
      if (best) return best;
    }
    // random far from player for BR
    for (let i = 0; i < 16; i++) {
      const sp = pick(this.world.spawnPoints);
      if (!sp) break;
      const d = Math.hypot(sp.x - g.player.pos.x, sp.z - g.player.pos.z);
      if (d > 40 || i > 12) return sp;
    }
    return pick(this.world.spawnPoints) || { x: rand(-80, 80), z: rand(-80, 80) };
  }

  findTarget(bot) {
    const g = this.game;
    const candidates = [];
    const player = g.player;
    if (player.alive && (this.mode.id !== 'tdm' || bot.team !== 0)) {
      const d = bot.pos.distanceTo(player.pos);
      if (d < 68) candidates.push({ t: player, d });
    }
    for (const b of this.bots) {
      if (b === bot || !b.alive) continue;
      if (b.team === bot.team) continue;
      if (this.mode.id !== 'br' && b.team === bot.team) continue;
      const d = bot.pos.distanceTo(b.pos);
      if (d < 55) candidates.push({ t: b, d: d * 1.25 });
    }
    if (!candidates.length) return null;
    candidates.sort((a, b) => a.d - b.d);
    for (const c of candidates.slice(0, 3)) {
      const eye = bot.eye();
      const tp = c.t.center ? c.t.center() : c.t.pos.clone().add(new THREE.Vector3(0, 1.2, 0));
      const dir = tp.clone().sub(eye); const d = dir.length(); dir.normalize();
      if (this.world.rayBlock(eye, dir, d) >= d - 0.6) return c.t;
    }
    return null;
  }

  update(dt) {
    if (!this.game.dropDone) return;
    for (const bot of this.bots) bot.update(dt);
    // virtual BR attrition
    if (this.mode.id === 'br' && this.virtualAlive > 0 && this.game.time > 18) {
      this.virtualTimer -= dt;
      if (this.virtualTimer <= 0) {
        this.virtualTimer = rand(2.2, 6.4);
        const victim = this.virtualNames.pop() || 'UNKNOWN';
        const killer = Math.random() > 0.5 && this.virtualNames.length ? pick(this.virtualNames) : pick(BOT_NAMES);
        this.virtualAlive--;
        this.game.onVirtualKill?.(killer, victim);
      }
    }
  }

  notifyKill(killerTeam, victimTeam) {
    if (this.mode.id !== 'tdm') return;
    const scoringTeam = killerTeam === 0 ? 1 : 0;
    // team 0 = player's team; kills by team 0 add to 0
    this.teamScores[killerTeam] = (this.teamScores[killerTeam] || 0) + 1;
    this.game.onTeamScore?.(this.teamScores);
    if (this.teamScores.player >= this.mode.killTarget || this.teamScores[0] >= this.mode.killTarget) {
      this.game.endMatch?.(true, 'score');
    }
    this.game.onTeamScore?.(this.teamScores);
  }

  handleRespawns(dt) {
    if (!this.mode.respawn) return;
    for (const bot of this.bots) {
      if (!bot.alive && bot.model && this.game.time - bot.deadTime > 3.2) {
        let sp;
        if (this.mode.id === 'tdm' && bot.team === 1) {
          // spawn away from player
          sp = pick(this.world.spawnPoints.filter(s => Math.hypot(s.x - this.game.player.pos.x, s.z - this.game.player.pos.z) > 35)) || pick(this.world.spawnPoints);
        } else sp = this.pickSpawn(bot.team, 99);
        bot.respawn(sp.x, sp.z);
      }
    }
  }

  remove(bot) {
    const i = this.bots.indexOf(bot);
    if (i >= 0) this.bots.splice(i, 1);
  }

  getScoreboardData() {
    const rows = [{ name: this.game.profile.name.toUpperCase(), kills: this.game.player.kills, dmg: Math.round(this.game.player.damageDealt), me: true, alive: this.game.player.alive }];
    for (const b of this.bots) rows.push({ name: b.name.toUpperCase(), kills: b.kills, dmg: 0, alive: b.alive, team: b.team });
    rows.sort((a, b) => (b.alive ? 1 : 0) - (a.alive ? 1 : 0) || b.kills - a.kills);
    return rows;
  }

  dispose() {
    for (const b of this.bots) {
      if (b.model) {
        this.game.scene.remove(b.model);
        b.model.traverse(o => {
          if (o.isMesh) { o.geometry?.dispose?.(); }
          if (o.material?.map) o.material.map.dispose?.();
        });
      }
    }
    this.bots.length = 0;
  }
}

import { clamp, formatTime, $, el } from './utils.js';

export class HUD {
  constructor() {
    this.root = $('#hud');
    this.minimap = $('#minimap');
    this.mctx = this.minimap.getContext('2d');
    this.compass = $('#compass');
    this.compassStrip = $('#compass-strip');
    this.compassBuilt = false;
    this.compassW = 0;
    this.lastMini = 0;
    this.lastCompass = -999;
    this.zone = null;
    this.killfeed = $('#killfeed');
    this.results = $('#results');
    this.scoreboardEl = $('#scoreboard');
    this.pauseEl = $('#pause');
    this.intro = $('#match-intro');
    this.dropUI = $('#drop-ui');
    this.game = null;
    this.bound = false;
    this.dmgDirEl = null;
    this.scoreboardOpen = false;
    this.reloadStart = 0;
    this.reloadDur = 0;
    this.bindStatic();
    window.addEventListener('resize', () => { this.buildCompass(); });
  }

  bind(game) {
    this.game = game;
    this.buildCompass();
    this.updateVitals();
    this.updateAmmo();
    this.updateAlive();
    this.setObjective(game.mode);
    if (game.mode.id === 'tdm') {
      $('#obj-score').classList.remove('hidden');
      this.updateScore(0, 0);
    } else $('#obj-score').classList.add('hidden');
    $('#hud-name').textContent = game.profile.name;
    $('#hud-initial').textContent = (game.profile.name[0] || 'P').toUpperCase();
    $('#hud-lvl').textContent = game.profile.level;
    $('#hud-team-tag').textContent = game.mode.id === 'tdm' ? 'ALPHA' : 'SOLO';
    this.killfeed.innerHTML = '';
    this.scoreboardEl.classList.add('hidden');
    this.pauseEl.classList.add('hidden');
    this.results.classList.add('hidden');
    this.dropUI.classList.add('hidden');
    this.intro.classList.add('hidden');
    this.compassBuilt = false;
    this.zone = game.zone;
    if (game.world) this.miniBase = game.world.miniCanvas;
  }

  bindStatic() {
    if (this.bound) return;
    this.bound = true;
    $('#btn-resume')?.addEventListener('click', () => this.game?.resume());
    $('#btn-leave')?.addEventListener('click', () => this.game?.leaveMatch());
    $('#btn-pause-settings')?.addEventListener('click', () => this.game?.openSettings());
    $('#vh-exit')?.addEventListener('click', () => this.game?.exitVehicle(true));
    $('#btn-again')?.addEventListener('click', () => this.game?.playAgain());
    $('#btn-lobby')?.addEventListener('click', () => this.game?.returnToLobby());
    $('#drop-skip')?.addEventListener('click', () => this.game?.skipDrop());
    const d = document.createElement('div');
    d.id = 'dmg-dir'; d.className = 'dmg-dir'; d.innerHTML = '<i></i>';
    document.getElementById('hud').appendChild(d);
    this.dmgDirEl = d;
  }

  show() { this.root.classList.remove('hidden'); }
  hide() { this.root.classList.add('hidden'); }

  buildCompass() {
    if (!this.compass) return;
    const w = this.compass.offsetWidth || 400;
    this.compassW = w;
    this.compassStrip.innerHTML = '';
    const k = w / 180; // pixels per degree (shows 180°)
    const labels = [[0, 'N'], [45, 'NE'], [90, 'E'], [135, 'SE'], [180, 'S'], [225, 'SW'], [270, 'W'], [315, 'NW']];
    for (let a = -180; a <= 540; a += 15) {
      const span = document.createElement('span');
      const norm = ((a % 360) + 360) % 360;
      const found = labels.find(l => l[0] === norm);
      span.textContent = found ? found[1] : '';
      span.className = found ? 'card' : '';
      span.style.left = (w / 2 + a * k) + 'px';
      this.compassStrip.appendChild(span);
      if (!found) {
        const tick = document.createElement('i');
        tick.style.left = (w / 2 + a * k) + 'px';
        this.compassStrip.appendChild(tick);
      }
    }
    this.compassBuilt = true;
  }

  updateCompass() {
    if (!this.game) return;
    if (!this.compassBuilt || Math.abs(this.compass.offsetWidth - this.compassW) > 2) this.buildCompass();
    const heading = ((-this.game.player.yaw * 180 / Math.PI) % 360 + 360) % 360;
    if (Math.abs(heading - this.lastCompass) < 0.35) return;
    this.lastCompass = heading;
    const k = this.compassW / 180;
    this.compassStrip.style.transform = `translateX(${-heading * k}px)`;
  }

  setZone(zone) { this.zone = zone; }

  update(dt) {
    if (!this.game || this.root.classList.contains('hidden')) return;
    this.updateCompass();
    this.updateZone();
    this.updateVehicle();
    this.updateReload();
    if (performance.now() - this.lastMini > 90) {
      this.lastMini = performance.now();
      this.drawMinimap();
    }
  }

  updateZone() {
    if (!this.game) return;
    const z = this.game.zone;
    const bar = $('#zone-bar'), label = $('#zone-label'), timer = $('#zone-timer');
    const mz = $('#mm-zone'), mzt = $('#mm-zone-txt');
    if (!z || !z.active) {
      label.textContent = this.game.mode.id === 'tdm' ? 'NO SAFE ZONE' : 'ZONE ACTIVE';
      timer.textContent = '--:--';
      bar.classList.remove('danger');
      mz.classList.remove('danger');
      mzt.textContent = 'ZONE DISABLED';
      return;
    }
    label.textContent = z.shrinking ? 'ZONE SHRINKING' : (z.phase === 0 ? 'ZONE STABLE' : 'NEXT ZONE');
    timer.textContent = formatTime(Math.max(0, z.timeLeft));
    const outside = z.outside;
    bar.classList.toggle('danger', outside);
    mz.classList.toggle('danger', outside);
    const d = Math.hypot(this.game.player.pos.x - z.center.x, this.game.player.pos.z - z.center.z);
    const dist = Math.max(0, d - z.radius);
    mzt.textContent = outside ? `OUTSIDE · ${Math.ceil(dist)}M` : `SAFE · ${Math.ceil(dist)}M`;
  }

  updateVehicle() {
    const g = this.game;
    const vh = $('#vehicle-hud');
    if (g.vehicle) {
      vh.classList.remove('hidden');
      $('#vh-speed').textContent = Math.round(Math.abs(g.vehicle.speed) * 3.6);
      $('#vh-health').style.width = clamp(g.vehicle.health, 0, 100) + '%';
    } else vh.classList.add('hidden');
  }

  updateReload() {
    const tr = $('#reload-track');
    if (!this.game || this.game.player.reloadTimer <= 0) { tr.classList.remove('active'); return; }
    tr.classList.add('active');
    const p = 1 - this.game.player.reloadTimer / this.game.player.def.reload;
    tr.querySelector('i').style.width = clamp(p * 100, 0, 100) + '%';
  }

  startReload(dur) { this.reloadDur = dur; this.reloadStart = performance.now(); }

  updateVitals() {
    const p = this.game?.player;
    if (!p) return;
    const hp = clamp(p.health, 0, 100), sh = clamp(p.shield, 0, 100);
    const hpFill = $('#hp-fill'), hpText = $('#hp-text');
    hpFill.style.width = hp + '%'; hpText.textContent = Math.ceil(hp);
    $('#armor-fill').style.width = sh + '%'; $('#armor-text').textContent = Math.ceil(sh);
    const bar = hpFill.closest('.bar');
    bar.classList.toggle('low', hp < 30);
    const ghost = $('#hp-ghost');
    ghost.style.width = Math.max(hp, parseFloat(ghost.style.width) || 0) + '%';
    setTimeout(() => { ghost.style.width = hp + '%'; }, 30);
    $('#med-count').textContent = p.medkits;
    $('#shield-count').textContent = p.shields;
  }

  updateAmmo() {
    const p = this.game?.player;
    if (!p) return;
    const w = p.weapon;
    $('#weapon-label').textContent = w.def.name;
    $('#fire-mode').textContent = w.def.auto ? 'AUTO' : 'SEMI';
    $('#ammo-mag').textContent = w.mag;
    $('#ammo-reserve').textContent = this.game.mode.infiniteAmmo ? '∞' : w.reserve;
    $('#wslot-0').textContent = p.weapons[0]?.def.short || '—';
    $('#wslot-1').textContent = p.weapons[1]?.def.short || '—';
    $('#wslot-2').textContent = p.weapons[2]?.def.short || '—';
    document.querySelectorAll('#hud .wslot').forEach((el, i) => el.classList.toggle('active', i === p.weaponIndex));
    $('#ammo-mag').style.color = w.mag === 0 ? '#ff5b4b' : w.mag <= Math.ceil(w.def.mag * 0.25) ? '#ffc74a' : '#fff';
    $('#crosshair').style.setProperty('--spread', Math.round(4 + p.currentSpread() * 2.2) + 'px');
  }

  updateAlive() {
    const g = this.game;
    if (!g) return;
    const alive = g.bots ? g.bots.aliveCount : 0;
    $('#hud-alive').textContent = alive;
    $('#hud-kills').textContent = g.player.kills;
    $('#hud-squad').textContent = g.mode.id === 'tdm' ? (g.bots ? g.bots.bots.filter(b => b.alive && b.team === 0).length + (g.player.alive ? 1 : 0) : 1) : 1;
    if (g.mode.id === 'tdm') {
      this.updateScore(g.bots.teamScores[0], g.bots.teamScores[1]);
    }
    if (this.scoreboardOpen) this.renderScoreboard();
  }

  updateScore(a, b) {
    const el = $('#obj-score');
    if (el) el.innerHTML = `${a} <i>—</i> ${b}`;
  }

  drawMinimap() {
    if (!this.miniBase || !this.game) return;
    const ctx = this.mctx, W = this.minimap.width;
    ctx.clearRect(0, 0, W, W);
    ctx.drawImage(this.miniBase, 0, 0, 512, 512, 0, 0, W, W);
    const g = this.game, world = g.world;
    const sx = W / world.size;
    const px = (world.playerToMap?.x ?? (g.player.pos.x + 300)) * sx;
    const py = (world.playerToMap?.y ?? (g.player.pos.z + 300)) * sx;
    const toPx = (x, z) => [(x + 300) * sx, (z + 300) * sx];
    // safe zones
    const z = g.zone;
    if (z && z.active) {
      const [cx, cy] = toPx(z.center.x, z.center.z);
      ctx.beginPath(); ctx.arc(cx, cy, z.radius * sx, 0, Math.PI * 2);
      ctx.strokeStyle = z.outside ? 'rgba(255,70,60,.9)' : 'rgba(255,255,255,.85)';
      ctx.lineWidth = 2; ctx.stroke();
      ctx.fillStyle = z.outside ? 'rgba(255,60,40,.08)' : 'rgba(255,255,255,.05)'; ctx.fill();
      if (z.nextCenter && z.nextRadius) {
        const [nx, ny] = toPx(z.nextCenter.x, z.nextCenter.z);
        ctx.beginPath(); ctx.arc(nx, ny, z.nextRadius * sx, 0, Math.PI * 2);
        ctx.strokeStyle = 'rgba(255,170,60,.85)'; ctx.lineWidth = 1.5; ctx.setLineDash([5, 4]); ctx.stroke(); ctx.setLineDash([]);
      }
    }
    // teammates
    if (g.bots) {
      for (const b of g.bots.bots) {
        if (!b.alive) continue;
        if (g.mode.id === 'br' || b.team !== 0) continue;
        const [bx, by] = toPx(b.pos.x, b.pos.z);
        ctx.fillStyle = '#25ddc3'; ctx.beginPath(); ctx.arc(bx, by, 3, 0, 7); ctx.fill();
      }
    }
    // vehicles
    for (const v of g.vehicles || []) {
      if (v.destroyed) continue;
      const [vx, vy] = toPx(v.pos.x, v.pos.z);
      ctx.fillStyle = 'rgba(255,200,80,.9)'; ctx.fillRect(vx - 2, vy - 2, 4, 4);
    }
    // airdrop
    if (g.airdropPos) {
      const [ax, ay] = toPx(g.airdropPos.x, g.airdropPos.z);
      ctx.strokeStyle = '#ff7a1a'; ctx.lineWidth = 2;
      ctx.beginPath(); ctx.arc(ax, ay, 5, 0, 7); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(ax - 7, ay); ctx.lineTo(ax + 7, ay); ctx.moveTo(ax, ay - 7); ctx.lineTo(ax, ay + 7); ctx.stroke();
    }
    // player
    ctx.save();
    ctx.translate(px, py);
    ctx.rotate(-g.player.yaw);
    ctx.fillStyle = '#fff';
    ctx.beginPath(); ctx.moveTo(0, -7); ctx.lineTo(5, 6); ctx.lineTo(0, 3); ctx.lineTo(-5, 6); ctx.closePath(); ctx.fill();
    ctx.strokeStyle = '#ff7a1a'; ctx.lineWidth = 1.2; ctx.stroke();
    ctx.fillStyle = 'rgba(255,122,26,.14)';
    ctx.beginPath(); ctx.moveTo(0, 0); ctx.arc(0, 0, 26, -Math.PI / 2 - 0.5, -Math.PI / 2 + 0.5); ctx.closePath(); ctx.fill();
    ctx.restore();
    $('#mm-coords').textContent = `GRID ${String(Math.floor((g.player.pos.x + 300) / 40)).padStart(2, '0')}·${String(Math.floor((g.player.pos.z + 300) / 40)).padStart(2, '0')}`;
  }

  killFeed(killer, victim, weapon, me = false, head = false) {
    const row = el('div', 'kf-row' + (me ? ' me' : ''));
    row.innerHTML = `${head ? '<svg class="icon"><use href="#i-skull"/></svg>' : ''}<span class="kf-a">${killer}</span><span class="kf-v">eliminated</span><span class="kf-a">${victim}</span>${weapon ? `<span class="kf-w">[${weapon}]</span>` : ''}`;
    this.killfeed.prepend(row);
    while (this.killfeed.children.length > 5) this.killfeed.lastChild.remove();
    setTimeout(() => { row.style.opacity = '0'; row.style.transition = 'opacity .4s'; setTimeout(() => row.remove(), 420); }, 5200);
  }

  hitmarker(head = false) {
    const hm = $('#hitmarker');
    hm.classList.add('show'); hm.classList.toggle('head', head);
    clearTimeout(this._hm);
    this._hm = setTimeout(() => hm.classList.remove('show'), 110);
  }

  hitFlash(strength = 0.6) {
    const f = $('#hit-flash');
    f.style.transition = 'none'; f.style.opacity = String(clamp(strength, 0, 1));
    requestAnimationFrame(() => { f.style.transition = 'opacity .28s'; f.style.opacity = '0'; });
  }

  flashAmmo() {
    const a = $('#ammo-mag'); a.animate([{ transform: 'scale(1.15)', color: '#ff5b4b' }, { transform: 'scale(1)', color: '#ff5b4b' }], { duration: 220 });
  }
  flashHealth() {
    const v = $('#damage-vignette'); v.style.opacity = '1';
    clearTimeout(this._dmgT); this._dmgT = setTimeout(() => v.style.opacity = '0', 220);
  }

  damageIndicator(sourcePos) {
    this.flashHealth();
    if (!sourcePos || !this.dmgDirEl || !this.game) return;
    const dx = sourcePos.x - this.game.player.pos.x, dz = sourcePos.z - this.game.player.pos.z;
    const angle = Math.atan2(dx, -dz) * 180 / Math.PI;
    const rel = angle - (-this.game.player.yaw * 180 / Math.PI);
    const d = this.dmgDirEl;
    d.style.transform = `rotate(${rel}deg)`;
    d.style.opacity = '1';
    clearTimeout(this._dirT);
    this._dirT = setTimeout(() => { d.style.opacity = '0'; }, 450);
  }

  nearMiss() {}

  toast(title, sub = '') {
    const wrap = $('#toast-wrap');
    const t = el('div', 'toast', `${title}${sub ? ` <span style="color:#7d8b96">${sub}</span>` : ''}`);
    wrap.appendChild(t);
    setTimeout(() => t.remove(), 2900);
  }

  pickup(title, sub, icon = 'i-gun') {
    const host = $('#pickup-toast');
    const row = el('div', 'pickup-line', `<svg class="icon"><use href="#${icon}"/></svg><span>${title}</span><b>${sub}</b>`);
    host.appendChild(row);
    setTimeout(() => row.remove(), 2400);
  }

  banner(title, sub, dur = 2600) {
    const b = $('#event-banner');
    $('#eb-title').textContent = title; $('#eb-sub').textContent = sub || '';
    b.classList.add('show');
    clearTimeout(this._bannerT);
    this._bannerT = setTimeout(() => b.classList.remove('show'), dur);
  }

  setObjective(mode) {
    $('#obj-label').textContent = mode.name;
    $('#obj-main').textContent = mode.label;
  }

  showDrop(world, mode) {
    const d = this.dropUI;
    d.classList.remove('hidden');
    $('#drop-target').textContent = world.map.name;
    this.updateDrop(1, 140, true);
    $('#drop-hint').innerHTML = this.game?.input?.isTouch ? 'STEER TO LAND · TAP SKIP TO DEPLOY FASTER' : 'STEER WITH <kbd>WASD</kbd> · HOLD <kbd>SHIFT</kbd> TO DIVE';
    $('#drop-skip').style.display = 'flex';
  }
  updateDrop(progress, alt, chute) {
    $('#drop-progress').style.width = clamp(progress * 100, 0, 100) + '%';
    $('#drop-alt').innerHTML = `${Math.max(0, Math.round(alt))}<small>M</small>`;
    if (chute) $('#drop-hint').innerHTML = $('#drop-hint').innerHTML.includes('CHUTE') ? $('#drop-hint').innerHTML : 'PARACHUTE DEPLOYED · STEER WITH <kbd>WASD</kbd>';
  }
  hideDrop() { this.dropUI.classList.add('hidden'); }

  showIntro(mode, map) {
    this.intro.classList.remove('hidden');
    $('#mi-mode').textContent = mode.name;
    $('#mi-mapname').textContent = map.name;
    $('#mi-mode').nextElementSibling.textContent = map.name;
    const grid = this.intro.querySelector('.mi-grid');
    grid.innerHTML = `<div><b>${mode.players}</b><span>PLAYERS</span></div><div><b>${mode.teamSize > 1 ? mode.teamSize + 'v' + mode.teamSize : 'SOLO'}</b><span>MODE</span></div><div><b>${mode.ranked ? 'RANKED' : 'CASUAL'}</b><span>QUEUE</span></div>`;
    const content = this.intro.querySelector('.mi-content');
    content.style.animation = 'none'; content.offsetHeight; content.style.animation = '';
    const bg = this.intro.querySelector('.mi-bg');
    bg.style.animation = 'none'; bg.offsetHeight; bg.style.animation = '';
    setTimeout(() => this.intro.classList.add('hidden'), 2500);
  }

  toggleScoreboard(open) {
    this.scoreboardOpen = open ?? !this.scoreboardOpen;
    this.scoreboardEl.classList.toggle('hidden', !this.scoreboardOpen);
    if (this.scoreboardOpen) this.renderScoreboard();
  }
  renderScoreboard() {
    if (!this.game?.bots) return;
    const rows = this.game.bots.getScoreboardData();
    $('#sb-alive').textContent = `${this.game.bots.aliveCount} ALIVE`;
    const host = $('#sb-rows');
    host.innerHTML = '';
    rows.slice(0, 10).forEach((r, i) => {
      const row = el('div', 'sb-row' + (r.me ? ' me' : ''));
      row.innerHTML = `<span>${i + 1}</span><span class="sb-name"><i class="sb-dot" style="background:${r.me ? '#ff7a1a' : r.team === 0 && this.game.mode.id === 'tdm' ? '#25ddc3' : '#ff5a45'}"></i>${r.name}</span><b>${r.kills}</b><b>${r.dmg}</b>`;
      host.appendChild(row);
    });
  }

  togglePause(show) {
    this.pauseEl.classList.toggle('hidden', !show);
    if (show) this.toggleScoreboard(false);
  }

  showResults(data) {
    this.root.classList.add('hidden');
    const r = this.results;
    r.classList.remove('hidden');
    r.classList.toggle('lose', !data.win);
    $('#result-title').textContent = data.win ? (data.mode === 'tdm' ? 'VICTORY' : 'BLAZE VICTORY') : (data.mode === 'tdm' ? 'DEFEAT' : 'ELIMINATED');
    $('#result-kicker').textContent = data.modeName;
    $('#result-place').innerHTML = data.mode === 'tdm'
      ? `<b>${data.teamScores[0]} — ${data.teamScores[1]}</b><span>FINAL SCORE</span>`
      : `<b>#${data.placement}</b><span>OUT OF ${data.players}</span>`;
    $('#rs-kills').textContent = data.kills;
    $('#rs-damage').textContent = Math.round(data.damage);
    $('#rs-time').textContent = formatTime(data.time);
    $('#rs-acc').textContent = Math.round(data.accuracy) + '%';
    $('#reward-coins').textContent = '+' + data.coins.toLocaleString();
    $('#reward-xp').textContent = '+' + data.xp.toLocaleString();
    $('#reward-kills').textContent = (data.win ? '+' : '') + data.rankPts;
    $('#result-map').textContent = data.mapName;
  }
  hideResults() { this.results.classList.add('hidden'); }
}

import * as THREE from 'three';
import { clamp, damp, lerp, rand, pick, formatTime } from './utils.js';
import { WEAPONS, MODES } from './config.js';
import { buildWorld } from './world.js';
import { createHumanoid, createParachute, createVehicle, createPickupModel } from './models.js';
import { Effects } from './effects.js';
import { Player } from './player.js';
import { BotManager } from './bots.js';
import { audio } from './audio.js';
import { outfitOf, skinOf, helmetOf, backpackOf } from './profile.js';

const DROP_ALT = 155;

export class Game {
  constructor(app) {
    this.app = app;
    this.renderer = app.renderer;
    this.profile = app.profile;
    this.map = app.map;
    this.mode = app.mode;
    this.hud = app.hud;
    this.input = app.input;
    this.scene = new THREE.Scene();
    this.camera = new THREE.PerspectiveCamera(this.profile.settings.fov || 74, innerWidth / innerHeight, 0.04, 900);
    this.scene.add(this.camera);
    this.world = buildWorld(this.scene, this.map, app.quality);
    this.effects = null;
    this.vehicles = [];
    this.pickups = [];
    this.airdrop = null;
    this.airdropPos = null;
    this.vehicle = null;
    this.time = 0;
    this.matchTime = 0;
    this.active = true;
    this.paused = false;
    this.over = false;
    this.dropDone = false;
    this.zone = null;
    this.deathTimer = 0;
    this.respawnTimer = 0;
    this.airdropTimer = 55;
    this.zoneTick = 0;
    this.introTimer = 2.5;
    this.phase = 'intro';
    this.lastHud = 0;
    this.boundActions = false;
    this.input.clearListeners();
    this.bindInput();
    this.hud.bind(this);
    this.hud.show();
    this.renderer.domElement.classList.add('in-game');
    document.getElementById('lobby').classList.add('hidden');
    this.effects = new Effects(this.scene, this.camera);

    this.player = new Player(this, this.profile);
    this.target = null;
    this.playerModel = null;
    this.parachute = null;
    this.setupSpawn();
    this.bots = new BotManager(this);
    this.spawnPickups();
    this.spawnVehicles();
    this.setupZone();
    this.setupAtmosphere();
    audio.init();
    if (this.mode.id === 'br') this.hud.showDrop(this.world, this.mode);
    this.hud.showIntro(this.mode, this.map);
    this.hud.setObjective(this.mode);
    if (this.mode.id === 'tdm') {
      document.getElementById('obj-score').classList.remove('hidden');
      this.hud.updateScore(0, 0);
    }
    this.player.baseFov = this.profile.settings.fov || 74;
    this.camera.fov = this.player.baseFov;
    this.camera.updateProjectionMatrix();
    this.hud.root.classList.add(this.mode.id === 'br' ? 'dropping' : 'grounded');
    if (this.mode.id !== 'br') this.beginGroundMatch();
    this.updateCameraDrop(0);
    this.app.setGame(this);
  }

  /* ---------------- setup ---------------- */
  setupSpawn() {
    const w = this.world;
    if (this.mode.id === 'br') {
      const target = pick(w.poiCenters.filter(p => p.type !== 'lake')) || w.poiCenters[0];
      this.target = target;
      const ang = rand(0, Math.PI * 2), r = rand(0, 22);
      const x = target.x + Math.cos(ang) * r, z = target.z + Math.sin(ang) * r;
      this.player.pos.set(x, DROP_ALT, z);
      this.player.yaw = rand(0, Math.PI * 2);
      this.player.pitch = -0.08;
      this.player.mode = 'drop';
      this.playerModel = createHumanoid({
        outfit: this.outfitData(), skin: skinOf(this.profile.skin).color, helmet: this.profile.helmet,
        backpack: this.profile.backpack, weapon: this.profile.primary, accent: this.outfitData().accent
      });
      this.playerModel.position.copy(this.player.pos);
      this.playerModel.rotation.y = this.player.yaw;
      this.scene.add(this.playerModel);
      this.parachute = createParachute(this.outfitData().accent);
      this.playerModel.add(this.parachute);
      // skydive pose
      const parts = this.playerModel.userData.parts;
      parts.leftArm.rotation.set(-2.5, 0, -0.5);
      parts.rightArm.rotation.set(-2.5, 0, 0.5);
      parts.leftLeg.rotation.x = 0.35;
      parts.rightLeg.rotation.x = -0.2;
      parts.leftLeg.rotation.z = 0.15;
      parts.rightLeg.rotation.z = -0.1;
    } else {
      const sp = pick(w.spawnPoints);
      const x = sp?.x ?? 0, z = sp?.z ?? 0;
      this.player.spawn(x, z);
      this.player.yaw = rand(0, Math.PI * 2);
      this.playerModel = createHumanoid({
        outfit: this.outfitData(), skin: skinOf(this.profile.skin).color, helmet: this.profile.helmet,
        backpack: this.profile.backpack, weapon: this.profile.primary, accent: this.outfitData().accent
      });
      this.playerModel.visible = false;
      this.scene.add(this.playerModel);
    }
    this.player.health = 100;
    this.player.shield = this.mode.armor || 0;
  }

  outfitData() {
    const o = outfitOf(this.profile.outfit);
    return { top: o.top, pants: o.pants, accent: o.accent, vest: o.vest };
  }

  beginGroundMatch() {
    this.phase = 'play';
    this.dropDone = true;
    this.input.setEnabled(true);
    this.hud.root.classList.remove('dropping');
    this.hud.root.classList.add('grounded');
    this.hud.hideDrop();
    if (this.playerModel) this.playerModel.visible = false;
    if (this.parachute) this.parachute.visible = false;
    this.player.mode = 'fps';
    this.player.eyeHeight = 1.62;
    this.player.syncCamera(0.016);
    this.player.buildViewModel();
    this.hud.show();
    this.bots && (this.bots.active = true);
  }

  bindInput() {
    this.input.on('jump', () => { if (this.paused || this.over) return; if (this.vehicle) return; this.player.jump(); });
    this.input.on('reload', () => { if (!this.paused && !this.vehicle) this.player.startReload(); });
    this.input.on('interact', () => { if (!this.paused) this.interact(); });
    this.input.on('med', () => { if (!this.paused && !this.vehicle) this.player.heal(50); });
    this.input.on('shield', () => { if (!this.paused && !this.vehicle) this.player.useShield(50); });
    this.input.on('slot', i => { if (!this.paused && !this.vehicle) this.player.equip(i); });
    this.input.on('swap', dir => {
      if (this.paused || this.vehicle) return;
      const n = this.player.weapons.length;
      const i = typeof dir === 'number' ? (this.player.weaponIndex + (dir < 0 ? -1 : 1) + n) % n : (this.player.weaponIndex + 1) % n;
      this.player.equip(i);
    });
    this.input.on('scoreboard', open => { if (!this.over) this.hud.toggleScoreboard(open); });
    this.input.on('pause', () => { if (this.over) return; this.paused ? this.resume() : this.pause(); });
    this.input.on('unlock', () => { if (!this.over && !this.paused && this.dropDone && !this.input.isTouch) this.pause(); });
    this.input.on('crouch', () => {});
  }

  setupAtmosphere() {
    // match ambience: distant birds / wind handled by audio ambient
  }

  /* ---------------- zone ---------------- */
  setupZone() {
    if (!this.mode.zone) { this.zone = { active: false }; this.hud.setZone(this.zone); return; }
    const phases = [
      { wait: 22, shrink: 14, radius: 160 },
      { wait: 18, shrink: 13, radius: 105 },
      { wait: 16, shrink: 12, radius: 62 },
      { wait: 14, shrink: 11, radius: 32 },
      { wait: 12, shrink: 10, radius: 12 }
    ];
    this.zone = {
      active: true, phase: 0, phases, center: { x: 0, z: 0 }, radius: 255,
      nextCenter: { x: 0, z: 0 }, nextRadius: 160, startRadius: 255, startCenter: { x: 0, z: 0 },
      timeLeft: phases[0].wait, shrinking: false, damage: 3, outside: false, tick: 0
    };
    this.zone.nextCenter = this.pickZoneCenter(255, 160, { x: 0, z: 0 });
    this.zone.nextRadius = phases[0].radius;
    const mat = new THREE.ShaderMaterial({
      transparent: true, depthWrite: false, side: THREE.DoubleSide, blending: THREE.AdditiveBlending,
      uniforms: { uTime: { value: 0 }, uColor: { value: new THREE.Color(0xff5a1f) }, uOpacity: { value: 0.34 } },
      vertexShader: `varying vec2 vUv; void main(){vUv=uv; gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}`,
      fragmentShader: `uniform float uTime; uniform vec3 uColor; uniform float uOpacity; varying vec2 vUv;
        void main(){
          float band = smoothstep(0.45,0.5,abs(sin(vUv.x*70.0+uTime*0.6)));
          float scan = smoothstep(0.2,1.0,sin(vUv.y*24.0-uTime*1.3)*0.5+0.5);
          float vertical = smoothstep(0.0,0.35,vUv.y)*(1.0-smoothstep(0.85,1.0,vUv.y));
          float a = (0.06 + band*0.12 + scan*0.1) * vertical * uOpacity * 1.8;
          gl_FragColor = vec4(uColor, a);
        }`
    });
    this.zoneMat = mat;
    const cyl = new THREE.Mesh(new THREE.CylinderGeometry(1, 1, 1, 80, 1, true), mat);
    cyl.frustumCulled = false;
    this.zoneMesh = cyl;
    this.scene.add(cyl);
    const ringMat = new THREE.MeshBasicMaterial({ color: 0xff5a1f, transparent: true, opacity: 0.5, side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending });
    this.zoneRing = new THREE.Mesh(new THREE.RingGeometry(0.985, 1.0, 96), ringMat);
    this.zoneRing.rotation.x = -Math.PI / 2;
    this.zoneRing.frustumCulled = false;
    this.scene.add(this.zoneRing);
    this.updateZoneVisual();
    this.hud.setZone(this.zone);
  }

  pickZoneCenter(curR, nextR, curC) {
    const maxOffset = Math.max(0, curR - nextR) * 0.75;
    const a = rand(0, Math.PI * 2), d = Math.sqrt(Math.random()) * maxOffset;
    let x = curC.x + Math.cos(a) * d, z = curC.z + Math.sin(a) * d;
    const lim = 245 - nextR * 0.2;
    const r = Math.hypot(x, z);
    if (r > lim) { x *= lim / r; z *= lim / r; }
    return { x, z };
  }

  updateZone(dt) {
    const z = this.zone;
    if (!z || !z.active) return;
    z.timeLeft -= dt;
    if (!z.shrinking) {
      if (z.timeLeft <= 0 && z.phase < z.phases.length) {
        z.shrinking = true;
        z.timeLeft = z.phases[z.phase].shrink;
        z.shrinkDur = z.phases[z.phase].shrink;
        z.startRadius = z.radius;
        z.startCenter = { ...z.center };
      }
    } else {
      const p = clamp(1 - z.timeLeft / z.shrinkDur, 0, 1);
      z.radius = lerp(z.startRadius, z.nextRadius, p);
      z.center.x = lerp(z.startCenter.x, z.nextCenter.x, p);
      z.center.z = lerp(z.startCenter.z, z.nextCenter.z, p);
      if (z.timeLeft <= 0) {
        z.shrinking = false;
        z.phase++;
        z.damage = 3 + z.phase * 3;
        if (z.phase < z.phases.length) {
          z.timeLeft = z.phases[z.phase].wait;
          z.nextRadius = z.phases[z.phase].radius;
          z.nextCenter = this.pickZoneCenter(z.radius, z.nextRadius, z.center);
        } else {
          z.timeLeft = 999;
          z.nextRadius = z.radius;
          z.nextCenter = { ...z.center };
        }
      }
    }
    const d = Math.hypot(this.player.pos.x - z.center.x, this.player.pos.z - z.center.z);
    z.outside = d > z.radius;
    z.tick -= dt;
    if (z.tick <= 0) {
      z.tick = 1;
      if (z.outside) {
        this.player.takeDamage(z.damage, { pos: new THREE.Vector3(z.center.x, 0, z.center.z) });
        this.hud.warnZone?.();
        audio.warn();
      }
      for (const b of this.bots.bots) {
        if (!b.alive) continue;
        if (Math.hypot(b.pos.x - z.center.x, b.pos.z - z.center.z) > z.radius) b.takeDamage(z.damage + 2, null);
      }
    }
    this.updateZoneVisual();
    this.hud.setZone(z);
  }

  updateZoneVisual() {
    const z = this.zone;
    if (!z || !z.active || !this.zoneMesh) return;
    this.zoneMesh.scale.set(z.radius, 120, z.radius);
    this.zoneMesh.position.set(z.center.x, 60, z.center.z);
    this.zoneRing.scale.set(z.radius, z.radius, 1);
    this.zoneRing.position.set(z.center.x, this.world.heightAt(z.center.x, z.center.z) + 0.2, z.center.z);
    this.zoneRing.material.color.set(z.outside ? 0xff3828 : 0xff7a2a);
  }

  /* ---------------- loot ---------------- */
  spawnPickups() {
    const spots = this.world.lootSpots;
    const step = Math.max(1, Math.floor(spots.length / 42));
    let count = 0;
    for (let i = 0; i < spots.length && count < 46; i += step) {
      const s = spots[i];
      let kind = s.kind;
      if (kind === 'random') kind = pick(['ammo', 'med', 'shield', 'ammo', 'med', 'weapon', 'shield']);
      const weaponId = kind === 'weapon' ? pick(['vanguard', 'viper', 'breaker', 'longshot', 'raptor']) : (kind === 'ammo' ? pick(['vanguard', 'viper', 'sidearm']) : null);
      this.spawnPickup(s.x, s.z, s.y, kind, weaponId);
      count++;
    }
  }

  spawnPickup(x, z, y, kind, weaponId = null) {
    const model = createPickupModel(kind, weaponId || 'vanguard');
    const yy = Math.max(y, this.world.heightAt(x, z) + 0.03);
    model.position.set(x, yy, z);
    model.rotation.y = rand(0, 6);
    this.scene.add(model);
    const p = { x, z, y: yy, kind, weaponId, model, active: true, baseY: yy, t: rand(0, 6) };
    this.pickups.push(p);
    return p;
  }

  updatePickups(dt, t) {
    const p = this.player;
    for (let i = this.pickups.length - 1; i >= 0; i--) {
      const pk = this.pickups[i];
      if (!pk.active) { this.pickups.splice(i, 1); continue; }
      pk.t += dt;
      pk.model.rotation.y += dt * 0.9;
      pk.model.position.y = pk.baseY + Math.sin(pk.t * 1.8) * 0.06;
      if (pk.model.userData.ring) {
        const s = 1 + Math.sin(pk.t * 2.4) * 0.12;
        pk.model.userData.ring.scale.setScalar(s);
      }
      if (p.alive && p.mode !== 'dead' && !this.vehicle) {
        const dx = p.pos.x - pk.x, dz = p.pos.z - pk.z;
        if (dx * dx + dz * dz < 2.6 * 2.6 && Math.abs(p.pos.y - pk.baseY) < 3) {
          this.collectPickup(pk);
        }
      }
    }
  }

  collectPickup(pk) {
    const p = this.player;
    pk.active = false;
    this.scene.remove(pk.model);
    audio.pickup();
    if (pk.kind === 'weapon') {
      const def = WEAPONS[pk.weaponId];
      const current = p.weapon.def;
      if (current.id === pk.weaponId) {
        p.weapon.reserve += def.reserve;
        this.hud.pickup(def.name, '+' + def.reserve + ' AMMO', 'i-gun');
        this.hud.updateAmmo();
      } else {
        p.equipId(pk.weaponId);
        this.hud.pickup(def.name, 'EQUIPPED', 'i-gun');
      }
    } else if (pk.kind === 'ammo') {
      p.weapon.reserve += Math.ceil(p.weapon.def.mag * 2.5);
      this.hud.pickup('AMMO', '+' + Math.ceil(p.weapon.def.mag * 2.5), 'i-gun');
      this.hud.updateAmmo();
    } else if (pk.kind === 'med') {
      p.medkits = Math.min(5, p.medkits + 1);
      this.hud.pickup('MEDKIT', '+1', 'i-med');
      this.hud.updateVitals();
    } else if (pk.kind === 'shield') {
      p.shields = Math.min(4, p.shields + 1);
      this.hud.pickup('SHIELD CELL', '+1', 'i-shield');
      this.hud.updateVitals();
    } else if (pk.kind === 'airdrop') {
      const id = pick(['longshot', 'raptor']);
      p.equipId(id);
      p.weapon.mag = p.weapon.def.mag;
      p.weapon.reserve = p.weapon.def.reserve;
      p.shields = Math.min(4, p.shields + 2);
      p.medkits = Math.min(5, p.medkits + 2);
      this.hud.pickup('LEGENDARY DROP', WEAPONS[id].name, 'i-trophy');
      this.hud.banner('AIRDROP SECURED', WEAPONS[id].name, 2200);
      this.hud.updateAmmo(); this.hud.updateVitals();
    }
  }

  dropBotLoot(bot) {
    const y = this.world.heightAt(bot.pos.x, bot.pos.z);
    this.spawnPickup(bot.pos.x + rand(-1.2, 1.2), bot.pos.z + rand(-1.2, 1.2), y, 'ammo');
    if (Math.random() > 0.35) this.spawnPickup(bot.pos.x + rand(-1, 1), bot.pos.z + rand(-1, 1), y, 'med');
    if (Math.random() > 0.45) this.spawnPickup(bot.pos.x + rand(-1, 1), bot.pos.z + rand(-1, 1), y, 'weapon', bot.weaponDef.id);
  }

  /* ---------------- vehicles ---------------- */
  spawnVehicles() {
    const spots = [...this.world.vehicleSpots];
    for (let i = spots.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [spots[i], spots[j]] = [spots[j], spots[i]]; }
    for (const s of spots) {
      if (this.vehicles.length >= 5) break;
      let x = s.x, z = s.z;
      let ok = false;
      for (let k = 0; k < 6; k++) {
        if (!this.world.isSolidAt(x, z, this.world.heightAt(x, z) + 1)) { ok = true; break; }
        x += rand(-4, 4); z += rand(-4, 4);
      }
      if (!ok) continue;
      const type = Math.random() > 0.65 ? 'truck' : 'buggy';
      const color = pick(['#c8652a', '#4b6b48', '#6b4a3a', '#3d5b6b', '#8a7a45']);
      const model = createVehicle(type, color);
      const gy = this.world.heightAt(x, z);
      model.position.set(x, gy + 0.1, z);
      model.rotation.y = s.yaw;
      this.scene.add(model);
      this.vehicles.push({
        model, pos: new THREE.Vector3(x, gy + 0.1, z), yaw: s.yaw, speed: 0,
        health: 100, wheels: model.userData.wheels, type, destroyed: false, lastHit: -10
      });
    }
  }

  nearestVehicle(maxDist = 4) {
    let best = null, bd = maxDist;
    for (const v of this.vehicles) {
      if (v.destroyed) continue;
      const d = Math.hypot(v.pos.x - this.player.pos.x, v.pos.z - this.player.pos.z);
      if (d < bd) { bd = d; best = v; }
    }
    return best;
  }

  enterVehicle(v) {
    if (!v || v.destroyed || this.vehicle) return;
    this.vehicle = v;
    this.player.mode = 'vehicle';
    this.player.adsAmount = 0; this.player.aiming = false;
    this.player.viewGroup.visible = false;
    if (this.playerModel) this.playerModel.visible = false;
    this.hud.root.classList.add('driving');
    this.hud.root.classList.remove('grounded');
    audio.startEngine();
    this.hud.toast('VEHICLE ACQUIRED', v.type.toUpperCase());
    document.getElementById('interact-hint').classList.add('hidden');
    const ti = document.getElementById('t-interact'); if (ti) ti.classList.add('hidden');
  }

  exitVehicle(force = false) {
    if (!this.vehicle) return;
    const v = this.vehicle;
    const side = new THREE.Vector3(Math.cos(v.yaw), 0, -Math.sin(v.yaw)).multiplyScalar(2.2);
    this.player.mode = 'fps';
    this.player.pos.set(v.pos.x + side.x, this.world.heightAt(v.pos.x + side.x, v.pos.z + side.z) + 0.05, v.pos.z + side.z);
    this.world.collide(this.player.pos, 0.4, this.player.pos.y);
    this.player.vel.set(0, 0, 0);
    this.player.viewGroup.visible = true;
    this.player.eyeHeight = 1.62;
    this.player.yaw = v.yaw;
    this.player.pitch = 0;
    this.player.buildViewModel();
    this.player.syncCamera(0.016);
    this.hud.root.classList.remove('driving');
    this.hud.root.classList.add('grounded');
    audio.stopEngine();
    this.vehicle = null;
    v.speed = 0;
  }

  updateVehicle(dt) {
    const v = this.vehicle;
    if (!v) return;
    const throttle = this.input.forward;
    const steer = this.input.strafe;
    const maxF = v.type === 'truck' ? 19 : 26;
    const target = throttle * (throttle >= 0 ? maxF : -8);
    v.speed = damp(v.speed, target, throttle ? 1.8 : 2.6, dt);
    if (Math.abs(v.speed) < 0.03) v.speed = 0;
    const steerAmt = clamp(Math.abs(v.speed) / 12, 0, 1.3);
    v.yaw -= steer * steerAmt * 1.45 * Math.sign(v.speed || 1) * dt;
    const fx = -Math.sin(v.yaw), fz = -Math.cos(v.yaw);
    const oldX = v.pos.x, oldZ = v.pos.z;
    v.pos.x += fx * v.speed * dt;
    v.pos.z += fz * v.speed * dt;
    this.world.collide(v.pos, 1.35, v.pos.y);
    const bump = Math.hypot(v.pos.x - oldX, v.pos.z - oldZ) < Math.abs(v.speed * dt) * 0.5;
    if (bump) {
      if (Math.abs(v.speed) > 10) { v.health -= Math.abs(v.speed) * 0.7; this.effects.impact(new THREE.Vector3(v.pos.x, v.pos.y + 1, v.pos.z), null, '#ffce7a', false); audio.land(); this.player.cameraShake = 0.04; }
      v.speed *= -0.22;
    }
    const gy = this.world.heightAt(v.pos.x, v.pos.z);
    v.pos.y = gy + 0.1;
    // tilt to terrain
    const fh = this.world.heightAt(v.pos.x + fx * 1.6, v.pos.z + fz * 1.6);
    const bh = this.world.heightAt(v.pos.x - fx * 1.6, v.pos.z - fz * 1.6);
    const rh = this.world.heightAt(v.pos.x + Math.cos(v.yaw) * 1.1, v.pos.z - Math.sin(v.yaw) * 1.1);
    const lh = this.world.heightAt(v.pos.x - Math.cos(v.yaw) * 1.1, v.pos.z + Math.sin(v.yaw) * 1.1);
    const pitch = Math.atan2(fh - bh, 3.2);
    const roll = Math.atan2(lh - rh, 2.2);
    v.model.position.copy(v.pos);
    v.model.rotation.order = 'YXZ';
    v.model.rotation.y = v.yaw;
    v.model.rotation.x = damp(v.model.rotation.x, -pitch, 6, dt);
    v.model.rotation.z = damp(v.model.rotation.z, roll, 6, dt);
    for (const w of v.wheels) w.rotation.x += v.speed * dt * 1.4;
    this.player.pos.set(v.pos.x, v.pos.y, v.pos.z);
    this.player.yaw = v.yaw;
    // camera
    const camTarget = new THREE.Vector3(v.pos.x - fx * 7.4 + Math.cos(v.yaw) * 0.0, v.pos.y + 3.7, v.pos.z - fz * 7.4);
    this.camera.position.lerp(camTarget, 1 - Math.exp(-6 * dt));
    const look = new THREE.Vector3(v.pos.x + fx * 3.5, v.pos.y + 1.35, v.pos.z + fz * 3.5);
    this.camera.lookAt(look);
    this.camera.rotation.z += roll * 0.3;
    this.camera.fov = damp(this.camera.fov, (this.profile.settings.fov || 74) + 6, 4, dt);
    this.camera.updateProjectionMatrix();
    audio.engineSpeed(Math.abs(v.speed));
    // run over bots
    if (Math.abs(v.speed) > 5) {
      for (const b of this.bots.bots) {
        if (!b.alive) continue;
        if (Math.hypot(b.pos.x - v.pos.x, b.pos.z - v.pos.z) < 2.4 && this.time - b.lastDamage > 0.5) {
          b.takeDamage(100, this.player, null, false, null);
          this.effects.impact(new THREE.Vector3(b.pos.x, b.pos.y + 1, b.pos.z), null, '#ff9a6a', true);
          this.player.kills++;
        }
      }
    }
    if (v.health <= 0) {
      v.destroyed = true;
      this.effects.explosion(new THREE.Vector3(v.pos.x, v.pos.y + 1, v.pos.z), 1.6);
      audio.explosion?.();
      this.scene.remove(v.model);
      this.player.takeDamage(28, null);
      this.exitVehicle(true);
      this.hud.toast('VEHICLE DESTROYED', 'BAILED OUT');
    }
  }

  interact() {
    if (this.vehicle) { this.exitVehicle(); return; }
    const v = this.nearestVehicle(4);
    if (v) this.enterVehicle(v);
  }

  /* ---------------- combat ---------------- */
  castShot(origin, dir, range, shooter) {
    const raycaster = new THREE.Raycaster(origin, dir, 0.1, range);
    const meshes = [];
    for (const b of this.bots.bots) if (b.alive && b.hitMeshes) meshes.push(...b.hitMeshes);
    const hits = raycaster.intersectObjects(meshes, false);
    let wallDist = this.world.rayBlock(origin, dir, range);
    // terrain via marching
    let terrainDist = range;
    const step = 2;
    const p = new THREE.Vector3();
    for (let d = step; d < Math.min(range, wallDist); d += step) {
      p.copy(origin).addScaledVector(dir, d);
      if (p.y <= this.world.heightAt(p.x, p.z)) { terrainDist = d; break; }
    }
    let botHit = null, zone = null, botDist = Infinity;
    for (const h of hits) {
      if (h.distance >= wallDist || h.distance >= terrainDist) continue;
      const bot = h.object.userData.bot;
      if (!bot || !bot.alive) continue;
      if (bot === shooter) continue;
      if (shooter && shooter !== this.player && shooter.team === bot.team) continue;
      botDist = h.distance; botHit = bot; zone = h.object.userData.hitZone;
      break;
    }
    const dist = Math.min(range, wallDist, terrainDist, botDist);
    const point = origin.clone().addScaledVector(dir, dist);
    return { point, bot: botHit, zone, distance: dist, normal: dir.clone().negate() };
  }

  damageBot(bot, amount, shooter, point, head, def) {
    if (!bot.alive) return;
    const was = bot.alive;
    bot.takeDamage(amount, shooter, point, head, def);
    this.player.damageDealt += amount;
    this.hud.hitmarker(head);
    if (was && !bot.alive) {
      this.effects.damageNumber(point, amount, head, true);
    } else {
      this.effects.damageNumber(point, amount, head, false);
    }
    this.hud.updateAlive();
    this.checkEnd();
  }

  onBotKilled(bot, killer, head, def) {
    const isPlayer = killer === this.player;
    const weaponName = (def || bot.weaponDef).short;
    if (isPlayer) {
      this.player.kills++;
      this.hud.killFeed(this.profile.name.toUpperCase(), bot.name.toUpperCase(), weaponName, true, head);
      this.hud.banner(head ? 'HEADSHOT ELIMINATION' : 'ENEMY ELIMINATED', bot.name.toUpperCase(), 1500);
      audio.kill();
      this.hud.updateAlive();
      this.hud.updateVitals();
    } else if (killer && killer.name) {
      killer.kills = (killer.kills || 0) + 1;
      this.hud.killFeed(killer.name.toUpperCase(), bot.name.toUpperCase(), weaponName, false, head);
      if (this.mode.id === 'tdm') this.bots.notifyKill(killer.team);
    } else {
      this.hud.killFeed('THE FIRESTORM', bot.name.toUpperCase(), null, false, false);
      if (this.mode.id === 'tdm') this.bots.notifyKill(bot.team === 0 ? 1 : 0);
    }
    this.hud.updateAlive();
    this.checkEnd();
  }

  onVirtualKill(killer, victim) {
    this.hud.killFeed(killer.toUpperCase(), victim.toUpperCase(), pick(['AR', 'SMG', 'SR', 'SG']), false, false);
    this.hud.updateAlive();
    this.checkEnd();
  }

  onTeamScore(scores) {
    this.hud.updateScore(scores[0], scores[1]);
    this.hud.updateAlive();
    if (scores[0] >= this.mode.killTarget || scores[1] >= this.mode.killTarget) {
      this.endMatch(scores[0] > scores[1], 'score');
    }
  }

  onPlayerDeath(source) {
    this.input.firing = false;
    this.player.adsAmount = 0;
    if (this.vehicle) this.exitVehicle(true);
    this.deathTimer = 0;
    this.hud.banner('YOU WERE ELIMINATED', source && source.name ? `BY ${source.name.toUpperCase()}` : 'THE ZONE CLAIMED YOU', 2400);
    this.hud.toggleScoreboard(false);
    if (source && source.name) {
      source.kills = (source.kills || 0) + 1;
      this.hud.killFeed(source.name.toUpperCase(), this.profile.name.toUpperCase(), source.weaponDef?.short || 'AR', false, false);
      if (this.mode.id === 'tdm') this.bots.notifyKill(source.team);
    } else {
      this.hud.killFeed('THE FIRESTORM', this.profile.name.toUpperCase(), null, false, false);
    }
    this.hud.updateAlive();
    if (this.mode.respawn) {
      this.respawnTimer = 3.2;
      this.hud.banner('RESPAWNING', '3 SECONDS', 2600);
    } else {
      this.hud.root.classList.add('dead');
      setTimeout(() => this.endMatch(false, 'death'), 2100);
    }
  }

  respawnPlayer() {
    const sp = pick(this.world.spawnPoints);
    this.player.resetForRespawn(sp.x, sp.z);
    this.player.syncCamera(0.016);
    this.player.buildViewModel();
    this.hud.root.classList.remove('dead');
    this.hud.updateVitals(); this.hud.updateAmmo();
    this.hud.banner('REDEPLOYED', 'BACK IN THE FIGHT', 1600);
    this.deathTimer = 0;
  }

  checkEnd() {
    if (this.over) return;
    if (this.mode.id === 'br' && this.dropDone && this.player.alive) {
      if (this.bots.aliveReal === 0 && this.bots.virtualAlive === 0) this.endMatch(true, 'last');
    }
  }

  endMatch(win, reason) {
    if (this.over) return;
    this.over = true;
    this.input.setEnabled(false);
    this.hud.hideDrop();
    this.hud.toggleScoreboard(false);
    if (this.vehicle) this.exitVehicle(true);
    const placement = win && this.mode.id === 'br' ? 1 : Math.max(1, this.bots.aliveCount + 1);
    const accuracy = this.player.shots ? (this.player.hits / this.player.shots) * 100 : 0;
    const time = Math.max(1, this.matchTime);
    const kills = this.player.kills;
    const data = {
      win: !!win, mode: this.mode.id, modeName: this.mode.name, placement,
      players: this.mode.players, kills, damage: this.player.damageDealt,
      time, accuracy, mapName: this.map.name, headshots: this.player.headshots,
      teamScores: this.bots.teamScores,
      coins: Math.round(120 + kills * 45 + (win ? 300 : 0) + placement * 3),
      xp: Math.round(180 + kills * 80 + (win ? 600 : 0) + this.player.damageDealt * 0.35),
      rankPts: Math.max(-15, kills * 6 + (win ? 40 : 0) - placement)
    };
    this.matchData = data;
    this.app.applyResult(data);
    setTimeout(() => {
      audio[win ? 'victory' : 'defeat']();
      this.hud.showResults(data);
      this.hud.hide();
    }, 900);
  }

  playAgain() {
    this.app.startMatch(this.mode.id, this.map.id);
  }
  returnToLobby() {
    this.app.endGame();
  }
  leaveMatch() {
    this.app.endGame();
  }
  skipDrop() {
    if (this.phase !== 'drop' || this.dropDone) return;
    const gy = this.world.heightAt(this.player.pos.x, this.player.pos.z);
    if (this.player.pos.y - gy > 28) {
      this.player.pos.y = gy + 24;
      this.parachute && (this.parachute.visible = true);
    } else this.landDrop();
  }

  /* ---------------- camera / drop ---------------- */
  updateCameraDrop(dt) {
    const p = this.player, cam = this.camera;
    const alt = p.pos.y - this.world.heightAt(p.pos.x, p.pos.z);
    const chute = alt < 55;
    if (this.parachute) this.parachute.visible = chute;
    if (this.playerModel) {
      this.playerModel.position.copy(p.pos);
      this.playerModel.rotation.y = p.yaw;
      if (!chute) {
        this.playerModel.rotation.x = damp(this.playerModel.rotation.x, -0.25, 2, dt);
      } else {
        this.playerModel.rotation.x = damp(this.playerModel.rotation.x, 0.05, 3, dt);
      }
    }
    const fwd = new THREE.Vector3(-Math.sin(p.yaw), 0, -Math.cos(p.yaw));
    const camPos = p.pos.clone().addScaledVector(fwd, -7.5).add(new THREE.Vector3(0, chute ? 3.4 : 2.4, 0));
    cam.position.lerp(camPos, 1 - Math.exp(-6 * dt));
    const look = p.pos.clone().addScaledVector(fwd, 6).add(new THREE.Vector3(0, 1.2, 0));
    cam.lookAt(look);
    if (chute) cam.rotation.z = Math.sin(this.time * 0.8) * 0.015;
    cam.fov = damp(cam.fov, (this.profile.settings.fov || 74) + (chute ? 4 : 10), 3, dt);
    cam.updateProjectionMatrix();
    this.world.update(dt, p.pos);
  }

  landDrop() {
    if (this.dropDone) return;
    const gy = this.world.heightAt(this.player.pos.x, this.player.pos.z);
    this.player.pos.y = gy + 0.05;
    this.player.mode = 'fps';
    this.player.eyeHeight = 1.62;
    this.dropDone = true;
    this.phase = 'play';
    this.playerModel.visible = false;
    if (this.parachute) this.parachute.visible = false;
    this.player.syncCamera(0.016);
    this.player.buildViewModel();
    this.input.setEnabled(true);
    this.hud.hideDrop();
    this.hud.root.classList.remove('dropping');
    this.hud.root.classList.add('grounded');
    this.hud.banner('DROP COMPLETE', this.target ? this.target.name : this.map.name, 2200);
    this.effects.impact(new THREE.Vector3(this.player.pos.x, this.player.pos.y + 0.1, this.player.pos.z), null, '#e8d9b8', false);
    this.effects.smoke(new THREE.Vector3(this.player.pos.x, this.player.pos.y + 0.3, this.player.pos.z), '#d9cbb0', 0.28, 1.6, 1.2);
    audio.land();
    this.camera.fov = this.player.baseFov;
    this.camera.updateProjectionMatrix();
    this.matchTime = 0;
    this.checkEnd();
  }

  updateDrop(dt) {
    const p = this.player;
    const look = this.input.consumeLook();
    p.yaw -= look.dx * (this.input.isTouch ? 0.0045 : 0.0022) * (this.profile.settings.sens || 1);
    p.pitch = clamp(p.pitch - look.dy * (this.input.isTouch ? 0.004 : 0.002), -0.9, 0.6);
    const alt = p.pos.y - this.world.heightAt(p.pos.x, p.pos.z);
    const chute = alt < 55;
    const steerSpeed = chute ? 9 : 15;
    const f = this.input.forward, s = this.input.strafe;
    if (this.introTimer <= 0) {
      const sin = Math.sin(p.yaw), cos = Math.cos(p.yaw);
      const vx = (-sin * f + cos * s) * steerSpeed;
      const vz = (-cos * f - sin * s) * steerSpeed;
      p.pos.x = clamp(p.pos.x + vx * dt, -280, 280);
      p.pos.z = clamp(p.pos.z + vz * dt, -280, 280);
    }
    const gy = this.world.heightAt(p.pos.x, p.pos.z);
    const descent = chute ? 6.5 : (this.input.keys.has('ShiftLeft') ? 34 : 21);
    p.pos.y -= descent * dt;
    if (p.pos.y <= Math.max(gy + 0.4, this.world.sea + 0.2)) {
      this.landDrop();
      return;
    }
    this.updateCameraDrop(dt);
    if (this.phase === 'drop') {
      const altNow = p.pos.y - gy;
      this.hud.updateDrop(1 - altNow / DROP_ALT, altNow, chute);
    }
  }

  /* ---------------- main update ---------------- */
  update(dt) {
    if (!this.active) return;
    this.time += dt;
    if (this.paused) { this.effects.update(dt); return; }
    if (!this.over && this.dropDone) this.matchTime += dt;

    if (this.phase === 'intro') {
      this.introTimer -= dt;
      if (this.mode.id === 'br') {
        this.updateDrop(dt);
        if (this.introTimer <= 0) {
          this.phase = 'drop';
          this.input.setEnabled(true);
          this.hud.showDrop(this.world, this.mode);
        }
      } else {
        if (this.introTimer <= 0) this.beginGroundMatch();
      }
    } else if (this.phase === 'drop') {
      this.updateDrop(dt);
    } else if (this.dropDone) {
      if (this.player.alive) {
        if (this.vehicle) {
          this.updateVehicle(dt);
          this.player.fireTimer = Math.max(0, this.player.fireTimer - dt);
          this.player.viewGroup.visible = false;
        } else {
          this.player.update(dt, this.input);
        }
      } else {
        this.deathTimer += dt;
        this.player.updateCameraShake(dt);
        if (this.mode.respawn && this.respawnTimer > 0) {
          this.respawnTimer -= dt;
          if (this.respawnTimer <= 0) this.respawnPlayer();
        }
      }
      if (this.bots) {
        this.bots.update(dt);
        this.bots.handleRespawns(dt);
      }
      this.updatePickups(dt, this.time);
      this.updateZone(dt);
      this.updateAirdrop(dt);
      this.updateInteract();
      this.world.update(dt, this.player.pos);
      this.hud.update(dt);
      if (this.zoneMesh) { this.zoneMat.uniforms.uTime.value = this.time; }
      if (this.airdropPos) { /* smoke */ }
      // periodic HUD update
      if (this.time - this.lastHud > 0.2) {
        this.lastHud = this.time;
        this.hud.updateAlive();
        this.hud.updateVitals();
      }
    } else {
      this.world.update(dt, this.player.pos);
    }
    this.effects.update(dt);
  }

  updateInteract() {
    if (this.vehicle) {
      document.getElementById('interact-hint').classList.add('hidden');
      const ti = document.getElementById('t-interact');
      if (ti) ti.classList.add('hidden');
      return;
    }
    const v = this.nearestVehicle(4);
    const hint = document.getElementById('interact-hint');
    const ti = document.getElementById('t-interact');
    if (v && this.player.alive) {
      hint.classList.remove('hidden');
      document.getElementById('interact-text').textContent = 'ENTER VEHICLE';
      hint.querySelector('kbd').textContent = 'F';
      if (ti) { ti.classList.remove('hidden'); ti.textContent = 'ENTER'; }
    } else {
      hint.classList.add('hidden');
      if (ti) ti.classList.add('hidden');
    }
  }

  updateAirdrop(dt) {
    if (!this.mode.airdrop || this.over) return;
    if (!this.airdrop && this.matchTime > this.airdropTimer) {
      const z = this.zone;
      let x = 0, zz = 0;
      for (let i = 0; i < 20; i++) {
        const a = rand(0, Math.PI * 2), r = Math.sqrt(Math.random()) * z.radius * 0.8;
        x = z.center.x + Math.cos(a) * r; zz = z.center.z + Math.sin(a) * r;
        if (this.world.heightAt(x, zz) > 1) break;
      }
      const y = this.world.heightAt(x, zz);
      const model = createPickupModel('airdrop', 'longshot');
      model.position.set(x, y + 55, zz);
      model.scale.setScalar(1.25);
      this.scene.add(model);
      this.airdrop = { model, x, z: zz, y, t: 0, landed: false };
      this.airdropPos = { x, z: zz };
      this.hud.banner('AIRDROP INBOUND', 'LEGENDARY CRATE DETECTED', 3200);
      audio.airdrop();
      this.hud.updateAlive();
    }
    if (this.airdrop && !this.airdrop.landed) {
      const a = this.airdrop;
      a.t += dt;
      a.model.position.y = Math.max(a.y, a.model.position.y - dt * 10);
      a.model.rotation.y += dt * 0.4;
      this.effects.smoke(a.model.position.clone().add(new THREE.Vector3(0, 1, 0)), '#d8d0c0', 0.1, 1.5, 0.8);
      if (a.model.position.y <= a.y) {
        a.landed = true;
        a.model.position.y = a.y;
        this.pickups.push({ x: a.x, z: a.z, y: a.y, kind: 'airdrop', weaponId: 'longshot', model: a.model, active: true, baseY: a.y, t: 0 });
        this.effects.smoke(new THREE.Vector3(a.x, a.y + 0.6, a.z), '#ff9d4a', 0.3, 2, 2);
      }
    }
    if (this.airdropPos && Math.random() < dt * 1.5) {
      this.effects.smoke(new THREE.Vector3(this.airdropPos.x + rand(-1, 1), this.world.heightAt(this.airdropPos.x, this.airdropPos.z) + 0.5, this.airdropPos.z + rand(-1, 1)), '#ff8a3a', 0.22, 1.5, 2.4);
    }
  }

  pause() {
    if (this.over || this.paused) return;
    this.paused = true;
    this.input.setEnabled(false);
    this.hud.togglePause(true);
  }
  resume() {
    if (this.over) return;
    this.paused = false;
    this.hud.togglePause(false);
    this.input.setEnabled(true);
    if (!this.input.isTouch) this.renderer.domElement.requestPointerLock?.();
  }
  openSettings() {
    this.paused = true;
    this.input.setEnabled(false);
    this.hud.togglePause(false);
    this.app.openSettings(() => { if (!this.over) this.resume(); });
  }

  dispose() {
    this.active = false;
    this.input.setEnabled(false);
    this.input.clearListeners();
    audio.stopEngine();
    this.scene.traverse(o => {
      if (o.isMesh || o.isPoints || o.isLine) {
        o.geometry?.dispose?.();
        if (o.material) (Array.isArray(o.material) ? o.material : [o.material]).forEach(m => { m.map?.dispose?.(); m.dispose?.(); });
      }
    });
    this.scene.clear();
    this.hud.hide();
    this.hud.hideResults();
    this.hud.togglePause(false);
    this.hud.root.classList.remove('driving', 'dead', 'dropping');
    this.world.dispose();
    if (this.bots) this.bots.dispose();
    this.vehicles.length = 0;
    this.pickups.length = 0;
  }
}

