173:   /* ---------------- zone ---------------- */
174:   setupZone() {
175:     if (!this.mode.zone) { this.zone = { active: false }; this.hud.setZone(this.zone); return; }
176:     const phases = [
177:       { wait: 22, shrink: 14, radius: 160 },
178:       { wait: 18, shrink: 13, radius: 105 },
179:       { wait: 16, shrink: 12, radius: 62 },
180:       { wait: 14, shrink: 11, radius: 32 },
181:       { wait: 12, shrink: 10, radius: 12 }
182:     ];
183:     this.zone = {
184:       active: true, phase: 0, phases, center: { x: 0, z: 0 }, radius: 255,
185:       nextCenter: { x: 0, z: 0 }, nextRadius: 160, startRadius: 255, startCenter: { x: 0, z: 0 },
186:       timeLeft: phases[0].wait, shrinking: false, damage: 3, outside: false, tick: 0
187:     };
188:     this.zone.nextCenter = this.pickZoneCenter(255, 160, { x: 0, z: 0 });
189:     this.zone.nextRadius = phases[0].radius;
190:     const mat = new THREE.ShaderMaterial({
191:       transparent: true, depthWrite: false, side: THREE.DoubleSide, blending: THREE.AdditiveBlending,
192:       uniforms: { uTime: { value: 0 }, uColor: { value: new THREE.Color(0xff5a1f) }, uOpacity: { value: 0.34 } },
193:       vertexShader: `varying vec2 vUv; void main(){vUv=uv; gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}`,
194:       fragmentShader: `uniform float uTime; uniform vec3 uColor; uniform float uOpacity; varying vec2 vUv;
195:         void main(){
196:           float band = smoothstep(0.45,0.5,abs(sin(vUv.x*70.0+uTime*0.6)));
197:           float scan = smoothstep(0.2,1.0,sin(vUv.y*24.0-uTime*1.3)*0.5+0.5);
198:           float vertical = smoothstep(0.0,0.35,vUv.y)*(1.0-smoothstep(0.85,1.0,vUv.y));
199:           float a = (0.06 + band*0.12 + scan*0.1) * vertical * uOpacity * 1.8;
200:           gl_FragColor = vec4(uColor, a);
201:         }`
202:     });
203:     this.zoneMat = mat;
204:     const cyl = new THREE.Mesh(new THREE.CylinderGeometry(1, 1, 1, 80, 1, true), mat);
205:     cyl.frustumCulled = false;
206:     this.zoneMesh = cyl;
207:     this.scene.add(cyl);
208:     const ringMat = new THREE.MeshBasicMaterial({ color: 0xff5a1f, transparent: true, opacity: 0.5, side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending });
209:     this.zoneRing = new THREE.Mesh(new THREE.RingGeometry(0.985, 1.0, 96), ringMat);
210:     this.zoneRing.rotation.x = -Math.PI / 2;
211:     this.zoneRing.frustumCulled = false;
212:     this.scene.add(this.zoneRing);
213:     this.updateZoneVisual();
214:     this.hud.setZone(this.zone);
215:   }
216: 
217:   pickZoneCenter(curR, nextR, curC) {
218:     const maxOffset = Math.max(0, curR - nextR) * 0.75;
219:     const a = rand(0, Math.PI * 2), d = Math.sqrt(Math.random()) * maxOffset;
220:     let x = curC.x + Math.cos(a) * d, z = curC.z + Math.sin(a) * d;
221:     const lim = 245 - nextR * 0.2;
222:     const r = Math.hypot(x, z);
223:     if (r > lim) { x *= lim / r; z *= lim / r; }
224:     return { x, z };
225:   }
226: 
227:   updateZone(dt) {
228:     const z = this.zone;
229:     if (!z || !z.active) return;
230:     z.timeLeft -= dt;
231:     if (!z.shrinking) {
232:       if (z.timeLeft <= 0 && z.phase < z.phases.length) {
233:         z.shrinking = true;
234:         z.timeLeft = z.phases[z.phase].shrink;
235:         z.shrinkDur = z.phases[z.phase].shrink;
236:         z.startRadius = z.radius;
237:         z.startCenter = { ...z.center };
238:       }
239:     } else {
240:       const p = clamp(1 - z.timeLeft / z.shrinkDur, 0, 1);
241:       z.radius = lerp(z.startRadius, z.nextRadius, p);
242:       z.center.x = lerp(z.startCenter.x, z.nextCenter.x, p);
243:       z.center.z = lerp(z.startCenter.z, z.nextCenter.z, p);
244:       if (z.timeLeft <= 0) {
245:         z.shrinking = false;
246:         z.phase++;
247:         z.damage = 3 + z.phase * 3;
248:         if (z.phase < z.phases.length) {
249:           z.timeLeft = z.phases[z.phase].wait;
250:           z.nextRadius = z.phases[z.phase].radius;
251:           z.nextCenter = this.pickZoneCenter(z.radius, z.nextRadius, z.center);
252:         } else {
253:           z.timeLeft = 999;
254:           z.nextRadius = z.radius;
255:           z.nextCenter = { ...z.center };
256:         }
257:       }
258:     }
259:     const d = Math.hypot(this.player.pos.x - z.center.x, this.player.pos.z - z.center.z);
260:     z.outside = d > z.radius;
261:     z.tick -= dt;
262:     if (z.tick <= 0) {
263:       z.tick = 1;
264:       if (z.outside) {
265:         this.player.takeDamage(z.damage, { pos: new THREE.Vector3(z.center.x, 0, z.center.z) });
266:         this.hud.warnZone?.();
267:         audio.warn();
268:       }
269:       for (const b of this.bots.bots) {
270:         if (!b.alive) continue;
271:         if (Math.hypot(b.pos.x - z.center.x, b.pos.z - z.center.z) > z.radius) b.takeDamage(z.damage + 2, null);
272:       }
273:     }
274:     this.updateZoneVisual();
275:     this.hud.setZone(z);
276:   }
277: 
278:   updateZoneVisual() {
279:     const z = this.zone;
280:     if (!z || !z.active || !this.zoneMesh) return;
281:     this.zoneMesh.scale.set(z.radius, 120, z.radius);
282:     this.zoneMesh.position.set(z.center.x, 60, z.center.z);
283:     this.zoneRing.scale.set(z.radius, z.radius, 1);
284:     this.zoneRing.position.set(z.center.x, this.world.heightAt(z.center.x, z.center.z) + 0.2, z.center.z);
285:     this.zoneRing.material.color.set(z.outside ? 0xff3828 : 0xff7a2a);
286:   }
