288:   /* ---------------- loot ---------------- */
289:   spawnPickups() {
290:     const spots = this.world.lootSpots;
291:     const step = Math.max(1, Math.floor(spots.length / 42));
292:     let count = 0;
293:     for (let i = 0; i < spots.length && count < 46; i += step) {
294:       const s = spots[i];
295:       let kind = s.kind;
296:       if (kind === 'random') kind = pick(['ammo', 'med', 'shield', 'ammo', 'med', 'weapon', 'shield']);
297:       const weaponId = kind === 'weapon' ? pick(['vanguard', 'viper', 'breaker', 'longshot', 'raptor']) : (kind === 'ammo' ? pick(['vanguard', 'viper', 'sidearm']) : null);
298:       this.spawnPickup(s.x, s.z, s.y, kind, weaponId);
299:       count++;
300:     }
301:   }
