303:   spawnPickup(x, z, y, kind, weaponId = null) {
304:     const model = createPickupModel(kind, weaponId || 'vanguard');
305:     const yy = Math.max(y, this.world.heightAt(x, z) + 0.03);
306:     model.position.set(x, yy, z);
307:     model.rotation.y = rand(0, 6);
308:     this.scene.add(model);
309:     const p = { x, z, y: yy, kind, weaponId, model, active: true, baseY: yy, t: rand(0, 6) };
310:     this.pickups.push(p);
311:     return p;
312:   }
