314:   updatePickups(dt, t) {
315:     const p = this.player;
316:     for (let i = this.pickups.length - 1; i >= 0; i--) {
317:       const pk = this.pickups[i];
318:       if (!pk.active) { this.pickups.splice(i, 1); continue; }
319:       pk.t += dt;
320:       pk.model.rotation.y += dt * 0.9;
321:       pk.model.position.y = pk.baseY + Math.sin(pk.t * 1.8) * 0.06;
322:       if (pk.model.userData.ring) {
323:         const s = 1 + Math.sin(pk.t * 2.4) * 0.12;
324:         pk.model.userData.ring.scale.setScalar(s);
325:       }
326:       if (p.alive && p.mode !== 'dead' && !this.vehicle) {
327:         const dx = p.pos.x - pk.x, dz = p.pos.z - pk.z;
328:         if (dx * dx + dz * dz < 2.6 * 2.6 && Math.abs(p.pos.y - pk.baseY) < 3) {
329:           this.collectPickup(pk);
330:         }
331:       }
332:     }
333:   }
