335:   collectPickup(pk) {
336:     const p = this.player;
337:     pk.active = false;
338:     this.scene.remove(pk.model);
339:     audio.pickup();
340:     if (pk.kind === 'weapon') {
341:       const def = WEAPONS[pk.weaponId];
342:       const current = p.weapon.def;
343:       if (current.id === pk.weaponId) {
344:         p.weapon.reserve += def.reserve;
345:         this.hud.pickup(def.name, '+' + def.reserve + ' AMMO', 'i-gun');
346:         this.hud.updateAmmo();
347:       } else {
348:         p.equipId(pk.weaponId);
349:         this.hud.pickup(def.name, 'EQUIPPED', 'i-gun');
350:       }
351:     } else if (pk.kind === 'ammo') {
352:       p.weapon.reserve += Math.ceil(p.weapon.def.mag * 2.5);
353:       this.hud.pickup('AMMO', '+' + Math.ceil(p.weapon.def.mag * 2.5), 'i-gun');
354:       this.hud.updateAmmo();
355:     } else if (pk.kind === 'med') {
356:       p.medkits = Math.min(5, p.medkits + 1);
357:       this.hud.pickup('MEDKIT', '+1', 'i-med');
358:       this.hud.updateVitals();
359:     } else if (pk.kind === 'shield') {
360:       p.shields = Math.min(4, p.shields + 1);
361:       this.hud.pickup('SHIELD CELL', '+1', 'i-shield');
362:       this.hud.updateVitals();
363:     } else if (pk.kind === 'airdrop') {
364:       const id = pick(['longshot', 'raptor']);
365:       p.equipId(id);
366:       p.weapon.mag = p.weapon.def.mag;
367:       p.weapon.reserve = p.weapon.def.reserve;
368:       p.shields = Math.min(4, p.shields + 2);
369:       p.medkits = Math.min(5, p.medkits + 2);
370:       this.hud.pickup('LEGENDARY DROP', WEAPONS[id].name, 'i-trophy');
371:       this.hud.banner('AIRDROP SECURED', WEAPONS[id].name, 2200);
372:       this.hud.updateAmmo(); this.hud.updateVitals();
373:     }
374:   }
