384:   spawnVehicles() {
385:     const spots = [...this.world.vehicleSpots];
386:     for (let i = spots.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [spots[i], spots[j]] = [spots[j], spots[i]]; }
387:     for (const s of spots) {
388:       if (this.vehicles.length >= 5) break;
389:       let x = s.x, z = s.z;
390:       let ok = false;
391:       for (let k = 0; k < 6; k++) {
392:         if (!this.world.isSolidAt(x, z, this.world.heightAt(x, z) + 1)) { ok = true; break; }
