398:       const model = createVehicle(type, color);
399:       const gy = this.world.heightAt(x, z);
400:       model.position.set(x, gy + 0.1, z);
401:       model.rotation.y = s.yaw;
402:       this.scene.add(model);
403:       this.vehicles.push({
404:         model, pos: new THREE.Vector3(x, gy + 0.1, z), yaw: s.yaw, speed: 0,
405:         health: 100, wheels: model.userData.wheels, type, destroyed: false, lastHit: -10
406:       });
407:     }
