456:   updateVehicle(dt) {
457:     const v = this.vehicle;
458:     if (!v) return;
459:     const throttle = this.input.forward;
460:     const steer = this.input.strafe;
461:     const maxF = v.type === 'truck' ? 19 : 26;
462:     const target = throttle * (throttle >= 0 ? maxF : -8);
463:     v.speed = damp(v.speed, target, throttle ? 1.8 : 2.6, dt);
464:     if (Math.abs(v.speed) < 0.03) v.speed = 0;
465:     const steerAmt = clamp(Math.abs(v.speed) / 12, 0, 1.3);
466:     v.yaw -= steer * steerAmt * 1.45 * Math.sign(v.speed || 1) * dt;
467:     const fx = -Math.sin(v.yaw), fz = -Math.cos(v.yaw);
468:     const oldX = v.pos.x, oldZ = v.pos.z;
469:     v.pos.x += fx * v.speed * dt;
470:     v.pos.z += fz * v.speed * dt;
471:     this.world.collide(v.pos, 1.35, v.pos.y);
472:     const bump = Math.hypot(v.pos.x - oldX, v.pos.z - oldZ) < Math.abs(v.speed * dt) * 0.5;
473:     if (bump) {
474:       if (Math.abs(v.speed) > 10) { v.health -= Math.abs(v.speed) * 0.7; this.effects.impact(new THREE.Vector3(v.pos.x, v.pos.y + 1, v.pos.z), null, '#ffce7a', false); audio.land(); this.player.cameraShake = 0.04; }
475:       v.speed *= -0.22;
476:     }
477:     const gy = this.world.heightAt(v.pos.x, v.pos.z);
478:     v.pos.y = gy + 0.1;
479:     // tilt to terrain
480:     const fh = this.world.heightAt(v.pos.x + fx * 1.6, v.pos.z + fz * 1.6);
481:     const bh = this.world.heightAt(v.pos.x - fx * 1.6, v.pos.z - fz * 1.6);
482:     const rh = this.world.heightAt(v.pos.x + Math.cos(v.yaw) * 1.1, v.pos.z - Math.sin(v.yaw) * 1.1);
483:     const lh = this.world.heightAt(v.pos.x - Math.cos(v.yaw) * 1.1, v.pos.z + Math.sin(v.yaw) * 1.1);
484:     const pitch = Math.atan2(fh - bh, 3.2);
485:     const roll = Math.atan2(lh - rh, 2.2);
486:     v.model.position.copy(v.pos);
487:     v.model.rotation.order = 'YXZ';
488:     v.model.rotation.y = v.yaw;
489:     v.model.rotation.x = damp(v.model.rotation.x, -pitch, 6, dt);
490:     v.model.rotation.z = damp(v.model.rotation.z, roll, 6, dt);
491:     for (const w of v.wheels) w.rotation.x += v.speed * dt * 1.4;
492:     this.player.pos.set(v.pos.x, v.pos.y, v.pos.z);
493:     this.player.yaw = v.yaw;
494:     // camera
495:     const camTarget = new THREE.Vector3(v.pos.x - fx * 7.4 + Math.cos(v.yaw) * 0.0, v.pos.y + 3.7, v.pos.z - fz * 7.4);
496:     this.camera.position.lerp(camTarget, 1 - Math.exp(-6 * dt));
497:     const look = new THREE.Vector3(v.pos.x + fx * 3.5, v.pos.y + 1.35, v.pos.z + fz * 3.5);
498:     this.camera.lookAt(look);
499:     this.camera.rotation.z += roll * 0.3;
500:     this.camera.fov = damp(this.camera.fov, (this.profile.settings.fov || 74) + 6, 4, dt);
501:     this.camera.updateProjectionMatrix();
502:     audio.engineSpeed(Math.abs(v.speed));
503:     // run over bots
504:     if (Math.abs(v.speed) > 5) {
505:       for (const b of this.bots.bots) {
506:         if (!b.alive) continue;
507:         if (Math.hypot(b.pos.x - v.pos.x, b.pos.z - v.pos.z) < 2.4 && this.time - b.lastDamage > 0.5) {
508:           b.takeDamage(100, this.player, null, false, null);
509:           this.effects.impact(new THREE.Vector3(b.pos.x, b.pos.y + 1, b.pos.z), null, '#ff9a6a', true);
510:           this.player.kills++;
511:         }
512:       }
513:     }
514:     if (v.health <= 0) {
515:       v.destroyed = true;
516:       this.effects.explosion(new THREE.Vector3(v.pos.x, v.pos.y + 1, v.pos.z), 1.6);
517:       audio.explosion?.();
518:       this.scene.remove(v.model);
519:       this.player.takeDamage(28, null);
520:       this.exitVehicle(true);
521:       this.hud.toast('VEHICLE DESTROYED', 'BAILED OUT');
522:     }
523:   }
