531:   /* ---------------- combat ---------------- */
532:   castShot(origin, dir, range, shooter) {
533:     const raycaster = new THREE.Raycaster(origin, dir, 0.1, range);
534:     const meshes = [];
535:     for (const b of this.bots.bots) if (b.alive && b.hitMeshes) meshes.push(...b.hitMeshes);
536:     const hits = raycaster.intersectObjects(meshes, false);
537:     let wallDist = this.world.rayBlock(origin, dir, range);
538:     // terrain via marching
539:     let terrainDist = range;
540:     const step = 2;
541:     const p = new THREE.Vector3();
542:     for (let d = step; d < Math.min(range, wallDist); d += step) {
543:       p.copy(origin).addScaledVector(dir, d);
544:       if (p.y <= this.world.heightAt(p.x, p.z)) { terrainDist = d; break; }
545:     }
546:     let botHit = null, zone = null, botDist = Infinity;
547:     for (const h of hits) {
548:       if (h.distance >= wallDist || h.distance >= terrainDist) continue;
549:       const bot = h.object.userData.bot;
550:       if (!bot || !bot.alive) continue;
551:       if (bot === shooter) continue;
552:       if (shooter && shooter !== this.player && shooter.team === bot.team) continue;
553:       botDist = h.distance; botHit = bot; zone = h.object.userData.hitZone;
554:       break;
555:     }
556:     const dist = Math.min(range, wallDist, terrainDist, botDist);
557:     const point = origin.clone().addScaledVector(dir, dist);
558:     return { point, bot: botHit, zone, distance: dist, normal: dir.clone().negate() };
559:   }
