561:   damageBot(bot, amount, shooter, point, head, def) {
562:     if (!bot.alive) return;
563:     const was = bot.alive;
564:     bot.takeDamage(amount, shooter, point, head, def);
565:     this.player.damageDealt += amount;
566:     this.hud.hitmarker(head);
567:     if (was && !bot.alive) {
568:       this.effects.damageNumber(point, amount, head, true);
569:     } else {
570:       this.effects.damageNumber(point, amount, head, false);
571:     }
572:     this.hud.updateAlive();
573:     this.checkEnd();
574:   }
