654:   endMatch(win, reason) {
655:     if (this.over) return;
656:     this.over = true;
657:     this.input.setEnabled(false);
658:     this.hud.hideDrop();
659:     this.hud.toggleScoreboard(false);
660:     if (this.vehicle) this.exitVehicle(true);
661:     const placement = win && this.mode.id === 'br' ? 1 : Math.max(1, this.bots.aliveCount + 1);
662:     const accuracy = this.player.shots ? (this.player.hits / this.player.shots) * 100 : 0;
663:     const time = Math.max(1, this.matchTime);
664:     const kills = this.player.kills;
665:     const data = {
666:       win: !!win, mode: this.mode.id, modeName: this.mode.name, placement,
667:       players: this.mode.players, kills, damage: this.player.damageDealt,
668:       time, accuracy, mapName: this.map.name, headshots: this.player.headshots,
669:       teamScores: this.bots.teamScores,
670:       coins: Math.round(120 + kills * 45 + (win ? 300 : 0) + placement * 3),
671:       xp: Math.round(180 + kills * 80 + (win ? 600 : 0) + this.player.damageDealt * 0.35),
672:       rankPts: Math.max(-15, kills * 6 + (win ? 40 : 0) - placement)
673:     };
674:     this.matchData = data;
675:     this.app.applyResult(data);
676:     setTimeout(() => {
677:       audio[win ? 'victory' : 'defeat']();
678:       this.hud.showResults(data);
679:       this.hud.hide();
680:     }, 900);
681:   }
