692:   skipDrop() {
693:     if (this.phase !== 'drop' || this.dropDone) return;
694:     const gy = this.world.heightAt(this.player.pos.x, this.player.pos.z);
695:     if (this.player.pos.y - gy > 28) {
696:       this.player.pos.y = gy + 24;
697:       this.parachute && (this.parachute.visible = true);
698:     } else this.landDrop();
699:   }
