701:   /* ---------------- camera / drop ---------------- */
702:   updateCameraDrop(dt) {
703:     const p = this.player, cam = this.camera;
704:     const alt = p.pos.y - this.world.heightAt(p.pos.x, p.pos.z);
705:     const chute = alt < 55;
706:     if (this.parachute) this.parachute.visible = chute;
707:     if (this.playerModel) {
708:       this.playerModel.position.copy(p.pos);
709:       this.playerModel.rotation.y = p.yaw;
710:       if (!chute) {
711:         this.playerModel.rotation.x = damp(this.playerModel.rotation.x, -0.25, 2, dt);
712:       } else {
713:         this.playerModel.rotation.x = damp(this.playerModel.rotation.x, 0.05, 3, dt);
714:       }
715:     }
716:     const fwd = new THREE.Vector3(-Math.sin(p.yaw), 0, -Math.cos(p.yaw));
717:     const camPos = p.pos.clone().addScaledVector(fwd, -7.5).add(new THREE.Vector3(0, chute ? 3.4 : 2.4, 0));
718:     cam.position.lerp(camPos, 1 - Math.exp(-6 * dt));
719:     const look = p.pos.clone().addScaledVector(fwd, 6).add(new THREE.Vector3(0, 1.2, 0));
720:     cam.lookAt(look);
721:     if (chute) cam.rotation.z = Math.sin(this.time * 0.8) * 0.015;
722:     cam.fov = damp(cam.fov, (this.profile.settings.fov || 74) + (chute ? 4 : 10), 3, dt);
723:     cam.updateProjectionMatrix();
724:     this.world.update(dt, p.pos);
725:   }
