727:   landDrop() {
728:     if (this.dropDone) return;
729:     const gy = this.world.heightAt(this.player.pos.x, this.player.pos.z);
730:     this.player.pos.y = gy + 0.05;
731:     this.player.mode = 'fps';
732:     this.player.eyeHeight = 1.62;
733:     this.dropDone = true;
734:     this.phase = 'play';
735:     this.playerModel.visible = false;
736:     if (this.parachute) this.parachute.visible = false;
737:     this.player.syncCamera(0.016);
738:     this.player.buildViewModel();
739:     this.input.setEnabled(true);
740:     this.hud.hideDrop();
741:     this.hud.root.classList.remove('dropping');
742:     this.hud.root.classList.add('grounded');
743:     this.hud.banner('DROP COMPLETE', this.target ? this.target.name : this.map.name, 2200);
744:     this.effects.impact(new THREE.Vector3(this.player.pos.x, this.player.pos.y + 0.1, this.player.pos.z), null, '#e8d9b8', false);
745:     this.effects.smoke(new THREE.Vector3(this.player.pos.x, this.player.pos.y + 0.3, this.player.pos.z), '#d9cbb0', 0.28, 1.6, 1.2);
746:     audio.land();
747:     this.camera.fov = this.player.baseFov;
748:     this.camera.updateProjectionMatrix();
749:     this.matchTime = 0;
750:     this.checkEnd();
751:   }
