753:   updateDrop(dt) {
754:     const p = this.player;
755:     const look = this.input.consumeLook();
756:     p.yaw -= look.dx * (this.input.isTouch ? 0.0045 : 0.0022) * (this.profile.settings.sens || 1);
757:     p.pitch = clamp(p.pitch - look.dy * (this.input.isTouch ? 0.004 : 0.002), -0.9, 0.6);
758:     const alt = p.pos.y - this.world.heightAt(p.pos.x, p.pos.z);
759:     const chute = alt < 55;
760:     const steerSpeed = chute ? 9 : 15;
761:     const f = this.input.forward, s = this.input.strafe;
762:     if (this.introTimer <= 0) {
763:       const sin = Math.sin(p.yaw), cos = Math.cos(p.yaw);
764:       const vx = (-sin * f + cos * s) * steerSpeed;
765:       const vz = (-cos * f - sin * s) * steerSpeed;
766:       p.pos.x = clamp(p.pos.x + vx * dt, -280, 280);
767:       p.pos.z = clamp(p.pos.z + vz * dt, -280, 280);
768:     }
769:     const gy = this.world.heightAt(p.pos.x, p.pos.z);
770:     const descent = chute ? 6.5 : (this.input.keys.has('ShiftLeft') ? 34 : 21);
771:     p.pos.y -= descent * dt;
772:     if (p.pos.y <= Math.max(gy + 0.4, this.world.sea + 0.2)) {
773:       this.landDrop();
774:       return;
775:     }
776:     this.updateCameraDrop(dt);
777:     if (this.phase === 'drop') {
778:       const altNow = p.pos.y - gy;
779:       this.hud.updateDrop(1 - altNow / DROP_ALT, altNow, chute);
780:     }
781:   }
