783:   /* ---------------- main update ---------------- */
784:   update(dt) {
785:     if (!this.active) return;
786:     this.time += dt;
787:     if (this.paused) { this.effects.update(dt); return; }
788:     if (!this.over && this.dropDone) this.matchTime += dt;
789: 
790:     if (this.phase === 'intro') {
791:       this.introTimer -= dt;
792:       if (this.mode.id === 'br') {
793:         this.updateDrop(dt);
794:         if (this.introTimer <= 0) {
795:           this.phase = 'drop';
796:           this.input.setEnabled(true);
797:           this.hud.showDrop(this.world, this.mode);
798:         }
799:       } else {
800:         if (this.introTimer <= 0) this.beginGroundMatch();
801:       }
802:     } else if (this.phase === 'drop') {
803:       this.updateDrop(dt);
804:     } else if (this.dropDone) {
805:       if (this.player.alive) {
806:         if (this.vehicle) {
807:           this.updateVehicle(dt);
808:           this.player.fireTimer = Math.max(0, this.player.fireTimer - dt);
809:           this.player.viewGroup.visible = false;
810:         } else {
811:           this.player.update(dt, this.input);
812:         }
813:       } else {
814:         this.deathTimer += dt;
815:         this.player.updateCameraShake(dt);
816:         if (this.mode.respawn && this.respawnTimer > 0) {
817:           this.respawnTimer -= dt;
818:           if (this.respawnTimer <= 0) this.respawnPlayer();
819:         }
820:       }
821:       if (this.bots) {
822:         this.bots.update(dt);
823:         this.bots.handleRespawns(dt);
824:       }
825:       this.updatePickups(dt, this.time);
826:       this.updateZone(dt);
827:       this.updateAirdrop(dt);
828:       this.updateInteract();
829:       this.world.update(dt, this.player.pos);
830:       this.hud.update(dt);
831:       if (this.zoneMesh) { this.zoneMat.uniforms.uTime.value = this.time; }
832:       if (this.airdropPos) { /* smoke */ }
833:       // periodic HUD update
834:       if (this.time - this.lastHud > 0.2) {
835:         this.lastHud = this.time;
836:         this.hud.updateAlive();
837:         this.hud.updateVitals();
838:       }
839:     } else {
840:       this.world.update(dt, this.player.pos);
841:     }
842:     this.effects.update(dt);
843:   }
