866:   updateAirdrop(dt) {
867:     if (!this.mode.airdrop || this.over) return;
868:     if (!this.airdrop && this.matchTime > this.airdropTimer) {
869:       const z = this.zone;
870:       let x = 0, zz = 0;
871:       for (let i = 0; i < 20; i++) {
872:         const a = rand(0, Math.PI * 2), r = Math.sqrt(Math.random()) * z.radius * 0.8;
873:         x = z.center.x + Math.cos(a) * r; zz = z.center.z + Math.sin(a) * r;
874:         if (this.world.heightAt(x, zz) > 1) break;
875:       }
876:       const y = this.world.heightAt(x, zz);
877:       const model = createPickupModel('airdrop', 'longshot');
878:       model.position.set(x, y + 55, zz);
879:       model.scale.setScalar(1.25);
880:       this.scene.add(model);
881:       this.airdrop = { model, x, z: zz, y, t: 0, landed: false };
882:       this.airdropPos = { x, z: zz };
883:       this.hud.banner('AIRDROP INBOUND', 'LEGENDARY CRATE DETECTED', 3200);
884:       audio.airdrop();
885:       this.hud.updateAlive();
886:     }
887:     if (this.airdrop && !this.airdrop.landed) {
888:       const a = this.airdrop;
889:       a.t += dt;
890:       a.model.position.y = Math.max(a.y, a.model.position.y - dt * 10);
891:       a.model.rotation.y += dt * 0.4;
892:       this.effects.smoke(a.model.position.clone().add(new THREE.Vector3(0, 1, 0)), '#d8d0c0', 0.1, 1.5, 0.8);
893:       if (a.model.position.y <= a.y) {
894:         a.landed = true;
895:         a.model.position.y = a.y;
896:         this.pickups.push({ x: a.x, z: a.z, y: a.y, kind: 'airdrop', weaponId: 'longshot', model: a.model, active: true, baseY: a.y, t: 0 });
897:         this.effects.smoke(new THREE.Vector3(a.x, a.y + 0.6, a.z), '#ff9d4a', 0.3, 2, 2);
898:       }
899:     }
900:     if (this.airdropPos && Math.random() < dt * 1.5) {
901:       this.effects.smoke(new THREE.Vector3(this.airdropPos.x + rand(-1, 1), this.world.heightAt(this.airdropPos.x, this.airdropPos.z) + 0.5, this.airdropPos.z + rand(-1, 1)), '#ff8a3a', 0.22, 1.5, 2.4);
902:     }
903:   }
