280:     if (!this.lobbyDragging) this.lobbyRotation += dt * 0.075;
281:     l.avatarPivot.rotation.y = this.lobbyRotation;
282:     l.avatarPivot.position.y = Math.sin(l.time * 1.15) * 0.012;
283:     if (l.avatar) {
284:       const parts = l.avatar.userData.parts;
285:       if (parts) {
286:         parts.torso.position.y = 1.2 + Math.sin(l.time * 1.5) * 0.008;
287:         parts.leftArm.rotation.x = -1.32 + Math.sin(l.time * 1.2) * 0.025;
288:         parts.rightArm.rotation.x = -1.18 + Math.sin(l.time * 1.2 + 0.4) * 0.02;
289:         parts.head.rotation.y = Math.sin(l.time * 0.55) * 0.08;
290:       }
291:     }
292:     l.embers.rotation.y = l.time * 0.018;
293:     const pos = l.embers.geometry.attributes.position;
294:     const a = pos.array;
295:     for (let i = 0; i < l.speeds.length; i++) {
296:       a[i * 3 + 1] += dt * l.speeds[i];
297:       if (a[i * 3 + 1] > 5) {
298:         a[i * 3 + 1] = 0;
299:         a[i * 3] = (Math.random() - 0.5) * 9;
300:         a[i * 3 + 2] = (Math.random() - 0.5) * 7;
301:       }
302:     }
303:     pos.needsUpdate = true;
304:   }
