317:     const started = performance.now();
318:     const duration = 2100;
319:     const tick = () => {
320:       const p = Math.min(1, (performance.now() - started) / duration);
321:       let step = LOAD_STEPS[0];
322:       for (const s of LOAD_STEPS) if (p >= s[0] - 0.001) step = s;
323:       const pct = Math.round(p * 100);
324:       $('#load-fill').style.width = pct + '%';
325:       $('#load-pct').textContent = pct + '%';
326:       $('#load-status').textContent = step[1];
327:       if (p < 1) requestAnimationFrame(tick);
328:       else this.hideLoading();
329:     };
330:     requestAnimationFrame(tick);
331:   }
