356:   /* ============================================================
357:      Match lifecycle
358:      ============================================================ */
359:   async startMatch(modeId = this.selectedMode || this.profile.mode, mapId = this.selectedMap || this.profile.map) {
360:     if (this.starting) return;
361:     this.starting = true;
362:     try {
363:       this.closeModal();
364:       audio.init();
365:       this.selectedMode = MODES[modeId] ? modeId : 'br';
366:       this.selectedMap = MAPS[mapId] ? mapId : 'bermuda';
367:       this.profile.mode = this.selectedMode;
368:       this.profile.map = this.selectedMap;
369:       saveProfile(this.profile);
370:       this.syncProfileUI();
371: 
372:       $('#results').classList.add('hidden');
373:       this.hud.hideResults();
374:       this.showLoading();
375:       await this.delay(220);
376:       this.setMatchLoading(0.28, 'SYNCING OPERATORS');
377:       await this.delay(120);
378: 
379:       if (this.game) {
380:         this.game.dispose();
381:         this.game = null;
382:       }
383:       this.setMatchLoading(0.52, 'BUILDING BATTLEGROUND');
384:       await this.delay(70);
385: 
386:       const mode = MODES[this.selectedMode];
387:       const map = MAPS[this.selectedMap];
388:       this.qualityKey = this.resolveQuality(this.profile.settings.quality);
389:       this.game = new Game({
390:         renderer: this.renderer,
391:         profile: this.profile,
392:         map,
393:         mode,
394:         hud: this.hud,
395:         input: this.input,
396:         quality: this.qualityKey,
397:         startMatch: this.startMatch.bind(this),
398:         endGame: this.endGame.bind(this),
399:         applyResult: this.applyResult.bind(this),
400:         openSettings: this.openSettings.bind(this),
401:         setGame: game => { this.game = game; }
402:       });
403: 
404:       this.setMatchLoading(0.86, 'DEPLOYING OPERATOR');
405:       await this.delay(180);
406:       this.setMatchLoading(1, 'MATCH LIVE');
407:       await this.delay(110);
408:       this.hideLoading();
409:       this.starting = false;
410:     } catch (err) {
411:       console.error('[BLAZE] Failed to start match:', err);
412:       this.starting = false;
413:       this.hideLoading();
414:       if (this.game) { try { this.game.dispose(); } catch {} this.game = null; }
415:       $('#lobby').classList.remove('hidden');
416:       this.renderer.domElement.classList.remove('in-game');
417:       this.toast('DEPLOYMENT FAILED', 'CHECK THE CONSOLE AND TRY AGAIN');
418:     }
419:   }
420: 
421:   applyResult(data) {
422:     this.profile = applyMatchResult(this.profile, data);
423:     this.applyOutfitCache();
424:     this.syncProfileUI();
425:     saveProfile(this.profile);
426:   }
427: 
428:   endGame() {
429:     if (this.game) {
430:       try { this.game.dispose(); } catch (err) { console.warn(err); }
431:       this.game = null;
432:     }
433:     this.input.setEnabled(false);
434:     if (document.pointerLockElement) document.exitPointerLock?.();
435:     this.hideLockHint();
436:     this.hud.hide();
437:     this.hud.hideResults();
438:     this.hud.togglePause(false);
439:     $('#results').classList.add('hidden');
440:     $('#lobby').classList.remove('hidden');
441:     this.renderer.domElement.classList.remove('in-game');
442:     this.syncProfileUI();
443:     this.refreshLobbyAvatar();
444:   }
