241:     this.scene.add(cyl);
242:     const ringMat = new THREE.MeshBasicMaterial({ color: 0xff5a1f, transparent: true, opacity: 0.5, side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending });
243:     this.zoneRing = new THREE.Mesh(new THREE.RingGeometry(0.985, 1.0, 96), ringMat);
244:     this.zoneRing.rotation.x = -Math.PI / 2;
245:     this.zoneRing.frustumCulled = false;
