251:   pickZoneCenter(curR, nextR, curC) {
252:     const maxOffset = Math.max(0, curR - nextR) * 0.75;
253:     const a = rand(0, Math.PI * 2), d = Math.sqrt(Math.random()) * maxOffset;
254:     let x = curC.x + Math.cos(a) * d, z = curC.z + Math.sin(a) * d;
255:     const lim = 245 - nextR * 0.2;
256:     const r = Math.hypot(x, z);
257:     if (r > lim) { x *= lim / r; z *= lim / r; }
258:     return { x, z };
259:   }
