261:   updateZone(dt) {
262:     const z = this.zone;
263:     if (!z || !z.active) return;
264:     z.timeLeft -= dt;
265:     if (!z.shrinking) {
266:       if (z.timeLeft <= 0 && z.phase < z.phases.length) {
267:         z.shrinking = true;
268:         z.timeLeft = z.phases[z.phase].shrink;
269:         z.shrinkDur = z.phases[z.phase].shrink;
270:         z.startRadius = z.radius;
271:         z.startCenter = { ...z.center };
272:       }
273:     } else {
274:       const p = clamp(1 - z.timeLeft / z.shrinkDur, 0, 1);
275:       z.radius = lerp(z.startRadius, z.nextRadius, p);
276:       z.center.x = lerp(z.startCenter.x, z.nextCenter.x, p);
277:       z.center.z = lerp(z.startCenter.z, z.nextCenter.z, p);
278:       if (z.timeLeft <= 0) {
279:         z.shrinking = false;
280:         z.phase++;
281:         z.damage = 3 + z.phase * 3;
282:         if (z.phase < z.phases.length) {
283:           z.timeLeft = z.phases[z.phase].wait;
284:           z.nextRadius = z.phases[z.phase].radius;
285:           z.nextCenter = this.pickZoneCenter(z.radius, z.nextRadius, z.center);
286:         } else {
287:           z.timeLeft = 999;
288:           z.nextRadius = z.radius;
289:           z.nextCenter = { ...z.center };
290:         }
291:       }
292:     }
293:     const d = Math.hypot(this.player.pos.x - z.center.x, this.player.pos.z - z.center.z);
294:     z.outside = d > z.radius;
295:     z.tick -= dt;
296:     if (z.tick <= 0) {
297:       z.tick = 1;
298:       if (z.outside) {
299:         this.player.takeDamage(z.damage, { pos: new THREE.Vector3(z.center.x, 0, z.center.z) });
300:         this.hud.warnZone?.();
301:         audio.warn();
302:       }
303:       for (const b of this.bots.bots) {
304:         if (!b.alive) continue;
305:         if (Math.hypot(b.pos.x - z.center.x, b.pos.z - z.center.z) > z.radius) b.takeDamage(z.damage + 2, null);
306:       }
307:     }
308:     this.updateZoneVisual();
309:     this.hud.setZone(z);
310:   }
