490:   updateVehicle(dt) {
491:     const v = this.vehicle;
492:     if (!v) return;
493:     const throttle = this.input.forward;
494:     const steer = this.input.strafe;
495:     const maxF = v.type === 'truck' ? 19 : 26;
496:     const target = throttle * (throttle >= 0 ? maxF : -8);
497:     v.speed = damp(v.speed, target, throttle ? 1.8 : 2.6, dt);
498:     if (Math.abs(v.speed) < 0.03) v.speed = 0;
499:     const steerAmt = clamp(Math.abs(v.speed) / 12, 0, 1.3);
500:     v.yaw -= steer * steerAmt * 1.45 * Math.sign(v.speed || 1) * dt;
501:     const fx = -Math.sin(v.yaw), fz = -Math.cos(v.yaw);
502:     const oldX = v.pos.x, oldZ = v.pos.z;
503:     v.pos.x += fx * v.speed * dt;
504:     v.pos.z += fz * v.speed * dt;
505:     this.world.collide(v.pos, 1.35, v.pos.y);
506:     const bump = Math.hypot(v.pos.x - oldX, v.pos.z - oldZ) < Math.abs(v.speed * dt) * 0.5;
507:     if (bump) {
508:       if (Math.abs(v.speed) > 10) { v.health -= Math.abs(v.speed) * 0.7; this.effects.impact(new THREE.Vector3(v.pos.x, v.pos.y + 1, v.pos.z), null, '#ffce7a', false); audio.land(); this.player.cameraShake = 0.04; }
509:       v.speed *= -0.22;
510:     }
511:     const gy = this.world.heightAt(v.pos.x, v.pos.z);
512:     v.pos.y = gy + 0.1;
513:     // tilt to terrain
514:     const fh = this.world.heightAt(v.pos.x + fx * 1.6, v.pos.z + fz * 1.6);
515:     const bh = this.world.heightAt(v.pos.x - fx * 1.6, v.pos.z - fz * 1.6);
516:     const rh = this.world.heightAt(v.pos.x + Math.cos(v.yaw) * 1.1, v.pos.z - Math.sin(v.yaw) * 1.1);
517:     const lh = this.world.heightAt(v.pos.x - Math.cos(v.yaw) * 1.1, v.pos.z + Math.sin(v.yaw) * 1.1);
518:     const pitch = Math.atan2(fh - bh, 3.2);
519:     const roll = Math.atan2(lh - rh, 2.2);
520:     v.model.position.copy(v.pos);
521:     v.model.rotation.order = 'YXZ';
522:     v.model.rotation.y = v.yaw;
523:     v.model.rotation.x = damp(v.model.rotation.x, -pitch, 6, dt);
524:     v.model.rotation.z = damp(v.model.rotation.z, roll, 6, dt);
525:     for (const w of v.wheels) w.rotation.x += v.speed * dt * 1.4;
526:     this.player.pos.set(v.pos.x, v.pos.y, v.pos.z);
527:     this.player.yaw = v.yaw;
528:     // camera
529:     const camTarget = new THREE.Vector3(v.pos.x - fx * 7.4 + Math.cos(v.yaw) * 0.0, v.pos.y + 3.7, v.pos.z - fz * 7.4);
530:     this.camera.position.lerp(camTarget, 1 - Math.exp(-6 * dt));
531:     const look = new THREE.Vector3(v.pos.x + fx * 3.5, v.pos.y + 1.35, v.pos.z + fz * 3.5);
532:     this.camera.lookAt(look);
533:     this.camera.rotation.z += roll * 0.3;
534:     this.camera.fov = damp(this.camera.fov, (this.profile.settings.fov || 74) + 6, 4, dt);
535:     this.camera.updateProjectionMatrix();
536:     audio.engineSpeed(Math.abs(v.speed));
537:     // run over bots
538:     if (Math.abs(v.speed) > 5) {
539:       for (const b of this.bots.bots) {
540:         if (!b.alive) continue;
541:         if (Math.hypot(b.pos.x - v.pos.x, b.pos.z - v.pos.z) < 2.4 && this.time - b.lastDamage > 0.5) {
542:           b.takeDamage(100, this.player, null, false, null);
543:           this.effects.impact(new THREE.Vector3(b.pos.x, b.pos.y + 1, b.pos.z), null, '#ff9a6a', true);
544:           this.player.kills++;
545:         }
546:       }
547:     }
548:     if (v.health <= 0) {
549:       v.destroyed = true;
550:       this.effects.explosion(new THREE.Vector3(v.pos.x, v.pos.y + 1, v.pos.z), 1.6);
551:       audio.explosion?.();
552:       this.scene.remove(v.model);
553:       this.player.takeDamage(28, null);
554:       this.exitVehicle(true);
555:       this.hud.toast('VEHICLE DESTROYED', 'BAILED OUT');
556:     }
557:   }
