565:   /* ---------------- combat ---------------- */
566:   castShot(origin, dir, range, shooter) {
567:     const raycaster = new THREE.Raycaster(origin, dir, 0.1, range);
568:     const meshes = [];
569:     for (const b of this.bots.bots) if (b.alive && b.hitMeshes) meshes.push(...b.hitMeshes);
570:     const hits = raycaster.intersectObjects(meshes, false);
571:     let wallDist = this.world.rayBlock(origin, dir, range);
572:     // terrain via marching
573:     let terrainDist = range;
574:     const step = 2;
575:     const p = new THREE.Vector3();
576:     for (let d = step; d < Math.min(range, wallDist); d += step) {
577:       p.copy(origin).addScaledVector(dir, d);
578:       if (p.y <= this.world.heightAt(p.x, p.z)) { terrainDist = d; break; }
579:     }
580:     let botHit = null, zone = null, botDist = Infinity;
581:     for (const h of hits) {
582:       if (h.distance >= wallDist || h.distance >= terrainDist) continue;
583:       const bot = h.object.userData.bot;
584:       if (!bot || !bot.alive) continue;
585:       if (bot === shooter) continue;
586:       if (shooter && shooter !== this.player && shooter.team === bot.team) continue;
587:       botDist = h.distance; botHit = bot; zone = h.object.userData.hitZone;
588:       break;
589:     }
590:     const dist = Math.min(range, wallDist, terrainDist, botDist);
591:     const point = origin.clone().addScaledVector(dir, dist);
592:     return { point, bot: botHit, zone, distance: dist, normal: dir.clone().negate() };
593:   }
