599:     this.player.damageDealt += amount;
600:     this.hud.hitmarker(head);
601:     if (was && !bot.alive) {
602:       this.effects.damageNumber(point, amount, head, true);
603:     } else {
604:       this.effects.damageNumber(point, amount, head, false);
605:     }
606:     this.hud.updateAlive();
607:     this.checkEnd();
