162:     const targetEye = crouchWanted ? EYE_CROUCH : EYE_STAND;
163:     this.eyeHeight = damp(this.eyeHeight, targetEye, 12, dt);
164: 
165:     let wx = 0, wz = 0;
166:     if (this.mode === 'fps') {
167:       const f = input.forward, s = input.strafe;
168:       const len = Math.hypot(f, s);
169:       const sprinting = input.sprinting && !this.aiming && !crouchWanted && f > 0.2;
170:       this.sprinting = sprinting;
171:       let speed = crouchWanted ? 2.6 : (sprinting ? 7.2 : 4.85);
172:       if (this.aiming) speed = 2.9;
173:       if (this.inWater) speed *= 0.6;
174:       if (len > 0.01) {
175:         const nf = f / Math.max(len, 1), ns = s / Math.max(len, 1);
176:         const sin = Math.sin(this.yaw), cos = Math.cos(this.yaw);
177:         wx = (-sin * nf + cos * ns) * speed;
178:         wz = (-cos * nf - sin * ns) * speed;
179:       }
180:     }
181:     const accel = this.grounded ? 14 : 3.2;
182:     this.vel.x = damp(this.vel.x, wx, accel, dt);
183:     this.vel.z = damp(this.vel.z, wz, accel, dt);
184:     this.vel.y -= 21 * dt;
185: 
186:     const oldY = this.pos.y;
187:     this.pos.x += this.vel.x * dt;
188:     this.pos.z += this.vel.z * dt;
189:     this.world.collide(this.pos, 0.4, this.pos.y);
190:     this.pos.y += this.vel.y * dt;
191: 
192:     const ground = Math.max(this.world.heightAt(this.pos.x, this.pos.z), this.world.sea - 0.82);
193:     this.inWater = this.world.heightAt(this.pos.x, this.pos.z) < this.world.sea - 0.1;
194:     if (this.pos.y <= ground) {
195:       if (this.vel.y < -7) { this.landKick = clamp(-this.vel.y * 0.008, 0.02, 0.09); audio.land(); }
196:       this.pos.y = ground;
197:       this.vel.y = 0;
198:       this.grounded = true;
199:     } else {
200:       this.grounded = false;
201:     }
202:     this.speed = Math.hypot(this.vel.x, this.vel.z);
203: 
204:     // footsteps + bob
205:     if (this.grounded && this.speed > 1.2) {
206:       this.bobPhase += dt * (this.sprinting ? 11 : 8) * (this.crouching ? 0.6 : 1);
207:       this.stepTimer -= dt;
208:       if (this.stepTimer <= 0) {
209:         this.stepTimer = this.sprinting ? 0.27 : 0.38;
210:         audio.step();
211:       }
212:     }
213:     this.landKick = damp(this.landKick, 0, 8, dt);
214:     this.recoilPitch = damp(this.recoilPitch, 0, 9, dt);
215:     this.recoilYaw = damp(this.recoilYaw, 0, 9, dt);
216:     this.recoilRoll = damp(this.recoilRoll, 0, 8, dt);
217:     this.cameraShake = damp(this.cameraShake, 0, 11, dt);
218: 
219:     // health regen after 9s
220:     if (this.alive && this.health < 100 && this.game.time - this.lastDamageTime > 9) {
221:       this.health = Math.min(100, this.health + dt * 3.2);
222:     }
223:     this.useCooldown = Math.max(0, this.useCooldown - dt);
224:     this.syncCamera(dt);
225:     this.updateWeapon(dt, input);
226:     this.updateViewModel(dt);
227:   }
228: 
229:   syncCamera(dt) {
230:     const bobAmt = clamp(this.speed / 7, 0, 1) * (this.grounded ? 1 : 0) * (1 - this.adsAmount * 0.8);
231:     const bx = Math.cos(this.bobPhase) * 0.035 * bobAmt;
232:     const by = Math.abs(Math.sin(this.bobPhase)) * 0.045 * bobAmt;
233:     const shake = this.cameraShake;
234:     const sx = (Math.random() - 0.5) * shake, sy = (Math.random() - 0.5) * shake;
235:     this.camera.position.set(
236:       this.pos.x + bx * Math.cos(this.yaw) + sx,
237:       this.pos.y + this.eyeHeight + by - this.landKick + sy,
238:       this.pos.z - bx * Math.sin(this.yaw)
239:     );
240:     this.camera.rotation.order = 'YXZ';
241:     this.camera.rotation.set(this.pitch + this.recoilPitch, this.yaw + this.recoilYaw, this.recoilRoll);
242:     const baseFov = this.baseFov;
243:     const targetFov = this.aiming ? baseFov / this.def.zoom : baseFov;
244:     if (Math.abs(this.camera.fov - targetFov) > 0.05) {
245:       this.camera.fov = damp(this.camera.fov, targetFov, 18, dt || 0.016);
246:       this.camera.updateProjectionMatrix();
247:     }
248:   }
249: 
250:   updateCameraShake(dt) {
251:     this.cameraShake = damp(this.cameraShake, 0, 10, dt);
252:     this.camera.rotation.set(this.pitch, this.yaw, this.recoilRoll);
253:     this.camera.position.y = damp(this.camera.position.y, this.pos.y + 0.4, 8, dt);
254:   }
255: 
256:   updateViewModel(dt) {
257:     if (!this.gunRoot) return;
258:     const target = new THREE.Vector3().copy(this.gunBasePos).lerp(this.gunAdsPos, this.adsAmount);
259:     const sway = clamp(this.speed / 7, 0, 1) * (1 - this.adsAmount * 0.85);
260:     target.x += Math.cos(this.bobPhase) * 0.012 * sway;
261:     target.y += Math.sin(this.bobPhase * 2) * 0.012 * sway;
262:     this.weaponKick = damp(this.weaponKick, 0, 12, dt);
263:     this.weaponRoll = damp(this.weaponRoll, 0, 10, dt);
264:     target.z += this.weaponKick * 0.12;
265:     this.gunRoot.position.lerp(target, 1 - Math.exp(-18 * dt));
266:     this.gunRoot.rotation.x = 0.01 - this.weaponKick * 0.22 + (1 - this.adsAmount) * 0.04;
267:     this.gunRoot.rotation.y = 0.03 * (1 - this.adsAmount);
268:     this.gunRoot.rotation.z = this.weaponRoll;
269:     if (this.reloadTimer > 0) {
270:       const total = this.def.reload;
271:       const k = 1 - this.reloadTimer / total;
272:       const dip = Math.sin(k * Math.PI);
273:       this.gunRoot.position.y -= dip * 0.25;
274:       this.gunRoot.rotation.x -= dip * 0.5;
275:       this.gunRoot.rotation.z += dip * 0.4;
276:     }
277:     if (this.switchTimer > 0) {
278:       const k = this.switchTimer / 0.28;
279:       this.gunRoot.position.y -= k * 0.35;
280:     }
281:   }
282: 
283:   updateWeapon(dt, input) {
284:     const w = this.weapon;
285:     this.fireTimer = Math.max(0, this.fireTimer - dt);
286:     this.switchTimer = Math.max(0, this.switchTimer - dt);
287:     this.spreadHeat = Math.max(0, this.spreadHeat - dt * 2.6);
288:     if (this.reloadTimer > 0) {
289:       this.reloadTimer -= dt;
290:       if (this.reloadTimer <= 0) this.finishReload();
291:       return;
292:     }
293:     if (this.switchTimer > 0) return;
294:     if (this.mode !== 'fps') return;
295:     if (input.firing && this.fireTimer <= 0) {
296:       if (w.def.auto || !this.triggerHeld) {
297:         this.tryFire();
298:       }
299:     }
300:     this.triggerHeld = input.firing;
301:   }
302: 
303:   tryFire() {
304:     const w = this.weapon, def = w.def;
305:     if (!this.alive) return;
306:     if (w.mag <= 0) {
307:       audio.empty();
308:       this.fireTimer = 0.25;
309:       this.game.hud?.flashAmmo();
310:       return;
311:     }
312:     w.mag--;
313:     this.fireTimer = 60 / def.rpm;
314:     this.shots++;
315:     this.weaponKick = 1;
316:     this.weaponRoll = rand(-0.04, 0.04);
317:     this.spreadHeat = clamp(this.spreadHeat + 0.22, 0, 2.6);
318:     const spread = this.currentSpread();
319:     for (let p = 0; p < def.pellets; p++) {
320:       const dir = this.camera.getWorldDirection(new THREE.Vector3());
321:       const right = new THREE.Vector3().crossVectors(dir, new THREE.Vector3(0, 1, 0)).normalize();
322:       const up = new THREE.Vector3().crossVectors(right, dir).normalize();
323:       const a = rand(0, Math.PI * 2), r = Math.tan(deg(spread)) * Math.sqrt(Math.random());
324:       dir.addScaledVector(right, Math.cos(a) * r).addScaledVector(up, Math.sin(a) * r).normalize();
325:       const origin = this.camera.position.clone();
326:       const hit = this.game.castShot(origin, dir, def.range, this);
327:       const end = hit.point;
328:       const muzzleWorld = this.getMuzzleWorld();
329:       this.game.effects.tracer(muzzleWorld, end, def.id === 'longshot' ? 0xbfe4ff : 0xffc06a);
330:       if (hit.bot) {
331:         const dist = hit.distance;
332:         let dmg = def.dmg;
333:         if (def.pellets > 1) dmg *= clamp(1 - dist / (def.range * 1.2), 0.25, 1);
334:         if (def.falloff && dist > def.falloff[0]) {
335:           const t = clamp((dist - def.falloff[0]) / (def.falloff[1] - def.falloff[0]), 0, 1);
336:           dmg *= lerp(1, def.falloff[2], t);
337:         }
338:         if (hit.zone === 'head') dmg *= 2.1;
339:         else if (hit.zone === 'leg') dmg *= 0.8;
340:         this.hits++;
341:         if (hit.zone === 'head') this.headshots++;
342:         this.game.damageBot(hit.bot, Math.round(dmg), this, hit.point, hit.zone === 'head', def);
343:         this.game.effects.impact(hit.point, hit.normal, '#ffca7a', true);
344:         audio.hit(hit.zone === 'head');
345:       } else {
346:         this.game.effects.impact(hit.point, hit.normal, '#ffd08a', false);
347:       }
348:     }
349:     this.recoilPitch += deg(def.recoil * 0.32) * (1 - this.adsAmount * 0.38);
350:     this.recoilYaw += rand(-1, 1) * deg(def.recoil * 0.1) * (1 - this.adsAmount * 0.5);
351:     this.recoilRoll += rand(-1, 1) * deg(0.35);
352:     this.cameraShake = Math.max(this.cameraShake, def.recoil * 0.006);
353:     const muzzleWorld = this.getMuzzleWorld();
354:     this.game.effects.muzzle(muzzleWorld, '#ffd08a', def.pellets > 5 ? 1.6 : 1);
355:     audio.shot(def.model, 0);
356:     this.game.onShot?.();
357:     if (w.mag === 0) this.startReload();
358:     this.game.hud?.updateAmmo();
359:   }
360: 
361:   currentSpread() {
362:     const def = this.def;
363:     let s = def.spread;
364:     const move = clamp(this.speed / 7, 0, 1);
365:     s += move * (def.moveSpread || 1) * 2.2;
366:     s += this.spreadHeat * 0.55;
367:     if (this.aiming) s = lerp(s, def.adsSpread, this.adsAmount) * 0.5;
368:     if (this.crouching) s *= 0.72;
369:     return s;
370:   }
371: 
372:   getMuzzleWorld() {
373:     const forward = this.camera.getWorldDirection(new THREE.Vector3());
374:     const right = new THREE.Vector3().crossVectors(forward, new THREE.Vector3(0, 1, 0)).normalize();
375:     return this.camera.position.clone().addScaledVector(forward, 0.75 + this.adsAmount * 0.2).addScaledVector(right, 0.18 * (1 - this.adsAmount)).add(new THREE.Vector3(0, -0.1, 0));
376:   }
377: 
378:   startReload() {
379:     const w = this.weapon, def = w.def;
380:     if (this.reloadTimer > 0 || w.mag >= def.mag || w.reserve <= 0) return;
381:     this.reloadTimer = def.reload;
382:     audio.reload();
383:     this.game.hud?.startReload(def.reload);
384:   }
385:   finishReload() {
386:     const w = this.weapon, def = w.def;
387:     const need = def.mag - w.mag;
388:     const take = this.game.mode.infiniteAmmo ? need : Math.min(need, w.reserve);
389:     w.mag += take;
390:     if (!this.game.mode.infiniteAmmo) w.reserve -= take;
391:     this.game.hud?.updateAmmo();
392:   }
393: 
394:   jump() {
395:     if (!this.alive || this.mode !== 'fps') return;
396:     if (this.grounded) {
397:       this.vel.y = 6.7;
398:       this.grounded = false;
399:       this.landKick = 0.015;
400:     }
401:   }
402: 
403:   heal(amount = 50) {
404:     if (!this.alive) return false;
405:     if (this.medkits <= 0) return false;
406:     if (this.health >= 100) return false;
407:     this.medkits--;
408:     this.health = Math.min(100, this.health + amount);
409:     audio.heal();
410:     this.game.hud?.updateVitals();
411:     this.game.hud?.toast('MEDKIT USED', '+50 HEALTH');
412:     return true;
413:   }
414:   useShield(amount = 50) {
415:     if (!this.alive) return false;
416:     if (this.shields <= 0) return false;
417:     if (this.shield >= this.maxShield) return false;
418:     this.shields--;
419:     this.shield = Math.min(this.maxShield, this.shield + amount);
420:     audio.shield();
421:     this.game.hud?.updateVitals();
422:     this.game.hud?.toast('SHIELD CELL', '+50 ARMOR');
423:     return true;
424:   }
425: 
426:   takeDamage(amount, source, point = null) {
427:     if (!this.alive || this.game.godMode) return;
428:     this.lastDamageTime = this.game.time;
429:     this.regenTimer = 0;
430:     if (this.shield > 0) {
431:       const absorbed = Math.min(this.shield, amount * 0.66);
432:       this.shield -= absorbed;
433:       amount -= absorbed;
434:       this.game.hud?.hitFlash(0.3);
435:     }
436:     this.health -= amount;
437:     this.cameraShake = 0.03;
438:     audio.hit(false);
439:     this.game.hud?.damageIndicator(source ? source.pos : null);
440:     this.game.hud?.updateVitals();
441:     this.game.hud?.hitFlash(0.75);
442:     if (this.health <= 0) {
443:       this.health = 0;
444:       this.die(source);
445:     }
446:   }
447: 
448:   die(source) {
449:     if (!this.alive) return;
450:     this.alive = false;
451:     this.mode = 'dead';
452:     this.adsAmount = 0; this.aiming = false;
453:     this.game.onPlayerDeath?.(source);
454:   }
455: 
456:   resetForRespawn(x, z) {
457:     this.alive = true;
458:     this.health = 100;
459:     this.shield = this.game.mode.armor || 0;
460:     this.pos.set(x, this.world.heightAt(x, z) + 0.05, z);
461:     this.vel.set(0, 0, 0);
462:     this.mode = 'fps';
463:     this.weapons.forEach(w => { w.mag = w.def.mag; w.reserve = w.def.reserve * (this.game.mode.startAmmo || 1); });
464:     this.equip(0, true);
465:     this.medkits = 2; this.shields = 1;
466:   }
467: }

