import fs from 'node:fs';

const wait = ms => new Promise(r => setTimeout(r, ms));
const target = await fetch('http://127.0.0.1:9222/json/new?about:blank', { method: 'PUT' }).then(r => r.json());
const ws = new WebSocket(target.webSocketDebuggerUrl);
const pending = new Map();
let nextId = 0;
let events = [];

function send(method, params = {}) {
  return new Promise((resolve, reject) => {
    const id = ++nextId;
    pending.set(id, { resolve, reject });
    ws.send(JSON.stringify({ id, method, params }));
  });
}

await new Promise((resolve, reject) => {
  ws.addEventListener('open', resolve, { once: true });
  ws.addEventListener('error', reject, { once: true });
});
ws.addEventListener('message', ev => {
  const msg = JSON.parse(ev.data);
  if (msg.id && pending.has(msg.id)) {
    const p = pending.get(msg.id);
    pending.delete(msg.id);
    if (msg.error) p.reject(new Error(JSON.stringify(msg.error)));
    else p.resolve(msg.result);
    return;
  }
  if (msg.method === 'Runtime.consoleAPICalled') {
    const text = msg.params.args.map(a => a.value ?? a.description ?? '').join(' ');
    events.push({ type: 'console.' + msg.params.type, text });
  } else if (msg.method === 'Runtime.exceptionThrown') {
    const d = msg.params.exceptionDetails;
    events.push({ type: 'exception', text: `${d.text} ${d.exception?.description || ''} @${d.url}:${d.lineNumber}` });
  } else if (msg.method === 'Log.entryAdded') {
    events.push({ type: 'log.' + msg.params.entry.level, text: msg.params.entry.text + ' ' + (msg.params.entry.url || '') });
  }
});

await send('Page.enable');
await send('Runtime.enable');
await send('Log.enable');
await send('Network.enable');
await send('Network.setCacheDisabled', { cacheDisabled: true });

const evalJS = async expression => {
  const r = await send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true });
  if (r.exceptionDetails) return { error: r.exceptionDetails.text + ' ' + (r.exceptionDetails.exception?.description || '') };
  return r.result.value;
};

async function shot(name) {
  const r = await send('Page.captureScreenshot', { format: 'jpeg', quality: 78, fromSurface: true });
  fs.writeFileSync('/tmp/opencode/shots/' + name, Buffer.from(r.data, 'base64'));
}

async function load(width, height, mobile, touch) {
  events = [];
  await send('Emulation.setDeviceMetricsOverride', { width, height, deviceScaleFactor: 1, mobile });
  await send('Emulation.setTouchEmulationEnabled', { enabled: touch, maxTouchPoints: touch ? 5 : 0 });
  await send('Page.navigate', { url: 'http://127.0.0.1:8123/?t=' + Date.now() });
  await wait(4600);
}
const key = (type, code) => send('Input.dispatchKeyEvent', { type, code, key: code, windowsVirtualKeyCode: 0 });

const report = {};

/* ---------------- desktop run ---------------- */
await load(1280, 800, false, false);
report.lobby = await evalJS(`(() => ({
  loading: getComputedStyle(document.getElementById('loading')).display,
  lobbyHidden: document.getElementById('lobby').classList.contains('hidden'),
  hasApp: !!window.blaze,
  name: window.blaze?.profile?.name,
  mapCards: document.querySelectorAll('#map-strip .map-mini').length,
  charItems: document.querySelectorAll('#char-items .char-item').length,
  weaponRows: document.querySelectorAll('#weapon-list .weapon-row').length,
  overflowX: document.documentElement.scrollWidth - document.documentElement.clientWidth,
  webgl2: !!document.createElement('canvas').getContext('webgl2')
}))()`);
await shot('d-lobby.jpg');

await evalJS(`document.getElementById('btn-play').click()`);
await wait(5600);
report.matchStart = await evalJS(`(() => {
  const g = window.blaze?.game;
  if (!g) return { noGame: true };
  g.introTimer = 0; g.phase = 'drop'; g.landDrop();
  document.getElementById('lock-hint')?.classList.add('hidden');
  return { phase: g.phase, dropDone: g.dropDone, pos: g.player.pos.toArray().map(v => +v.toFixed(1)),
    bots: g.bots?.bots.length, alive: g.bots?.aliveCount, hp: g.player.health,
    hudHidden: document.getElementById('hud').classList.contains('hidden'), mode: g.mode.id };
})()`);

// movement: hold W
await wait(900);
const beforeMove = await evalJS(`(() => { const p = window.blaze.game.player; return p.pos.toArray().map(v => +v.toFixed(2)); })()`);
await key('keyDown', 'KeyW');
await wait(1000);
await key('keyUp', 'KeyW');
await wait(200);
const afterMove = await evalJS(`(() => { const p = window.blaze.game.player; return { pos: p.pos.toArray().map(v => +v.toFixed(2)), speed: +p.speed.toFixed(2), grounded: p.grounded }; })()`);
report.movement = { beforeMove, afterMove, distance: Math.hypot(afterMove.pos[0] - beforeMove[0], afterMove.pos[2] - beforeMove[2]).toFixed(2) };

// jump
await key('keyDown', 'Space'); await key('keyUp', 'Space');
await wait(200);
report.jump = await evalJS(`(() => { const p = window.blaze.game.player; return { y: +p.pos.y.toFixed(2), vy: +p.vel.y.toFixed(2) }; })()`);

// shooting via simulated pointer lock + mouse events
const ammoBefore = await evalJS(`(() => { const g = window.blaze.game; return { mag: g.player.weapon.mag, shots: g.player.shots }; })()`);
await evalJS(`(() => { const { input } = window.blaze; input.mouse.locked = true; document.getElementById('stage').dispatchEvent(new MouseEvent('mousedown', { button: 0, bubbles: true })); return true; })()`);
await wait(700);
await evalJS(`(() => { window.dispatchEvent(new MouseEvent('mouseup', { button: 0, bubbles: true })); return true; })()`);
await wait(300);
const ammoAfter = await evalJS(`(() => { const g = window.blaze.game; return { mag: g.player.weapon.mag, shots: g.player.shots, reserve: g.player.weapon.reserve, hudMag: document.getElementById('ammo-mag').textContent, firing: window.blaze.input.firing }; })()`);
report.shooting = { before: ammoBefore, after: ammoAfter };

// reload
await key('keyDown', 'KeyR'); await key('keyUp', 'KeyR');
report.reload = await evalJS(`(() => { const p = window.blaze.game.player; return { reloadTimer: +p.reloadTimer.toFixed(2), trackActive: document.getElementById('reload-track').classList.contains('active') }; })()`);
await wait(2600);
report.reloadDone = await evalJS(`(() => { const p = window.blaze.game.player; return { mag: p.weapon.mag, reloadTimer: +p.reloadTimer.toFixed(2) }; })()`);

// scoreboard
await key('keyDown', 'Tab');
await wait(350);
report.scoreboardOpen = await evalJS(`(() => ({ hidden: document.getElementById('scoreboard').classList.contains('hidden'), rows: document.querySelectorAll('#sb-rows .sb-row').length, alive: document.getElementById('sb-alive').textContent }))()`);
await shot('d-scoreboard.jpg');
await key('keyUp', 'Tab');
await wait(250);
report.scoreboardClosed = await evalJS(`document.getElementById('scoreboard').classList.contains('hidden')`);

// pause
await key('keyDown', 'Escape'); await key('keyUp', 'Escape');
await wait(350);
report.pause = await evalJS(`(() => ({ paused: window.blaze.game.paused, overlayHidden: document.getElementById('pause').classList.contains('hidden'), inputEnabled: window.blaze.input.enabled }))()`);
await shot('d-pause.jpg');

// settings from pause
await evalJS(`document.getElementById('btn-pause-settings').click()`);
await wait(350);
report.pauseSettings = await evalJS(`(() => ({ modalHidden: document.getElementById('modal').classList.contains('hidden'), hasSens: !!document.getElementById('set-sens'), qualityButtons: document.querySelectorAll('#set-quality button').length }))()`);
await shot('d-settings.jpg');
await evalJS(`document.getElementById('set-apply').click()`);
await wait(300);
report.settingsClosed = await evalJS(`(() => ({ modalHidden: document.getElementById('modal').classList.contains('hidden'), paused: window.blaze.game.paused, inputEnabled: window.blaze.input.enabled }))()`);

// resume via pause menu
await evalJS(`(() => { const g = window.blaze.game; g.pause(); return true; })()`);
await wait(200);
await evalJS(`document.getElementById('btn-resume').click()`);
await wait(250);
report.resumed = await evalJS(`(() => ({ paused: window.blaze.game.paused, pauseHidden: document.getElementById('pause').classList.contains('hidden'), inputEnabled: window.blaze.input.enabled }))()`);

// results flow
await evalJS(`(() => { const g = window.blaze.game; g.endMatch(true, 'last'); return true; })()`);
await wait(1400);
report.results = await evalJS(`(() => ({
  resultsHidden: document.getElementById('results').classList.contains('hidden'),
  hudHidden: document.getElementById('hud').classList.contains('hidden'),
  title: document.getElementById('result-title').textContent,
  place: document.getElementById('result-place').textContent.trim().replace(/\\s+/g, ' '),
  kills: document.getElementById('rs-kills').textContent,
  time: document.getElementById('rs-time').textContent,
  coins: document.getElementById('reward-coins').textContent,
  profileCoins: window.blaze.profile.coins,
  over: window.blaze.game?.over
}))()`);
await shot('d-results.jpg');

// back to lobby
await evalJS(`document.getElementById('btn-lobby').click()`);
await wait(600);
report.backToLobby = await evalJS(`(() => ({
  hasGame: !!window.blaze.game,
  lobbyHidden: document.getElementById('lobby').classList.contains('hidden'),
  resultsHidden: document.getElementById('results').classList.contains('hidden'),
  hudHidden: document.getElementById('hud').classList.contains('hidden'),
  over: window.blaze.game?.over ?? null
}))()`);

report.desktopEvents = events.slice();

/* ---------------- mobile run ---------------- */
await load(390, 844, true, true);
report.mobileLobby = await evalJS(`(() => {
  const b = document.body;
  return {
    width: innerWidth, height: innerHeight,
    overflowX: document.documentElement.scrollWidth - document.documentElement.clientWidth,
    isTouch: window.blaze?.input?.isTouch,
    touchUiHidden: document.getElementById('touch-ui')?.classList.contains('hidden'),
    playVisible: !!document.getElementById('btn-play')?.offsetParent,
    playRect: (() => { const r = document.getElementById('btn-play')?.getBoundingClientRect(); return r ? [Math.round(r.x), Math.round(r.y), Math.round(r.width), Math.round(r.height)] : null; })(),
    controlRects: [...document.querySelectorAll('.topbar,.dock,.play-panel,.profile-card')].map(el => ({ cls: el.className, right: Math.round(el.getBoundingClientRect().right), w: Math.round(el.getBoundingClientRect().width) }))
  };
})()`);
await shot('m-lobby.jpg');

await evalJS(`document.getElementById('btn-play').click()`);
await wait(5600);
report.mobileMatch = await evalJS(`(() => {
  const g = window.blaze?.game;
  if (!g) return { noGame: true };
  g.introTimer = 0; g.phase = 'drop'; g.landDrop();
  document.getElementById('lock-hint')?.classList.add('hidden');
  return {
    touch: window.blaze.input.isTouch,
    touchUiHidden: document.getElementById('touch-ui').classList.contains('hidden'),
    stickVisible: document.getElementById('stick-zone').getBoundingClientRect().width > 0,
    fireVisible: document.getElementById('t-fire').getBoundingClientRect().width > 0,
    lookZone: !!document.getElementById('look-zone'),
    overflowX: document.documentElement.scrollWidth - document.documentElement.clientWidth,
    phase: g.phase, hp: g.player.health, bots: g.bots?.bots.length
  };
})()`);
await wait(1200);
await shot('m-match.jpg');

// touch look drag
const yawBefore = await evalJS(`+window.blaze.game.player.yaw.toFixed(3)`);
await send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [{ x: 300, y: 360, id: 1 }] });
await send('Input.dispatchTouchEvent', { type: 'touchMove', touchPoints: [{ x: 250, y: 360, id: 1 }] });
await send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
await wait(300);
report.mobileLook = await evalJS(`({ yawBefore: ${yawBefore}, yawAfter: +window.blaze.game.player.yaw.toFixed(3) })`);

// touch joystick drag
const posBefore = await evalJS(`window.blaze.game.player.pos.toArray().map(v => +v.toFixed(2))`);
await send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [{ x: 70, y: 700, id: 2 }] });
await wait(100);
await send('Input.dispatchTouchEvent', { type: 'touchMove', touchPoints: [{ x: 70, y: 650, id: 2 }] });
await wait(900);
await send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
await wait(200);
report.mobileMove = await evalJS(`(() => ({ before: ${JSON.stringify(posBefore)}, after: window.blaze.game.player.pos.toArray().map(v => +v.toFixed(2)), joy: window.blaze.input.joy }))()`);

report.mobileEvents = events.filter(e => e.type.startsWith('exception') || e.type.includes('error') || e.type === 'log.error' || e.type === 'log.warning');

console.log(JSON.stringify(report, null, 2));
await send('Page.close');
ws.close();

