import fs from 'node:fs';

const wait = ms => new Promise(r => setTimeout(r, ms));
const target = await fetch('http://127.0.0.1:9222/json/new?about:blank', { method: 'PUT' }).then(r => r.json());
const ws = new WebSocket(target.webSocketDebuggerUrl);
const pending = new Map();
let nextId = 0;
let events = [];

function send(method, params = {}) {
  return new Promise((resolve, reject) => {
    const id = ++nextId;
    pending.set(id, { resolve, reject, method });
    ws.send(JSON.stringify({ id, method, params }));
  });
}
await new Promise((resolve, reject) => {
  ws.addEventListener('open', resolve, { once: true });
  ws.addEventListener('error', reject, { once: true });
});
ws.addEventListener('message', ev => {
  const msg = JSON.parse(ev.data);
  if (msg.id && pending.has(msg.id)) {
    const p = pending.get(msg.id); pending.delete(msg.id);
    if (msg.error) p.reject(new Error(p.method + ' ' + JSON.stringify(msg.error)));
    else p.resolve(msg.result);
    return;
  }
  if (msg.method === 'Runtime.consoleAPICalled') {
    events.push({ type: 'console.' + msg.params.type, text: msg.params.args.map(a => a.value ?? a.description ?? '').join(' ') });
  } else if (msg.method === 'Runtime.exceptionThrown') {
    const d = msg.params.exceptionDetails;
    events.push({ type: 'exception', text: `${d.text} ${d.exception?.description || ''} @${d.url}:${d.lineNumber}` });
  } else if (msg.method === 'Log.entryAdded') {
    events.push({ type: 'log.' + msg.params.entry.level, text: msg.params.entry.text });
  }
});
await send('Page.enable');
await send('Runtime.enable');
await send('Log.enable');
await send('Network.enable');
await send('Network.setCacheDisabled', { cacheDisabled: true });

const evalJS = async expression => {
  const r = await send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true });
  if (r.exceptionDetails) return { error: r.exceptionDetails.text + ' ' + (r.exceptionDetails.exception?.description || '') };
  return r.result.value;
};
const shot = async name => {
  const r = await send('Page.captureScreenshot', { format: 'jpeg', quality: 78, fromSurface: true });
  fs.writeFileSync('/tmp/opencode/shots/' + name, Buffer.from(r.data, 'base64'));
};
const touch = (type, points) => send('Input.dispatchTouchEvent', { type, touchPoints: points });

const report = {};

/* desktop: verify movement, reload, and no pointer-lock exceptions */
await send('Emulation.setDeviceMetricsOverride', { width: 1280, height: 800, deviceScaleFactor: 1, mobile: false });
await send('Emulation.setTouchEmulationEnabled', { enabled: false, maxTouchPoints: 1 });
await send('Page.navigate', { url: 'http://127.0.0.1:8123/?t=' + Date.now() });
await wait(3200);
report.boot = await evalJS(`({ loading: getComputedStyle(document.getElementById('loading')).display, hasApp: !!window.blaze, isTouch: window.blaze?.input?.isTouch })`);

await evalJS(`document.getElementById('btn-play').click()`);
await wait(5400);
await evalJS(`(() => { const g = window.blaze.game; if (!g) return 'no game'; g.introTimer = 0; g.phase = 'drop'; g.landDrop(); document.getElementById('lock-hint')?.classList.add('hidden'); return 'ok'; })()`);
await wait(700);

const p0 = await evalJS(`window.blaze.game.player.pos.toArray().map(v => +v.toFixed(2))`);
await send('Input.dispatchKeyEvent', { type: 'keyDown', code: 'KeyW', key: 'w' });
await wait(1200);
await send('Input.dispatchKeyEvent', { type: 'keyUp', code: 'KeyW', key: 'w' });
await wait(150);
const p1 = await evalJS(`window.blaze.game.player.pos.toArray().map(v => +v.toFixed(2))`);
report.desktopMove = { from: p0, to: p1, dist: +Math.hypot(p1[0] - p0[0], p1[2] - p0[2]).toFixed(2), fps: document.getElementById('fps-hud')?.textContent };

// fire then reload fully
await evalJS(`(() => { const g = window.blaze.game; g.player.weapon.mag = 10; g.player.startReload(); return g.player.weapon.mag; })()`);
report.reloadStart = await evalJS(`({ timer: +window.blaze.game.player.reloadTimer.toFixed(2), track: document.getElementById('reload-track').classList.contains('active') })`);
await wait(3400);
report.reloadEnd = await evalJS(`({ mag: window.blaze.game.player.weapon.mag, timer: +window.blaze.game.player.reloadTimer.toFixed(2), reloading: window.blaze.game.player.reloadTimer > 0 })`);

// walk back to lobby before mobile pass
await evalJS(`window.blaze.game.leaveMatch()`);
await wait(500);

/* mobile: touch look, fire, ads, jump, reload */
await send('Emulation.setDeviceMetricsOverride', { width: 390, height: 844, deviceScaleFactor: 1, mobile: true });
await send('Emulation.setTouchEmulationEnabled', { enabled: true, maxTouchPoints: 5 });
await send('Page.navigate', { url: 'http://127.0.0.1:8123/?t=' + Date.now() });
