import fs from 'node:fs';

const wait = ms => new Promise(r => setTimeout(r, ms));
const target = await fetch('http://127.0.0.1:9222/json/new?about:blank', { method: 'PUT' }).then(r => r.json());
const ws = new WebSocket(target.webSocketDebuggerUrl);
const pending = new Map();
let nextId = 0;
let events = [];

function send(method, params = {}) {
  return new Promise((resolve, reject) => {
    const id = ++nextId;
    pending.set(id, { resolve, reject, method });
    ws.send(JSON.stringify({ id, method, params }));
  });
}
await new Promise((resolve, reject) => {
  ws.addEventListener('open', resolve, { once: true });
  ws.addEventListener('error', reject, { once: true });
});
ws.addEventListener('message', ev => {
  const msg = JSON.parse(ev.data);
  if (msg.id && pending.has(msg.id)) {
    const p = pending.get(msg.id); pending.delete(msg.id);
    if (msg.error) p.reject(new Error(p.method + ' ' + JSON.stringify(msg.error)));
    else p.resolve(msg.result);
    return;
  }
  if (msg.method === 'Runtime.consoleAPICalled') {
    events.push({ type: 'console.' + msg.params.type, text: msg.params.args.map(a => a.value ?? a.description ?? '').join(' ') });
  } else if (msg.method === 'Runtime.exceptionThrown') {
    const d = msg.params.exceptionDetails;
    events.push({ type: 'exception', text: `${d.text} ${d.exception?.description || ''} @${d.url}:${d.lineNumber}` });
  } else if (msg.method === 'Log.entryAdded') {
    events.push({ type: 'log.' + msg.params.entry.level, text: msg.params.entry.text });
  }
});
await send('Page.enable');
await send('Runtime.enable');
await send('Log.enable');
await send('Network.enable');
await send('Network.setCacheDisabled', { cacheDisabled: true });

const evalJS = async expression => {
  const r = await send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true });
  if (r.exceptionDetails) return { error: r.exceptionDetails.text + ' ' + (r.exceptionDetails.exception?.description || '') };
  return r.result.value;
};
const shot = async name => {
  const r = await send('Page.captureScreenshot', { format: 'jpeg', quality: 78, fromSurface: true });
  fs.writeFileSync('/tmp/opencode/shots/' + name, Buffer.from(r.data, 'base64'));
};
const touch = (type, points) => send('Input.dispatchTouchEvent', { type, touchPoints: points });

const report = {};

/* ---------- desktop ---------- */
await send('Emulation.setDeviceMetricsOverride', { width: 1280, height: 800, deviceScaleFactor: 1, mobile: false });
await send('Emulation.setTouchEmulationEnabled', { enabled: false, maxTouchPoints: 1 });
await send('Page.navigate', { url: 'http://127.0.0.1:8123/?t=' + Date.now() });
await wait: undefined;
await wait(4200);
report.desktop = await evalJS(`(() => ({
  loading: getComputedStyle(document.getElementById('loading')).display,
  bodyTouch: document.body.classList.contains('touch'),
  lookPointer: getComputedStyle(document.getElementById('look-zone')).pointerEvents,
  isTouch: window.blaze?.input?.isTouch,
  lobby: !document.getElementById('lobby').classList.contains('hidden')
}))()`);
// click canvas (should attempt pointer lock but stay silent)
await evalJS(`document.getElementById('stage').dispatchEvent(new MouseEvent('mousedown', { button: 0, bubbles: true }))`);
await wait(300);

/* ---------- mobile ---------- */
events = [];
await send('Emulation.setDeviceMetricsOverride', { width: 390, height: 844, deviceScaleFactor: 1, mobile: true });
await send('Emulation.setTouchEmulationEnabled', { enabled: true, maxTouchPoints: 5 });
await send('Page.navigate', { url: 'http://127.0.0.1:8123/?t=' + Date.now() });
await wait(4300);
report.mobileLobby = await evalJS(`(() => ({
  loading: getComputedStyle(document.getElementById('loading')).display,
  bodyTouch: document.body.classList.contains('touch'),
  lookPointer: getComputedStyle(document.getElementById('look-zone')).pointerEvents,
  isTouch: window.blaze?.input?.isTouch,
  lobby: !document.getElementById('lobby').classList.contains('hidden'),
  overflow: document.documentElement.scrollWidth - document.documentElement.clientWidth
}))()`);
await shot('m3-lobby.jpg');

await evalJS(`document.getElementById('btn-play').click()`);
await wait(5600);
report.mobileMatch = await evalJS(`(() => {
  const g = window.blaze?.game; if (!g) return { noGame: true };
  g.introTimer = 0; g.phase = 'drop'; g.landDrop();
  document.getElementById('lock-hint')?.classList.add('hidden');
  const rect = sel => { const r = document.querySelector(sel).getBoundingClientRect(); return { l: Math.round(r.left), t: Math.round(r.top), r: Math.round(r.right), b: Math.round(r.bottom) }; };
  const overlap = (a, b) => a.l < b.r && a.r > b.l && a.t < b.b && a.b > b.t;
  const ammo = rect('.ammo-panel');
  const names = ['#t-fire', '#t-ads', '#t-jump', '#t-crouch', '#t-reload', '#t-swap', '#t-menu'];
  const overlapList = names.filter(n => overlap(ammo, rect(n)));
  return {
    touchUi: !document.getElementById('touch-ui').classList.contains('hidden'),
    menuVisible: document.getElementById('t-menu').getBoundingClientRect().width > 0,
    ammo: ammo, buttons: Object.fromEntries(names.map(n => [n, rect(n)])), ammoOverlaps: overlapList,
    lookRect: (() => { const r = document.getElementById('look-zone').getBoundingClientRect(); return [Math.round(r.width), Math.round(r.height)]; })(),
    hudAlive: document.getElementById('hud-alive').textContent
  };
})()`);
await wait(800);
await shot('m3-match.jpg');

// ADS toggle state
const adsRect = await evalJS(`(() => { const r = document.getElementById('t-ads').getBoundingClientRect(); return { x: Math.round(r.x + r.width / 2), y: Math.round(r.y + r.height / 2) }; })()`);
await touch('touchStart', [{ x: adsRect.x, y: adsRect.y, id: 3 }]);
await touch('touchEnd', [{ x: adsRect.x, y: adsRect.y, id: 3 }]);
await wait(250);
report.adsOn = await evalJS(`({ aiming: window.blaze.input.aiming, on: document.getElementById('t-ads').classList.contains('on') })`);
await touch('touchStart', [{ x: adsRect.x, y: adsRect.y, id: 3 }]);
await touch('touchEnd', [{ x: adsRect.x, y: adsRect.y, id: 3 }]);
await wait(250);
report.adsOff = await evalJS(`({ aiming: window.blaze.input.aiming, on: document.getElementById('t-ads').classList.contains('on') })`);

// menu -> pause -> settings -> close -> resume
const menuRect = await evalJS(`(() => { const r = document.getElementById('t-menu').getBoundingClientRect(); return { x: Math.round(r.x + r.width / 2), y: Math.round(r.y + r.height / 2) }; })()`);
await touch('touchStart', [{ x: menuRect.x, y: menuRect.y, id: 4 }]);
await touch('touchEnd', [{ x: menuRect.x, y: menuRect.y, id: 4 }]);
await wait(400);
report.mobilePause = await evalJS(`({ paused: window.blaze.game.paused, pauseHidden: document.getElementById('pause').classList.contains('hidden'), touchHidden: document.getElementById('touch-ui').classList.contains('hidden') })`);
await shot('m3-pause.jpg');
await evalJS(`document.getElementById('btn-pause-settings').click()`);
await wait(400);
report.mobilePauseSettings = await evalJS(`({ modalHidden: document.getElementById('modal').classList.contains('hidden'), settings: !!document.getElementById('set-sens') })`);
await shot('m3-settings.jpg');
await evalJS(`document.getElementById('set-apply').click()`);
await wait(300);
report.mobileResume = await evalJS(`({ paused: window.blaze.game.paused, touchVisible: !document.getElementById('touch-ui').classList.contains('hidden'), input: window.blaze.input.enabled })`);

// touch look still works after resume
const yaw0 = await evalJS(`+window.blaze.game.player.yaw.toFixed(3)`);
await touch('touchStart', [{ x: 300, y: 380, id: 5 }]);
await touch('touchMove', [{ x: 200, y: 380, id: 5 }]);
await touch('touchEnd', [{ x: 200, y: 380, id: 5 }]);
await wait(250);
report.touchLookAfterResume = await evalJS(`({ yaw0: ${yaw0}, yaw1: +window.blaze.game.player.yaw.toFixed(3) })`);

report.errors = events.filter(e => e.type === 'exception' || e.type.endsWith('.error') || (e.type === 'log.warning' && !e.text.includes('AudioContext')));
console.log(JSON.stringify(report, null, 2));
await send('Page.close');
ws.close();

