import fs from 'node:fs';
const wait = ms => new Promise(r => setTimeout(r, ms));
const target = await fetch('http://127.0.0.1:9222/json/new?about:blank', { method: 'PUT' }).then(r => r.json());
const ws = new WebSocket(target.webSocketDebuggerUrl);
const pending = new Map(); let nextId = 0; const events = [];
function send(method, params = {}) { return new Promise((resolve, reject) => { const id = ++nextId; pending.set(id, { resolve, reject, method }); ws.send(JSON.stringify({ id, method, params })); }); }
await new Promise((resolve, reject) => { ws.addEventListener('open', resolve, { once: true }); ws.addEventListener('error', reject, { once: true }); });
ws.addEventListener('message', ev => { const msg = JSON.parse(ev.data); if (msg.id && pending.has(msg.id)) { const p = pending.get(msg.id); pending.delete(msg.id); if (msg.error) p.reject(new Error(p.method + ' ' + JSON.stringify(msg.error))); else p.resolve(msg.result); return; } if (msg.method === 'Runtime.exceptionThrown') { const d = msg.params.exceptionDetails; events.push(d.text + ' ' + (d.exception?.description || '')); } });
await send('Page.enable'); await send('Runtime.enable');
const evalJS = async expression => { const r = await send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true }); if (r.exceptionDetails) return { error: r.exceptionDetails.text }; return r.result.value; };
const shot = async name => { const r = await send('Page.captureScreenshot', { format: 'jpeg', quality: 80, fromSurface: true }); fs.writeFileSync('/tmp/opencode/shots/' + name, Buffer.from(r.data, 'base64')); };
const touch = (type, points) => send('Input.dispatchTouchEvent', { type, touchPoints: points });

async function run(name, width, height, mobile) {
  events.length = 0;
  await send('Emulation.setDeviceMetricsOverride', { width, height, deviceScaleFactor: 1, mobile });
  await send('Emulation.setTouchEmulationEnabled', { enabled: mobile, maxTouchPoints: mobile ? 5 : 1 });
  await send('Page.navigate', { url: 'http://127.0.0.1:8123/?t=' + Date.now() });
  await wait(4300);
  await evalJS(`document.getElementById('btn-play').click()`);
  await wait(5600);
  await evalJS(`(() => { const g = window.blaze.game; if (!g) return false; g.introTimer = 0; g.phase = 'drop'; g.landDrop(); document.getElementById('lock-hint')?.classList.add('hidden'); return true; })()`);
  await wait(1200);
  const data = await evalJS(`(() => {
    const sel = ['.vitals', '.quick-slots', '.ammo-panel', '#t-fire', '#t-ads', '#t-jump', '#t-crouch', '#t-reload', '#t-swap', '#t-menu', '.stick-base', '#drop-ui', '#objective', '#killfeed', '.hud-top', '#interact-hint', '#vehicle-hud'];
    const rect = s => { const el = document.querySelector(s); if (!el) return null; const r = el.getBoundingClientRect(); return { l: Math.round(r.left), t: Math.round(r.top), r: Math.round(r.right), b: Math.round(r.bottom), w: Math.round(r.width), h: Math.round(r.height) }; };
    const rects = Object.fromEntries(sel.map(s => [s, rect(s)]));
    const visible = s => { const el = document.querySelector(s); if (!el) return false; const cs = getComputedStyle(el); return cs.display !== 'none' && cs.visibility !== 'hidden' && !el.classList.contains('hidden'); };
    const overlap = (a, b) => a && b && a.l < b.r && a.r > b.l && a.t < b.b && a.b > b.t;
    const pairs = [];
    const keys = ['.vitals', '.quick-slots', '.ammo-panel', '#t-fire', '#t-ads', '#t-jump', '#t-crouch', '#t-reload', '#t-swap', '#t-menu'];
    for (let i = 0; i < keys.length; i++) for (let j = i + 1; j < keys.length; j++) if (overlap(rects[keys[i]], rects[keys[j]])) pairs.push(keys[i] + ' X ' + keys[j]);
    return { rects, pairs, visible: Object.fromEntries(sel.map(s => [s, visible(s)])), overflow: document.documentElement.scrollWidth - document.documentElement.clientWidth, alive: document.getElementById('hud-alive').textContent, touchUi: !document.getElementById('touch-ui').classList.contains('hidden') };
  })()`);
  await shot(name + '.jpg');
  return data;
}
const portrait = await run('m5-portrait', 390, 844, true);
const landscape = await run('m5-landscape', 844, 390, true);
console.log(JSON.stringify({ portrait, landscape, errors: events }, null, 2));
await send('Page.close'); ws.close();

