#hit-flash{position:absolute;inset:0;pointer-events:none;opacity:0;background:radial-gradient(ellipse at center,transparent 60%,rgba(255,60,20,.4));transition:opacity .12s}

.hud-bottom{position:absolute;left:18px;right:18px;bottom:calc(14px + var(--safe-b));display:flex;align-items:flex-end;justify-content:space-between;gap:16px}
.vitals{display:flex;align-items:flex-end;gap:9px;min-width:270px}
.vital-avatar{width:44px;height:48px;position:relative;background:linear-gradient(160deg,rgba(255,255,255,.1),rgba(0,0,0,.4));border:1px solid var(--line);display:grid;place-items:center;clip-path:polygon(0 0,100% 0,100% calc(100% - 9px),calc(100% - 9px) 100%,0 100%)}
.vital-avatar span{font-family:var(--num);font-size:25px;font-weight:700;color:#dfe8ef}
.vital-lvl{position:absolute;right:-5px;bottom:-5px;width:17px;height:17px;display:grid;place-items:center;background:var(--orange);color:#0b0e12;font-family:var(--num);font-size:8px;font-weight:700;font-style:normal;border-radius:50%}
.vital-main{flex:1;max-width:250px}
.vital-name{display:flex;align-items:center;gap:6px;margin-bottom:5px}
.vital-name b{font-size:10px;letter-spacing:.11em}
.vital-name span{font-size:6px;letter-spacing:.13em;color:var(--teal);border:1px solid rgba(37,221,195,.3);padding:1px 4px}
.bar{height:11px;position:relative;background:rgba(6,9,13,.72);border:1px solid rgba(255,255,255,.13);overflow:hidden;margin-bottom:4px}
.bar-fill{position:absolute;left:0;top:0;bottom:0;transition:width .15s ease;z-index:2}
.bar.hp .bar-fill{background:linear-gradient(90deg,#1fbd8d,#4fffc4)}
.bar.armor .bar-fill{background:linear-gradient(90deg,#1a7ba8,#40d2ff)}
.bar.armor{height:7px}
.bar span{position:absolute;right:5px;top:50%;transform:translateY(-50%);font-family:var(--num);font-size:9px;font-weight:700;z-index:3;text-shadow:0 1px 2px #000;color:#eaf6f1}
.bar.armor span{font-size:7px;color:#bceaff}
.bar-ghost{position:absolute;left:0;top:0;bottom:0;background:rgba(255,255,255,.45);z-index:1;transition:width .6s ease}
.bar.hp.low .bar-fill{background:linear-gradient(90deg,#d62b2b,#ff6b4a);animation:blink 1s infinite}
.quick-slots{display:flex;gap:5px;margin-bottom:2px;position:relative;z-index:3}
.quick{width:42px;height:42px;position:relative;display:grid;place-items:center;background:rgba(8,12,17,.7);border:1px solid var(--line);color:#c1ced8;transition:.15s;pointer-events:auto;clip-path:polygon(0 0,100% 0,100% calc(100% - 7px),calc(100% - 7px) 100%,0 100%)}
.quick:hover{background:rgba(255,255,255,.1)}
.quick:active{transform:scale(.95)}
.quick .icon{width:17px;height:17px;color:#8fd4ff}
.quick:nth-child(2) .icon{color:#7ef4dc}
.quick b{position:absolute;right:4px;bottom:2px;font-family:var(--num);font-size:10px}
.quick span{position:absolute;left:4px;top:2px;font-size:6px;color:var(--muted-2)}
.ammo-panel{min-width:190px;text-align:right;position:relative;padding-bottom:1px;z-index:3}
.ammo-top{display:flex;align-items:baseline;justify-content:flex-end;gap:6px;font-size:8px;letter-spacing:.13em;color:#bdc9d2;margin-bottom:-2px}
.ammo-top i{font-style:normal;font-size:6px;color:var(--orange);border:1px solid rgba(255,122,26,.3);padding:1px 4px}
.ammo-main{font-family:var(--num);line-height:.95;display:flex;align-items:baseline;justify-content:flex-end;gap:5px}
.ammo-main b{font-size:44px;font-weight:700;letter-spacing:.01em}
.ammo-main span{font-size:16px;color:var(--muted)}
.ammo-main span i{font-style:normal;font-size:15px;color:#c2ced8}

