import fs from 'node:fs';
const wait = ms => new Promise(r => setTimeout(r, ms));
const target = await fetch('http://127.0.0.1:9222/json/new?about:blank', { method: 'PUT' }).then(r => r.json());
const ws = new WebSocket(target.webSocketDebuggerUrl);
const pending = new Map(); let nextId = 0; const events = [];
function send(method, params = {}) { return new Promise((resolve, reject) => { const id = ++nextId; pending.set(id, { resolve, reject, method }); ws.send(JSON.stringify({ id, method, params })); }); }
await new Promise((resolve, reject) => { ws.addEventListener('open', resolve, { once: true }); ws.addEventListener('error', reject, { once: true }); });
ws.addEventListener('message', ev => { const msg = JSON.parse(ev.data); if (msg.id && pending.has(msg.id)) { const p = pending.get(msg.id); pending.delete(msg.id); if (msg.error) p.reject(new Error(p.method + ' ' + JSON.stringify(msg.error))); else p.resolve(msg.result); return; } if (msg.method === 'Runtime.consoleAPICalled') events.push('console.' + msg.params.type + ': ' + msg.params.args.map(a => a.value ?? '').join(' ')); if (msg.method === 'Runtime.exceptionThrown') { const d = msg.params.exceptionDetails; events.push('exception: ' + d.text + ' ' + (d.exception?.description || '')); } });
await send('Page.enable'); await send('Runtime.enable');
const evalJS = async expression => { const r = await send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true }); if (r.exceptionDetails) return { error: r.exceptionDetails.text + ' ' + (r.exceptionDetails.exception?.description || '') }; return r.result.value; };
const shot = async name => { const r = await send('Page.captureScreenshot', { format: 'jpeg', quality: 80, fromSurface: true }); fs.writeFileSync('/tmp/opencode/shots/' + name, Buffer.from(r.data, 'base64')); };

await send('Emulation.setDeviceMetricsOverride', { width: 1280, height: 800, deviceScaleFactor: 1, mobile: false });
await send('Emulation.setTouchEmulationEnabled', { enabled: false, maxTouchPoints: 1 });
await send('Page.navigate', { url: 'http://127.0.0.1:8123/?t=' + Date.now() });
await wait(4300);
const report = {};

// --- TDM ---
report.tdmSelect = await evalJS(`(() => { document.querySelector('.mode-card[data-mode="tdm"]').click(); return { mode: window.blaze.selectedMode, active: document.querySelector('.mode-card[data-mode="tdm"]').classList.contains('active'), detail: document.getElementById('mi-detail').textContent, sub: document.getElementById('deploy-sub').textContent }; })()`);
await evalJS(`document.getElementById('btn-play').click()`);
await wait(1800);
report.tdmMatch = await evalJS(`(() => { const g = window.blaze.game; if (!g) return { noGame: true }; document.getElementById('lock-hint')?.classList.add('hidden');
  return { mode: g.mode.id, phase: g.phase, dropDone: g.dropDone, score: g.bots.teamScores, bots: g.bots.bots.length, alive: g.bots.aliveCount, squad: document.getElementById('hud-squad').textContent, objScore: document.getElementById('obj-score').textContent.replace(/\\s+/g, ' ').trim(), scoreVisible: !document.getElementById('obj-score').classList.contains('hidden'), respawn: g.mode.respawn }; })()`);
await wait(1000);
await shot('d-tdm.jpg');

report.tdmDeath = await evalJS(`(() => { const g = window.blaze.game; g.player.takeDamage(500, null); return { alive: g.player.alive, respawnTimer: +g.respawnTimer.toFixed(1), deadClass: g.hud.root.classList.contains('dead') }; })()`);
await wait(300);
report.tdmRespawned = await evalJS(`(() => { const g = window.blaze.game; g.respawnPlayer(); return { alive: g.player.alive, hp: g.player.health, deadClass: g.hud.root.classList.contains('dead'), timer: +g.respawnTimer.toFixed(1) }; })()`);

// force score win
report.tdmScoreWin = await evalJS(`(() => { const g = window.blaze.game; g.bots.teamScores = [30, 7]; g.onTeamScore([30, 7]); return { over: g.over }; })()`);
await wait(1300);
report.tdmResults = await evalJS(`({ title: document.getElementById('result-title').textContent, place: document.getElementById('result-place').textContent.replace(/\\s+/g, ' ').trim(), resultsHidden: document.getElementById('results').classList.contains('hidden'), kicker: document.getElementById('result-kicker').textContent })`);
await shot('d-tdm-results.jpg');
await evalJS(`document.getElementById('btn-lobby').click()`);
await wait(500);

// --- training ---
await evalJS(`(() => { document.querySelector('.mode-card[data-mode="training"]').click(); document.getElementById('btn-play').click(); return true; })()`);
await wait(1800);
report.training = await evalJS(`(() => { const g = window.blaze.game; if (!g) return { noGame: true }; document.getElementById('lock-hint')?.classList.add('hidden');
  return { mode: g.mode.id, infinite: g.mode.infiniteAmmo, reserveHud: document.getElementById('ammo-reserve').textContent, phase: g.phase, dropDone: g.dropDone, armor: g.player.shield }; })()`);
report.trainingFire = await evalJS(`(() => { const g = window.blaze.game; const before = g.player.weapon.reserve; g.input.firing = true; return { before, mag: g.player.weapon.mag }; })()`);
await wait(500);
report.trainingFireAfter = await evalJS(`(() => { const g = window.blaze.game; g.input.firing = false; return { mag: g.player.weapon.mag, reserve: g.player.weapon.reserve, hudReserve: document.getElementById('ammo-reserve').textContent, shots: g.player.shots }; })()`);
await shot('d-training.jpg');
await evalJS(`document.getElementById('hud') && window.blaze.game.leaveMatch()`);
await wait(500);

// --- map selection ---
report.mapSelect = await evalJS(`(() => { const cards = [...document.querySelectorAll('#map-strip .map-mini')]; cards[1].click(); return { selected: window.blaze.selectedMap, active: cards[1].classList.contains('active'), miMap: document.getElementById('mi-map').textContent }; })()`);
await evalJS(`document.getElementById('btn-play').click()`);
await wait(2000);
report.mapMatch = await evalJS(`(() => { const g = window.blaze.game; if (!g) return { noGame: true }; return { mode: g.mode.id, map: g.map.id, worldMap: g.world.map.id, hudTarget: document.getElementById('drop-target').textContent }; })()`);
await shot('d-dune.jpg');

report.errors = events.filter(e => e.startsWith('exception'));
console.log(JSON.stringify(report, null, 2));
await send('Page.close'); ws.close();

