const ws = new WebSocket(target.webSocketDebuggerUrl);
const pending = new Map(); let nextId = 0; const events = [];
function send(method, params = {}) { return new Promise((resolve, reject) => { const id = ++nextId; pending.set(id, { resolve, reject, method }); ws.send(JSON.stringify({ id, method, params })); }); }
await new Promise((resolve, reject) => { ws.addEventListener('open', resolve, { once: true }); ws.addEventListener('error', reject, { once: true }); });
ws.addEventListener('message', ev => { const msg = JSON.parse(ev.data); if (msg.id && pending.has(msg.id)) { const p = pending.get(msg.id); pending.delete(msg.id); if (msg.error) p.reject(new Error(p.method + ' ' + JSON.stringify(msg.error))); else p.resolve(msg.result); return; } if (msg.method === 'Runtime.consoleAPICalled') events.push('console.' + msg.params.type + ': ' + msg.params.args.map(a => a.value ?? a.description ?? '').join(' ')); if (msg.method === 'Runtime.exceptionThrown') { const d = msg.params.exceptionDetails; events.push('exception: ' + d.text + ' ' + (d.exception?.description || '') + ' @' + d.url + ':' + d.lineNumber); } if (msg.method === 'Log.entryAdded') events.push('log.' + msg.params.entry.level + ': ' + msg.params.entry.text); });
await send('Page.enable'); await send('Runtime.enable'); await send('Log.enable');
await send('Page.bringToFront'); await send('Emulation.setFocusEmulationEnabled', { enabled: true });
