import fs from 'node:fs';
const wait = ms => new Promise(r => setTimeout(r, ms));
const target = await fetch('http://127.0.0.1:9222/json/new?about:blank', { method: 'PUT' }).then(r => r.json());
const ws = new WebSocket(target.webSocketDebuggerUrl);
const pending = new Map(); let nextId = 0; const events = [];
function send(method, params = {}) { return new Promise((resolve, reject) => { const id = ++nextId; pending.set(id, { resolve, reject, method }); ws.send(JSON.stringify({ id, method, params })); }); }
await new Promise((resolve, reject) => { ws.addEventListener('open', resolve, { once: true }); ws.addEventListener('error', reject, { once: true }); });
ws.addEventListener('message', ev => {
  const msg = JSON.parse(ev.data);
  if (msg.id && pending.has(msg.id)) { const p = pending.get(msg.id); pending.delete(msg.id); if (msg.error) p.reject(new Error(p.method + ' ' + JSON.stringify(msg.error))); else p.resolve(msg.result); return; }
  if (msg.method === 'Runtime.consoleAPICalled') events.push('console.' + msg.params.type + ': ' + msg.params.args.map(a => a.value ?? a.description ?? '').join(' '));
  if (msg.method === 'Runtime.exceptionThrown') { const d = msg.params.exceptionDetails; events.push('exception: ' + d.text + ' ' + (d.exception?.description || '') + ' @' + d.url + ':' + d.lineNumber); }
  if (msg.method === 'Log.entryAdded') events.push('log.' + msg.params.entry.level + ': ' + msg.params.entry.text);
});
await send('Page.enable'); await send('Runtime.enable'); await send('Log.enable');
await send('Network.enable'); await send('Network.setCacheDisabled', { cacheDisabled: true });
await send('Page.bringToFront'); await send('Emulation.setFocusEmulationEnabled', { enabled: true });
const evalJS = async expression => { const r = await send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true }); if (r.exceptionDetails) return { error: r.exceptionDetails.text + ' ' + (r.exceptionDetails.exception?.description || '') }; return r.result.value; };
const waitFor = async (expr, timeout = 15000) => { const t = Date.now(); while (Date.now() - t < timeout) { const v = await evalJS(expr); if (v) return v; await wait(200); } return null; };
const shot = async name => { const r = await send('Page.captureScreenshot', { format: 'jpeg', quality: 80, fromSurface: true }); fs.writeFileSync('/tmp/opencode/shots/' + name, Buffer.from(r.data, 'base64')); };
const key = async (type, code, k, vk) => send('Input.dispatchKeyEvent', { type, code, key: k, windowsVirtualKeyCode: vk, nativeVirtualKeyCode: vk });
const touch = (type, points) => send('Input.dispatchTouchEvent', { type, touchPoints: points });
const tapPoint = async (x, y, id = 31) => { await touch('touchStart', [{ x, y, id }]); await wait(60); await touch('touchEnd', [{ x, y, id }]); await wait(120); };
const report = {};

const navigate = async () => { await send('Page.navigate', { url: 'http://127.0.0.1:8123/?t=' + Date.now() }); await send('Page.bringToFront'); await wait(4500); };
const startMode = async mode => {
  await evalJS(`(() => { document.querySelector('.mode-card[data-mode="${mode}"]').click(); document.getElementById('btn-play').click(); return true; })()`);
  const ok = await waitFor(`(() => { const a = window.blaze; return !!(a && a.game && !a.starting); })()`);
  await wait(900);
  return ok;
