import fs from 'node:fs';
const wait = ms => new Promise(r => setTimeout(r, ms));
const target = await fetch('http://127.0.0.1:9222/json/new?about:blank', { method: 'PUT' }).then(r => r.json());
const ws = new WebSocket(target.webSocketDebuggerUrl);
const pending = new Map(); let nextId = 0; const events = [];
function send(method, params = {}) { return new Promise((resolve, reject) => { const id = ++nextId; pending.set(id, { resolve, reject, method }); ws.send(JSON.stringify({ id, method, params })); }); }
await new Promise((resolve, reject) => { ws.addEventListener('open', resolve, { once: true }); ws.addEventListener('error', reject, { once: true }); });
ws.addEventListener('message', ev => {
  const msg = JSON.parse(ev.data);
  if (msg.id && pending.has(msg.id)) { const p = pending.get(msg.id); pending.delete(msg.id); if (msg.error) p.reject(new Error(p.method + ' ' + JSON.stringify(msg.error))); else p.resolve(msg.result); return; }
  if (msg.method === 'Runtime.consoleAPICalled') events.push('console.' + msg.params.type + ': ' + msg.params.args.map(a => a.value ?? a.description ?? '').join(' '));
  if (msg.method === 'Runtime.exceptionThrown') { const d = msg.params.exceptionDetails; events.push('exception: ' + d.text + ' ' + (d.exception?.description || '')); }
  if (msg.method === 'Log.entryAdded') events.push('log.' + msg.params.entry.level + ': ' + msg.params.entry.text);
});
await send('Page.enable'); await send('Runtime.enable'); await send('Log.enable');
await send('Network.enable'); await send('Network.setCacheDisabled', { cacheDisabled: true });
await send('Page.bringToFront'); await send('Emulation.setFocusEmulationEnabled', { enabled: true });
const evalJS = async expression => { const r = await send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true }); if (r.exceptionDetails) return { error: r.exceptionDetails.text + ' ' + (r.exceptionDetails.exception?.description || '') }; return r.result.value; };
const waitFor = async (expr, timeout = 20000) => { const t = Date.now(); while (Date.now() - t < timeout) { const v = await evalJS(expr); if (v) return v; await wait(250); } return null; };
const shot = async name => { const r = await send('Page.captureScreenshot', { format: 'jpeg', quality: 80, fromSurface: true }); fs.writeFileSync('/tmp/opencode/shots/' + name, Buffer.from(r.data, 'base64')); };
const key = async (type, code, k, vk) => send('Input.dispatchKeyEvent', { type, code, key: k, windowsVirtualKeyCode: vk, nativeVirtualKeyCode: vk });
const report = {};

await send('Emulation.setDeviceMetricsOverride', { width: 1280, height: 800, deviceScaleFactor: 1, mobile: false });
await send('Emulation.setTouchEmulationEnabled', { enabled: false, maxTouchPoints: 1 });
await send('Page.navigate', { url: 'http://127.0.0.1:8123/?t=' + Date.now() }); await send('Page.bringToFront');
await wait(4500);

await evalJS(`(() => { document.querySelector('.mode-card[data-mode="br"]').click(); document.getElementById('btn-play').click(); return true; })()`);
await waitFor(`window.blaze.game && !window.blaze.starting`, 15000);
await wait(700);
report.start = await evalJS(`(() => { const g = window.blaze.game; return { mode: g.mode.id, phase: g.phase, introTimer: +g.introTimer.toFixed(2), dropDone: g.dropDone }; })()`);
await evalJS(`window.blaze.game.introTimer = 0`);
report.dropPhase = await waitFor(`(() => { const g = window.blaze.game; return g && g.phase === 'drop'; })()`, 6000);
await evalJS(`(() => { const g = window.blaze.game; if (!g.dropDone) g.landDrop(); document.getElementById('lock-hint')?.classList.add('hidden'); return true; })()`);
await wait(500);
report.grounded = await evalJS(`(() => { const g = window.blaze.game; return { phase: g.phase, dropDone: g.dropDone, playerMode: g.player.mode, inputEnabled: g.input.enabled,
  hud: document.getElementById('hud').className, alive: document.getElementById('hud-alive').textContent, ammo: document.getElementById('ammo-mag').textContent,
  pos: { x: +g.player.pos.x.toFixed(2), y: +g.player.pos.y.toFixed(2), z: +g.player.pos.z.toFixed(2) }, bots: g.bots.bots.length, aliveCount: g.bots.aliveCount }; })()`);

const p0 = await evalJS(`(() => { const p = window.blaze.game.player; return { x: p.pos.x, z: p.pos.z }; })()`);
await key('keyDown', 'KeyW', 'w', 87);
await wait(1400);
await key('keyUp', 'KeyW', 'w', 87);
await wait(250);
report.move = await evalJS(`(() => { const g = window.blaze.game, p = g.player; return { dist: +Math.hypot(p.pos.x - ${p0.x}, p.pos.z - ${p0.z}).toFixed(2), keyW: g.input.keys.has('KeyW'), moving: g.input.moving, phase: g.phase }; })()`);

const j0 = await evalJS(`(() => { const p = window.blaze.game.player; return { y: p.pos.y, grounded: p.grounded }; })()`);
await key('keyDown', 'Space', ' ', 32); await key('keyUp', 'Space', ' ', 32);
await wait(250);
report.jump = await evalJS(`(() => { const p = window.blaze.game.player; return { grounded: p.grounded, dy: +(p.pos.y - ${j0.y}).toFixed(3), wasGrounded: ${j0.grounded} }; })()`);
await wait(1500);

report.fireStart = await evalJS(`(() => { const g = window.blaze.game, p = g.player; p.weapon.mag = p.weapon.def.mag; g.hud.updateAmmo(); const b = { mag: p.weapon.mag, shots: p.shots, hits: p.hits }; g.input.firing = true; return b; })()`);
await wait(1800);
report.fireHeld = await evalJS(`(() => { const g = window.blaze.game, p = g.player; return { firing: g.input.firing, shots: p.shots, mag: p.weapon.mag, hud: document.getElementById('ammo-mag').textContent }; })()`);
await evalJS(`window.blaze.game.input.firing = false`);
await wait(200);
report.fireAfter = await evalJS(`(() => { const g = window.blaze.game, p = g.player; return { firing: g.input.firing, shots: p.shots, mag: p.weapon.mag, hits: p.hits, tracerCount: g.effects.tracers?.length ?? null }; })()`);

report.reloadStart = await evalJS(`(() => { const g = window.blaze.game, p = g.player; p.weapon.mag = 12; g.hud.updateAmmo(); g.player.startReload(); return { mag: p.weapon.mag, timer: +p.reloadTimer.toFixed(2) }; })()`);
const reloaded = await waitFor(`(() => { const p = window.blaze.game.player; return p.reloadTimer <= 0 && p.weapon.mag === p.weapon.def.mag; })()`, 16000);
await wait(200);
report.reloadEnd = await evalJS(`(() => { const p = window.blaze.game.player; return { complete: ${!!reloaded}, mag: p.weapon.mag, full: p.weapon.def.mag, timer: +p.reloadTimer.toFixed(2), hud: document.getElementById('ammo-mag').textContent }; })()`);

report.pause = await (async () => { await key('keyDown', 'Escape', 'Escape', 27); await key('keyUp', 'Escape', 'Escape', 27); await wait(300);
  return await evalJS(`(() => ({ paused: window.blaze.game.paused, panel: !document.getElementById('pause').classList.contains('hidden') }))()`); })();
await evalJS(`document.getElementById('btn-resume').click()`);
await wait(300);
report.resume = await evalJS(`(() => ({ paused: window.blaze.game.paused, panelHidden: document.getElementById('pause').classList.contains('hidden'), enabled: window.blaze.game.input.enabled }))()`);
await shot('final2-d-br-live.jpg');

/* tdm ground-state re-check */
await evalJS(`(() => { const g = window.blaze.game; g.endMatch(false, 'death'); return true; })()`);
await waitFor(`!document.getElementById('results').classList.contains('hidden')`, 5000);
await evalJS(`document.getElementById('btn-lobby').click()`);
await waitFor(`window.blaze.game === null`, 5000);
await wait(500);
await evalJS(`(() => { document.querySelector('.mode-card[data-mode="tdm"]').click(); document.getElementById('btn-play').click(); return true; })()`);
await waitFor(`window.blaze.game && !window.blaze.starting`, 15000);
await wait(1200);
await evalJS(`(() => { const g = window.blaze.game; if (!g.dropDone) g.landDrop(); document.getElementById('lock-hint')?.classList.add('hidden'); return true; })()`);
await wait(400);
report.tdmGround = await evalJS(`(() => { const g = window.blaze.game; return { mode: g.mode.id, phase: g.phase, dropDone: g.dropDone, playerMode: g.player.mode,
  alive: g.player.alive, hudSquad: document.getElementById('hud-squad').textContent, score: document.getElementById('obj-score').textContent.replace(/\\s+/g,' ').trim(),
  teams: g.bots.bots.reduce((a,b)=>{a[b.team]=(a[b.team]||0)+1;return a;},{}) }; })()`);
report.errors = events.filter(e => e.startsWith('exception') || e.startsWith('console.error'));
console.log(JSON.stringify(report, null, 2));
await send('Page.close'); ws.close();

