await send('Emulation.setDeviceMetricsOverride', { width: 390, height: 844, deviceScaleFactor: 1, mobile: true });
await send('Emulation.setTouchEmulationEnabled', { enabled: true, maxTouchPoints: 5 });
await send('Page.navigate', { url: 'http://127.0.0.1:8123/?t=' + Date.now() }); await send('Page.bringToFront');
await wait(4500);
const report = {};
await evalJS(`(() => { document.querySelector('.mode-card[data-mode="tdm"]').click(); document.getElementById('btn-play').click(); return true; })()`);
await waitFor(`window.blaze.game && !window.blaze.starting`, 15000);
await wait(900);
await evalJS(`(() => { const g = window.blaze.game; if (!g.dropDone) g.landDrop(); document.getElementById('lock-hint')?.classList.add('hidden'); return true; })()`);
await wait(400);
report.start = await evalJS(`(() => { const g = window.blaze.game; return { mode: g.mode.id, phase: g.phase, dropDone: g.dropDone, perf: { touch: g.input.isTouch },
  squad: document.getElementById('hud-squad').textContent, score: document.getElementById('obj-score').textContent.replace(/\\s+/g,' ').trim(), overflow: Math.max(document.body.scrollWidth, document.documentElement.scrollWidth) - innerWidth }; })()`);

await evalJS(`window.blaze.game.player.takeDamage(500, null)`);
await wait(200);
report.death = await evalJS(`(() => { const g = window.blaze.game; return { alive: g.player.alive, timer: +g.respawnTimer.toFixed(2), deadHud: document.getElementById('hud').classList.contains('dead') }; })()`);
await wait(2600);
report.deathHud = await evalJS(`(() => ({ alive: window.blaze.game.player.alive, timer: +window.blaze.game.respawnTimer.toFixed(2), deadHud: document.getElementById('hud').classList.contains('dead') }))()`);
const respawned = await waitFor(`window.blaze.game.player.alive`, 9000);
await wait(300);
report.respawn = await evalJS(`(() => { const g = window.blaze.game; return { auto: ${!!respawned}, alive: g.player.alive, hp: g.player.health, deadHud: document.getElementById('hud').classList.contains('dead'), timer: +g.respawnTimer.toFixed(2) }; })()`);

await evalJS(`(() => { const g = window.blaze.game, p = g.player; p.weapon.mag = 12; g.hud.updateAmmo(); p.startReload(); return true; })()`);
const reloaded = await waitFor(`(() => { const p = window.blaze.game.player; return p.reloadTimer <= 0 && p.weapon.mag === p.weapon.def.mag; })()`, 8000);
await wait(200);
report.reload = await evalJS(`(() => { const p = window.blaze.game.player; return { complete: ${!!reloaded}, mag: p.weapon.mag, full: p.weapon.def.mag, timer: +p.reloadTimer.toFixed(2), hud: document.getElementById('ammo-mag').textContent }; })()`);

report.fireStart = await evalJS(`(() => { const g = window.blaze.game, p = g.player; p.weapon.mag = p.weapon.def.mag; g.hud.updateAmmo(); g.input.firing = true; return { shots: p.shots, mag: p.weapon.mag }; })()`);
await wait(1100);
report.fireEnd = await evalJS(`(() => { const g = window.blaze.game, p = g.player; g.input.firing = false; return { shots: p.shots, mag: p.weapon.mag, hud: document.getElementById('ammo-mag').textContent }; })()`);
report.fireDelta = report.fireEnd.shots - report.fireStart.shots;
await shot('final3-m-tdm-live.jpg');
report.errors = events.filter(e => e.startsWith('exception') || e.startsWith('console.error'));
console.log(JSON.stringify(report, null, 2));
await send('Page.close'); ws.close();

